/* 平成14年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h14.committeeSessions.push(...[{"id":"h14-20020318-3","meetingId":"h14-c-budget","date":"2002年3月18日","dateIso":"2002-03-18","committee":"予算特別委員会","time":"午前１０時０７分～午後６時１８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を185件整理しています。","topics":[{"id":"topic-01","title":"平成１４年度品川区一般会計予算","agenda":"平成１４年度品川区一般会計予算","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"公金使用という観点とか、それから品川区の職員としての意識が非常に欠如しているという感じがするんですがどうでしょうかということが一つ。それからプラン２１をこれから具体的にやっていくに当たって、そういう公金管理のルールとか、その辺についての考え方はいかがか尋ねました。","respondent":"鷹倉庶務課長","answer":"それとあわせて、区費の部分、今、若干おりますけれども、その部分との連携という形で若干不慣れな部分もある。こういうふうにしていったらどうかというようなことを今考えていますし、やりつつあるところであるです。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、一つの考え方をお聞かせください。お願いいたします。","respondent":"青木指導課長","answer":"私どもは、現在品川区が取り組んでいる内容なども含めて、品川区の教員であるという意識を強く意識づけるように研修をしています。それぞれの学校の教育のみならず、そうした管理面でも強く意識させるように指導してまいりたいというふうに考えております。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問・要望","question":"職員の防災待機寮があいているわけですから、そういうやる気のある教員、それから優秀な職員を全国から募集すべきと思います。いろいろ弊害はあるかと思うんですけれども、その辺についての考え方と、それから対応もお聞かせほしいと求めましたが、いかがか尋ねました。","respondent":"青木指導課長","answer":"やはりほかの地区、ほかの県から受験して東京都の教育、品川の教育にぜひ尽力したいという人も私はいるというふうに考えております。そうした形でいろいろな地区、ますますこれからの教育改革にそうした方たちの力を私たちは使っていきたいというふうに考えております。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"提案","question":"私たちの提案としては、もっともっとプラン２１のことを真剣に考えていくんだったらば、お願いいたしますとの意見を述べました。","respondent":"指田教育次長","answer":"こういう問題点があるということは直接訴えていかないと、やはり都教委や何かを含めて動かすことはなかなかできないと考えています。今後も、機会あるごとに問題点については対応していきたい、お話ししていきたいというふうに思っています。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"提案","question":"そういうような最もベースをやはりこの５日制の中で構築していくと同時に、私たちの提案としては、いろいろな団体があります。小学校、中学校での必要な学力を身につけていく方向で考えていくべきと思うんですが、見解はいかがか尋ねました。","respondent":"青木指導課長","answer":"いよいよ４月から完全学校週５日制が実施されます。それから地域の力をまさに連携、学校とともに連携して学力だけではない、そうした力を育てていきたいというふうに考えているところです。","id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問","question":"それぞれの人材を抱えているわけですから、こういうようなものがあるから、こういうことをセットできますよと。どういうふうなメニューがありますよ、私はいいと思いますが、答弁はいかがか尋ねました。","respondent":"青木指導課長","answer":"現在、それぞれの地域やＰＴＡの活動が一つ、情報としてまとめられるような形で、これから私たちは収集し、そして準備をしていかなければいけないというふうに考えておりますので、その点につきましては至急検討して対応してまいりたいというふうに考えております。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ＰＴＡだけじゃなくて、私が言ったのは、区のある、各事業部のそれぞれの人材がいるでしょう、地域に。ここで有効活用するためにスキームがつくれないんですかということを聞きましたので、それから、議員もそれぞれの人脈を持っているわけですから。","respondent":"青木指導課長","answer":"今は、ＰＴＡということだけでありましたけれども、確かに、これからは地域が子どもを育てるということが強く出されてまいります。そういう意味で、子どもたちの土曜日を使った、まさに生きる力の育成に町内の力を合わせて進めていきたいというふうに考えております。","id":"exchange-007"},{"speaker":"嶋委員","kind":"質問・要望","question":"初めに完全学校週５日制の実施について、二つ目には３０３ページの生徒指導対策費に当たるのかどうか、金銭教育についてお伺いをいたします。６６％の学校では学習内容を削減しないという、５日制を無視しているとか、お答えをちょっとお聞かせほしいと求めました。","respondent":"富田教育改革担当課長、青木指導課長","answer":"３校新規に１４年度は実施するという方向を出したわけですが、今後の予定ですけれども、ちょっと最終の予定等につきましては今後検討してまいりたいというように考えております。 学力低下についてのお尋ねですが、私どもは、基礎・基本を徹底的に教えるということにポイントを置いて指導していきたいというふうに考えております。基礎・基本を徹底的に指導していく…","id":"exchange-008"},{"speaker":"嶋委員","kind":"確認","question":"３時間程度、１クラス２０人程度で授業の補充として国語、英語などを勉強する。そういう意味では、ほんとに５日制にする意義というか、内容をもう一度はっきり確認したいと思いますので、もう一度お話をいただけますか尋ねました。","respondent":"青木指導課長","answer":"５日制の意義につきましては、家庭で培われる、まさに生きる力を育てていきたいという本来の趣旨があります。やはり学習内容が減らされたというようなご認識で、指導方法を工夫して、子どもたちの学力を定着させていきたいというふうに考えております。","id":"exchange-009"},{"speaker":"嶋委員","kind":"質問","question":"そういう意味で、品川区として子どもたちに５日制に対するアンケートをとられたのかどうか、もし内容……。家族と買い物や旅行３７％、家で学習する３５％と、品川区においてはどのようにこれを実施されていますか尋ねました。","respondent":"青木指導課長","answer":"品川区としてはとってございませんが、それぞれの学校で、子どもたちと接している教員が子どもたちのそうした心情を酌み取っているところです。私たちもそうしたことを、報告を受けておりますので、そうした子どもの実態というのは把握しています。","id":"exchange-010"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひまた何かの機会にとってほしいと求めました。品川区としてはケーブルテレビにどのような働きをかけて、もしこれをアピールしたい番組がありましたら教えてほしいと求めました。","respondent":"青木指導課長、山田広報広聴課長","answer":"ケーブルテレビのほうの内容ですけれども、今広報広聴課長がまいりましたので、かわりたいと思います。 来年度は中学校の放映ということを準備しております。すまいるスクールも大変好評ですので、特別番組なりで教育改革ということで取り上げたいというふうに、今準備をしています。","id":"exchange-011"},{"speaker":"嶋委員","kind":"質問・要望","question":"最後に、金銭教育についてお伺いをさせてほしいと求めました。お金の使い方がどういう形で、きっと遠足とか修学旅行かと思いますが、どういうようなときにこういう教育をされているのかお聞きしたいと思います。","respondent":"青木指導課長","answer":"今お話にもありましたように、お小遣いを持って出かける、そうした修学旅行や移動教室といった場面でも指導をすることになっております。大分いろいろと問題が出ておりますので、やはりそうした場をとらえて、きめの細かい指導をしていきたいというふうに考えております。","id":"exchange-012"},{"speaker":"嶋委員","kind":"質問","question":"先に使って、後から目に見えないお金として、そういうカードが使われております。こういうものをやっぱりしっかりとした時間をとって、学校、教育現場では教育をしていってほしいなと思いますが、いかがか尋ねました。","respondent":"青木指導課長","answer":"家庭科では身の回りの物や金銭の計画的な使い方を考え、適切に買い物ができるようにするという、こういう目標を持って指導をしている場面もあります。金融、金銭にかかわるそうした対応能力というものをそれぞれの学年…","id":"exchange-013"},{"speaker":"嶋委員","kind":"質問","question":"児童に対してでもいいんですけれども、そういうのを今までやったことがあるのでしょうか、ちょっとお聞きしたいと思います。","respondent":"青木指導課長","answer":"金銭面にかかわっては、保護者会などを通じて、家庭でもやはりきちんと指導していただきたいというようなこともよく指導しています。学校だけではできませんので、学校と家庭の連携を通して、金銭教育を充実させていきたいというふうに考えております。","id":"exchange-014"},{"speaker":"嶋委員","kind":"質問・要望","question":"お金でできるもの、できないものをしっかりと、やっぱり子どもたちに小さいころから教育をしていただきたい。できないものを明確にし、上手にお金の使い方を教えてほしいと求めましたが、いかがか尋ねました。","respondent":"青木指導課長","answer":"そうした学級指導ですとか、さまざまな場面で金銭の扱いについては指導してまいりましたし、今後も充実させていきたいと思います。認識、今後も家庭と連携をとりながら、指導してまいりたいというふうに考えております。","id":"exchange-015"},{"speaker":"嶋委員","kind":"質問","question":"これからもする予定がないのかどうか。絶好のチャンスだと思いますが、いかがか尋ねました。","respondent":"上川内生涯学習課長","answer":"１４年度から乳幼児を持つ親の子育て若葉マーク講座ということで、就学前の子育てに関する相談、それを児童センターの幼児クラブ等を中心にして行っていくことに計画をしております。","id":"exchange-016"},{"speaker":"嶋委員","kind":"質問","question":"児童センターではなくて、学校の就学時健診ということで、今ちょっとお聞きをしたのですが。","respondent":"上川内生涯学習課長","answer":"就学時健診というところでは今後検討してまいりますが、その前の段階のところではそういう予定を組んでおります。","id":"exchange-017"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひよろしくお願いをしたいと思います。それとあと子育てに関する地域のネットワークづくり交流２回ということなので、済みません、教えてほしいと求めました。","respondent":"上川内生涯学習課長","answer":"それで支援交流を今回も行いました。子どもの年齢区分講習ということで、主に思春期の部分と、それから小学生の中学年のギャングエージの部分に分けまして全８回組んでおります。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この内容についてちょっと教えていただきたいのと、当初改修費で２,０００万円、割合で教えていただけたらわかりやすいと思います。私はぜひクーラーをつけてほしいなと思うので、その辺どうなっているのかなというのはお尋ねと、その辺を教えていただきたいなと思います。","respondent":"富田教育改革担当課長","answer":"４室ございまして、新規開設予定の学校はいずれも児童数が３００人程度の学校でございまして、最低３教室は確保したいというふうに考えております。夏休みずっと開設する予定ですので、現在第二延山もクーラーを設置していますし…","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その点が１点と、ぜひはっきりとお答えいただきたいのと、改めてはっきりお返事をいただきたいなと思います。人数もお願いします。","respondent":"富田教育改革担当課長","answer":"平成１２年度から実施されている事業ですので、この辺、ちょっとその辺は区単独でどうこうということはできませんので調整してまいりたいと思います。教員免許のある非常勤職員２名配置の予定ですが、勉強、学習面の指導に当たる部分ということで考えております。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"確認","question":"クーラーのことは、ちょっともう一回しつこいんですけれども、第二延山のすまいるスクールには既にあるという確認はいいのでしょうか。改めてちょっとそこが確認と、あと職員体制のところなんですけれども、人数はわかりました。","respondent":"富田教育改革担当課長","answer":"１３年度も教員免許のある部分については入れておりまして、指導助手と同じ単価、時給１,６００円ということで算定しております。指導補助員については今後決定してまいります。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"次に活動内容についてお伺いをしますけれども、安全確認、お伺いします。一緒に過ごしたいというのは、これは当然の要求と思いますけれども、障害を持ったお子さんたちの受け入れの体制がどうなのかお伺いをいたします。","respondent":"富田教育改革担当課長","answer":"大変非常勤職員等と力を合わせながら実施運営してございまして、学校の校長先生、専任職員１名で大丈夫だというふうに認識しております。付き添いが必要なお子さんの受け入れにつきましては、保護者の方が付き添うとか、すまいるスクールの基本であるというふうに考えております。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"提案","question":"安全確認のところですけれども、連絡帳がどう使われているのかというところをちょっとお伺いします。子どもを伝える中身にもうちょっと充実をしていただきたいのと、すまいるの保護者会の開催を提案したいんですけれども、いかがか尋ねました。","respondent":"富田教育改革担当課長","answer":"すまいるで起きたようなできごと、親御さんに連絡が必要であるものにつきましては親御さんのほうに電話連絡するなり、適宜対応しています。すまいるスクールのほうでは説明会を開いておりまして、来年度すまいるスクール参加予定の方のための説明会も、３月中に開催する予定です。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この点をぜひ考慮して、考えていっていただきたいなと思います。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"原委員","kind":"質問・要望","question":"私のほうから、プラン２１関連事業の部分について、基本的な部分の再確認をさせてほしいと求めました。現実の問題として、土曜、日曜の対応は何か具体的なものが出ているんか尋ねました。","respondent":"青木指導課長","answer":"第１点目の学校週５日制の完全実施に伴い、まず、授業時数がどのくらい減るかというところからご説明させていただきたいと思います。１点目でご説明しましたように、２年間にわたりまして移行措置ということで、新学習指導要領の完全実施に向けた形での準備をしてきております。","id":"exchange-025"},{"speaker":"原委員","kind":"質問・要望","question":"要するに自然派と言ったらよろしんですかね、品川区は生きる力、すなわちゆとりというところを重点に今回プラン２１を組み立てていますね。先ほどのお話のように、ゆとりの中に、学力をどう取り込んでいくかというところについて何かお考えがあるようでしたら教えてほしいと求めました。","respondent":"上川内生涯学習課長、青木指導課長","answer":"学校支援ボランティアの話が出ましたが、学校支援ボランティア、登録している方が２８７名おります。それから１４年度から土曜日が全部お休みになるということで、校庭開放を全土曜日実施することになっております。 例えば、習熟度別学習とか、教科担任制とか、そうした方法で取り組む中で、学力の基本的な定着というのを図ってまいりたいというふうに考えています。やっぱり問題解決能力というような意味での学力も含めて…","id":"exchange-026"},{"speaker":"原委員","kind":"質問","question":"過度の塾通いはその機会を失うことなのであるが、子どもを塾に通わせるかどうかは親の、家庭の決めることだけれどもというようなことがついています。ここの塾、あるいは補習等々については、教育委員会としてはどういうご見解をお持ちか尋ねました。","respondent":"青木指導課長","answer":"学校週５日制が実施されることによって、学校週５日制が実施されることによって、通塾率が伸びたというようなデータは持ってございません。学校としては、基礎・基本の定着ということを目指して、今後も指導してまいりたいというふうに思っています。","id":"exchange-027"},{"speaker":"原委員","kind":"質問・要望","question":"その辺のところは、学校のほうから、学校と家庭との風通しをひとつよくしてお話をしていただければというふうに思っております。学力調査の件でちょっとお話をお伺いさせていただきたいんですが、表現力、お考えを聞かせてください。","respondent":"青木指導課長","answer":"この学力調査のねらいですが、私ども今、プラン２１を進めております。したがいまして、まず実態を把握し、そしてその結果それを指導法につなげる、そうしたねらいで行いたいというふうに考えております。","id":"exchange-028"},{"speaker":"原委員","kind":"意見","question":"そうしますと、今の考え方からすると、それでは、ここにも出ていますね、習熟度別学習というところに、学力の内容、今お話されたようなことをどうリンクさせていこうとしているかということなんですがとの意見を述べました。","respondent":"青木指導課長","answer":"それぞれの取り組みが成果として出ているのかというようなことも含めて分析をし、それを今後の指導法の改善につなげていきたいと思っています。そうした意味で、習熟度別の指導も一つの方法として…","id":"exchange-029"},{"speaker":"原委員","kind":"意見","question":"その温度差をなるべく小さくして、しかも学力向上につなげるという努力をしなければならない。いい先生にいい形で品川区に来ていただいて、そこのところの習熟度別学習の内容と学力の向上について、もう少しお考えがあったら説明を求めました。","respondent":"青木指導課長","answer":"そういう意味で、個に応じた指導ということが前提になりますので、なかなか理解が十分にできないお子さんにとっては時間をかけてやります。そうした意味で学力の定着ということを考えますと、大変有効な指導法ではないかなというふうに考えております。","id":"exchange-030"},{"speaker":"原委員","kind":"質問・要望","question":"しかも実のあるものにしていただくのがプラン２１の最大の目的だろうと思いますので、よろしくお願いします。足りないところはうちのほうの会派の中で、プラン２１関連、出てくると思いますが、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"鶴委員","kind":"意見","question":"学力低下は大丈夫かと心配している１人なんですが、教育委員会、品川区の教育委員会としての基礎学力に対する見解というのはどういうことなのか。そして今、品川区の子どもたち、児童たちはどういう基礎学力のレベルにあるのか、ちょっとお知らせいただけませんかとの意見を述べました。","respondent":"若月教育長","answer":"今日は時間の関係でご説明できませんので、まあ、中学校から高等学校に進んでいく一つの受験というステップがあります。全国、そして東京都のレベルから見ても、その平均レベルより劣るものではないというふうに認識をしています。","id":"exchange-032"},{"speaker":"鶴委員","kind":"質問","question":"まあ、統一的押しつけはいけないけれども、あるレベルというものが必要じゃないですか。あいまいもことしている中で任せっぱなしでやるんか尋ねました。","respondent":"若月教育長","answer":"それに基づいて各学校が指導もしておりますし、教員はそれに基づいたさまざまな測定方法、テストなどを用いて、基礎学力の定着度をはかっている。基本は学習指導要領にあるというふうにご理解ください。","id":"exchange-033"},{"speaker":"鶴委員","kind":"質問","question":"それじゃ、時間がないから１点聞きますが、今の小・中学校の品川区の児童の国語力というのはどうですか、読み書き含めて。全部１００点満点とれますか。","respondent":"若月教育長","answer":"これは、全部１００点をとれるかと言われると、これは無理であります。今子どもが持っているこの段階で、そういう部分もやはり我々教師は見ていってあげなければならないだろう、こんなふうに考えているところです。","id":"exchange-034"},{"speaker":"本田委員","kind":"意見","question":"それから３３１ページの図書館経費の中で、乳幼児の図書普及、読書普及ですね、これに関してお尋ねします。１学校３台くらいあるような計算になるんですが、この維持管理というのはどのようにされているのか、まずお尋ねしたいと思いますとの意見を述べました。","respondent":"久保田学務課長","answer":"私どもは年間を通じて委託契約しておりまして、年間に数回学校を訪れて、調律の状況を見ながら不十分なところがあれば若干直していくというような態勢をとっているところです。","id":"exchange-035"},{"speaker":"本田委員","kind":"質問","question":"素人ですから、１８０台のピアノというのは、一番古いのでどのくらいもっているんでしょうか。予算の中でも年２回の調律予算が入っておりますけれども、実態としてはどうなっているのか、お聞きしたいと思います。","respondent":"久保田学務課長","answer":"確か記憶では１０年ぐらいは、一番古いので、使っているんではないかなと考えています。そういう報告を受けて、また新しく老朽取りかえというような考えも出てきますし、そういう形で業者との連携はやっているところです。","id":"exchange-036"},{"speaker":"本田委員","kind":"質問","question":"古いもので１０年というと、新しいピアノが１８０台も品川区の小・中学校にそろっているんですか。もっと、２０年とか３０年とかたっているんじゃないか尋ねました。","respondent":"久保田学務課長","answer":"一番古いのということでいきますと、昭和５８年ということですから２０年はまだたっていないというような状況です。もう使えないというような報告はないんですが、やはりそろそろ古いもので使えなくなくものが出てくるのかなというふうな印象は持っているところです。","id":"exchange-037"},{"speaker":"本田委員","kind":"質問・要望","question":"車１台を買うぐらいの値段じゃないですか。父兄の中にはいろいろな方がおられるわけでして、たまたま聞く機会があったんだそうですけれども、もう一度お尋ねします。","respondent":"久保田学務課長","answer":"私、ちょっと見間違えまして、４８年が一番古いほうで、申しわけありません。やはり必要な取りかえなり、あるいは修繕というのは十分に行っていきたいと、こんなふうに考えております。","id":"exchange-038"},{"speaker":"本田委員","kind":"提案","question":"お尋ねするごとに１０年ずつ延びて、どうも教育委員会のほうは教材教具、ここはきちっとしてほしいんですね。２,０００人の１歳半健診時にお子さんたちに、一定の予算がなければこれはできないと思うんですけれども、どういうふうになっているんか尋ねました。","respondent":"青山品川区保健センター所長","answer":"実は、保健所のほうで図書館の者が参って、１歳半健診のときに約１０分間ずつ話をしてくれているんですが、それについては特に予算というものではなく、職員が来てくれているという状況です。","id":"exchange-039"},{"speaker":"本田委員","kind":"質問","question":"これは一体どういうことになっているんでしょうか。保健所と連携してやっているというんですが、荏原のほうとはやっているけれども、保健センターとはやっていないということなんか尋ねました。","respondent":"青山品川区保健センター所長","answer":"実は保健所、旧荏原保健所に対しては図書館の職員が参ってやっているんですが、保健センターのほうではこれまでやってきておりません。絵本をたくさん置いておきまして、そこで保護者の方や関係する者が読み聞かせができるような態勢をとるという形で変わらせていただいておりま…","id":"exchange-040"},{"speaker":"本田委員","kind":"提案","question":"私は、４カ月の健診のときに絵本の大切さを教えてやるというブックスタートが、こういうやり方をどうでしょうかということを昨年提案したんですが。荏原のほうはやっているけれども、品川のほうはやっていないというようなお話ですが、これはまずいんじゃないか尋ねました。","respondent":"志村品川図書館長","answer":"１歳６カ月健診については今答弁したとおり、品川区保健所になっていますけれども、そちらで今やってあります。ですので、その機会をとらえて普及を図っているというのもあります。","id":"exchange-041"},{"speaker":"本間委員","kind":"質問","question":"子どもたちに週末をどう過ごさせるか、完全学校週５日制の実施を４月に控え、そのデータが出ております。この件につきましてのご見解をお尋ねします。","respondent":"上川内生涯学習課長","answer":"週５日制になって、それから保護者で交流事業を促進していこうということで、これから展開してまいります。","id":"exchange-042"},{"speaker":"本間委員","kind":"質問","question":"完全学校週５日制ということにつきまして、私立との差に加えて地方自治体でも学力に差が生じるのではないかという懸念する声が上がっています。説明を求めました。","respondent":"久保田学務課長、青木指導課長","answer":"それから平成１３年度が１６.６％、平成１４年度にまいりますと、これはまだ見込みですけれども１８.１％になるかと思います。それから中学校についてですが、平成１３年度が２４％… 教員のほうの異動の件ですが、これもせんだっての本会議でもご答弁させていただきましたように、確かに今、品川区は教育改革を進めております。そうした教育改革に意欲のある教員と負担に感ずる教員と、それが如実に出てきた…","id":"exchange-043"},{"speaker":"本間委員","kind":"質問","question":"一緒にどうぞトイレを使ってくださいということで、ほんとに見違えるほどよくなっている姿を目の当たりに見させていただきました。小学校、中学校、お願いします。","respondent":"鷹倉庶務課長","answer":"このときの基本的な考え方ですけれども、それは３０年代、４０年代に集中していると。現在のところ３０校程度未実施ですけれども、今申し上げました意味ではＲＣ構造上、まあまあ大丈夫かなという見通しを持った形で残していると。","id":"exchange-044"},{"speaker":"本間委員","kind":"質問","question":"耐震構造をクリアしていないところについては、屋上緑化の話はなかなか前向きな受けとめ方をされないわけでして、その辺も実はお聞きしたわけです。したがいまして、これからの見通しについてお尋ねします。","respondent":"鷹倉庶務課長","answer":"これは当然のことです。従来のところを屋上緑化していく場合について、今ご指摘の耐震補強をしている部分、この辺のところを見きわめながら、屋上緑化をしていくです。","id":"exchange-045"},{"speaker":"本間委員","kind":"質問・要望","question":"前提となる施設がばらばらではやはりいい施設のほうに目が向くんじゃないかという心配が実はいつもされるものですから、最低の、校庭の部分だとか。もしあるとしたら、どれくらいありましょうか。","respondent":"鷹倉庶務課長","answer":"具体的には学校でできないのは浜川中、１校です。ここは３,７００m2ということで、ちょっと若干狭いのと、海浜公園が使いやすいこともございまして、ここ１校使用しています。","id":"exchange-046"},{"speaker":"本間委員","kind":"質問・要望","question":"そうしたら、その次は便宜を図っていただきたいということになりますが、これからもひとつよろしくお願いします。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それと２項で学校教育費の教職員健康管理費、それと３項で区立小学校ＰＴＡ連合会、その辺についてお聞きしたいと思います。参加者は区内全域、平均化していらっしゃるのかどうか、その辺についてお答えをお願いしたいと思います。","respondent":"上川内生涯学習課長","answer":"それから中学・高校生コースが１会場で２７名。区内全域の小・中学生を集めて実施しております。","id":"exchange-048"},{"speaker":"鈴木（真）委員","kind":"意見","question":"わかりました。どのように区の中でいろいろな協力体制をとっていらっしゃるのか、有効に生かしていらっしゃるのかを、ちょっとお答えいただけますかとの意見を述べました。","respondent":"上川内生涯学習課長","answer":"高校３年生を卒業した方たちを主に対象としまして、お姉さんという立場で、カウンセラーという形で活躍していただいております。","id":"exchange-049"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"殊にキャンプなどですと、そういう、体験した方たちを全然生かしていないような状況が今見えていると思います。その辺で、事業部の間でどうつながりを持って考えていらっしゃるのか、その辺をお答えほしいと求めました。","respondent":"上川内生涯学習課長","answer":"今小学校４年生からというふうになっていますけれども、ジュニア・リーダーのカウンセラーとして入ってくるという状況にあります。それからキャンプとか、青少年委員とともに行動するような形で、さまざまなボランティアのところに参加しているというような状況です。","id":"exchange-050"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ですからこの中でも、青少年委員の方は当然青少年対策地区委員会の方なんですから、今後の活用をお願いしたいということで要望にします。じゃ、それでちょっとお答えをお願いします。","respondent":"長田地域活動課長","answer":"そういう意味からすれば、当然青少年委員会で実施をした事業、十分調整をして生かしていただくということは原則かと思います。目下の最重点課題として取り組んでいますので、今後事業運営の中に生かしていきたいと、このように考えてあります。","id":"exchange-051"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"３人、お会いしたのは３人だったので、予算面で見ると生涯学習関係になるんですか。この中で研修会と学校の関係というのはどういうふうになってくるんか尋ねました。","respondent":"上川内生涯学習課長","answer":"ＰＴＡ研修会につきましては、小学校、中学校のＰＴＡ連合会への委託事業という形になっております。１年の成果として研究発表大会というふうにしておりまして、当然親御さんとそれから先生方と、学校側と一緒になって行うという事業です。","id":"exchange-052"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そこからお聞きしたいんですが、この日、七つのブロックに分かれてかなりきちんとした研究発表をなさっていらっしゃいました。教頭先生、それから逆に一般の先生方がどの程度こういうときに見えているのかなというのが、数字的なものはある程度わかりますか尋ねました。","respondent":"上川内生涯学習課長","answer":"校長先生と教頭先生と、ちょっと区分けはしていないんですが５７名。それから一般の先生のほうは２名ということで、あとは親御さんということです。","id":"exchange-053"},{"speaker":"鈴木（真）委員","kind":"意見","question":"先生の２名というのが非常に疑問に思ってならないです。学校が地域や保護者の方との開かれた学校ということでやっているのに、何で学校の先生って協力度がないのかなという気がちょっとしますとの意見を述べました。","respondent":"青木指導課長","answer":"学校からは代表の校長が行けばいいのではないかというような認識が学校にはあったのかというふうに私は受けとめています。私も今後、まだまだ認識がそこまでいっていませんので、ぜひ親御さんたちの研究の内容を実際に見てほしいなというふうにも思っております。","id":"exchange-054"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ただ、せっかく、今おっしゃったように、学校とＰＴＡの方で一生懸命やっているのに、もうちょっと協力をしていただきたいなという思いがあります。さっき予算書を見ていて、前回結核検診を受けていない方が４０人ぐらいいらしゃるというお答えがあったと思うんですが、進展しているんか尋ねました。","respondent":"鷹倉庶務課長","answer":"その時点では、その後各学校に残っておられる方について、個別に人間ドック等を受けていただくようにといった形で文書等で指導いたしました。そして逐次追跡調査していますけれども、現在のところほぼ１００％になっていると、こういう状況です。","id":"exchange-055"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"学校の関係でもう一点続けてお聞きしますが、去年６月の大阪での池田小学校事件。その中であのときに、学校安全対策委員会が各学校で設置されたと思うんですが、これの運営状況というのは今もずっと続いているんか尋ねました。","respondent":"青木指導課長","answer":"現状では安全対策委員会、実際に既にもう７回を迎えているような学校もありますが、残念ながら事件後１回で済んでしまっているという学校もあります。私どもはそれぞれの学校の取り組みを把握しながら、とりわけ年度があけましたら…","id":"exchange-056"},{"speaker":"鈴木（真）委員","kind":"質問","question":"７回もやっていらっしゃるという、あるところでお聞きしたところ、ほとんど実施されていない現状が強いということを聞きました。どういう対応をしたらいいのか、そういう訓練みたいなものも、先生方の中でそういう訓練というのは実施していらっしゃるんか尋ねました。","respondent":"鷹倉庶務課長","answer":"学校１１０番という形で設置したものです。基本的には学校が判断して押せばいいということになってありますので、そういう形で指導し、いろいろ学校で対応しています。","id":"exchange-057"},{"speaker":"鈴木（真）委員","kind":"質問","question":"システムだけでなく、何かあったとき、じゃ、先生方はどういうふうに動いたらいいんだというような、そういう訓練というのは特別にはなさっていらっしゃらないんか尋ねました。","respondent":"鷹倉庶務課長","answer":"各学校で、それぞれ押し方だとかという形で……、じゃなくて、学校１１０番につきましては、具体的な対応はしていないと思いますけれども。","id":"exchange-058"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ちょっと内容が違ったんですけれども、もし、そういう事件が発生したときに、先生方が生徒をどのように誘導していって、どうしたらいいということを検討していらっしゃって、そういう訓練は実際に何か考えていらっしゃるのかということ、そっちのほうなんですけれどもとの意見を述べました。","respondent":"青木指導課長","answer":"既に校内では避難訓練というような形で訓練をしています。私たちの主催しております生活指導主任会の中でも、こうした避難訓練などの情報交換をしています。","id":"exchange-059"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もうちょっとお聞きしたいんですが、私も何校かお邪魔して先生に聞いたときに、あき教室がないというケースにかなりぶつかっているんですね。その辺を考えていった場合に、現実論としてどういうふうに対応していくのかなというのが、疑問があるんですが。","respondent":"富田教育改革担当課長","answer":"ご指摘のすまいるスクール拡大にあたっての施設面での問題ですけれども、大変あき教室が少ない学校があるということは承知しております。これまで展開しているような形ではなく、例えば平日の午後にはどこまでできるのか、その点も含めて今後検討してまいりたいと考えております。","id":"exchange-060"},{"speaker":"鈴木（真）委員","kind":"質問","question":"屋上緑化をやっていくケースと、学校改築との兼ね合いとか、そこら辺はどうなっているんか尋ねました。","respondent":"鷹倉庶務課長","answer":"総合的に判断して代表質問等でお答えしていますけれども、学校を決めていきたいと、このように考えてあります。","id":"exchange-061"},{"speaker":"鈴木（真）委員","kind":"意見","question":"５日制になっていったときに、個性を生かしたというところがどうなってくるのかなというのと、そこら辺の兼ね合いについてお答えをお願いしたいと思いますとの意見を述べました。","respondent":"富田教育改革担当課長","answer":"いわゆるさまざまな教室の展開についてだと思いますけれども、やはり親御さんなどの希望の多い英会話とかパソコンなどはベースにしたいと考えていますが、あとは各学校また地域の方々でボランティアをしてくださる方との関係等々調整しながら検討してまいりたいと考えています。","id":"exchange-062"},{"speaker":"山路委員","kind":"質問","question":"３点目は、３２３ページ、パソコン教室についてお伺いいたします。どのようなコンピューター授業等の技能の向上を目指していくのか、その点についてお伺いをいたします。","respondent":"青木指導課長","answer":"私ども、この情報活用能力ということは、まず３点のところでとらえております。２点目は情報の科学的な理解に努める、先ほど委員がご指摘されました情報モラルの必要性等についても指導していきたいというふうに考えております。","id":"exchange-063"},{"speaker":"山路委員","kind":"質問","question":"現状の教育内容をお聞きした感じがいたしますけれども、その中で主体的に活用する認識についての教えはどういうふうにされているか、もう一度お願いします。","respondent":"青木指導課長","answer":"先ほど３点のポイントで指導をしているということでご説明させていただきましたけれども、表現や処理、そうした力をつけるような指導をしています。先ほど３点目にお示ししました情報社会に参画するという…","id":"exchange-064"},{"speaker":"山路委員","kind":"質問","question":"４枚から１０枚程度におさめ、色を２種類以上使い、マイホームページをつくるというようなことをやっているということなんです。そういうものに対しての検討をして、大きな技能資質の向上に役立つものの一つであるかと思いますが、どのようにお考えか尋ねました。","respondent":"青木指導課長","answer":"今、そういう意味でのコンピューターの使い方を考えておりますので、今コンピューターを使って指導をしているところではございません。私どもは情報手段の活用というところで、コンピューターを使いたいというふうに考えております。","id":"exchange-065"},{"speaker":"山路委員","kind":"質問・要望","question":"１級から９級まで段階がありますので、レベルアップのために、ぜひ研究はしてほしいと求めました。もう一点、特に平成１４年度からの情報倫理教育ということが言われておりますが、どういう指導をされていくのかをお伺いいたします。","respondent":"青木指導課長","answer":"情報倫理ですが、先ほども情報化社会に参画するためには、基本的な態度というものを育成する必要があるというご説明をさせていただきました。技術家庭の時間に、実際に学習内容にはあるんですが、こうしたことについても指導していきたいというふうに考えております。","id":"exchange-066"},{"speaker":"山路委員","kind":"質問","question":"先ほどの情報倫理ですが、人という関係性が薄れてくるのじゃないかということ、そういうものを大事に考えての情報機器の活用ですね。人の大事さの中に手段があるですけれども、この辺は現場で日常、どういうふうに指導されているかお伺いいたします。","respondent":"青木指導課長","answer":"まさにこれからの情報化社会はコンピューターが発達してそれを人間が使うという立場から、人間の主体性が問われてくる時代でもあります。先ほども申しましたように、道具としての認識を持って、きちんと整理して指導に当たっていきたいというふうに考えております。","id":"exchange-067"},{"speaker":"山路委員","kind":"質問","question":"どうぞ日常の教えの視点をはずさないようによろしくお願いいたします。続きまして、Ｅメールの活用について現在どのような活用をされていくかお伺いいたします。","respondent":"青木指導課長","answer":"今後の課題にはなってくるかと思いますが、実際に国際交流ということで、アメリカとＥメールのやりとりをするというような報告もあります。これからの課題かなというふうに考えてあります。","id":"exchange-068"},{"speaker":"山路委員","kind":"質問","question":"Ｅメール活用については、情報収集とか、提供とかいろいろな形で利用の方法はあるかと思います。すぐというわけにはいきませんけれども、研究の価値があるんじゃないかと思いますが、どのようにお考えか尋ねました。","respondent":"青木指導課長","answer":"メールを使って、実際に廊下に張ってあったり、直接校長室に子どもが自分の作品を持っていったりというようなことはあります。メールを使ってのやりとりについては今後の課題かなというふうに考えてあります。","id":"exchange-069"},{"speaker":"山路委員","kind":"提案","question":"Ｅメール大賞とかを新しく考えてはどうでしょうかという、これはご提案ですけれども、どうぞ研究をしてほしいと求めました。１３年度、どういう事業に変えられるのか、お伺いいたしますとの意見を述べました。","respondent":"上川内生涯学習課長","answer":"生涯学習関係では６,０００人、それから学校を含めまして約６,０００人、当課で実施しております。それの復習、エクセルの分を新たに組み入れるということでパソコン教室２０回、１回２０人定員で実施したいと思っているところです。","id":"exchange-070"},{"speaker":"山路委員","kind":"質問","question":"本年も１授業、１講習会ぐらいは必要じゃないかと私は思うんですけれども、この辺についてはどのように検討されたんか尋ねました。","respondent":"上川内生涯学習課長","answer":"１４年度に向けて２３区の中で実施したいところがあれば手を挙げるようにということで、品川区としましてもこれから申請をするところです。１３年度全体で約３０講座程度を申請していく予定にしています。","id":"exchange-071"},{"speaker":"山路委員","kind":"質問","question":"もう一点ですけれども、外国人の方の参加については１３年度はどうだったんでしょうか。外国人の方が参加していなかったら、新たに外国人の方の講習会というのも１４年度は考えてもいいんじゃないかと思いますが、どうお考えか尋ねました。","respondent":"上川内生涯学習課長","answer":"外国人の方につきましては、今までの中で外国人というところで集計はしてございませんでしたので、外国籍の方も入っていたと思いますので、今後はその辺、どのような需要があるのか研究させていただきたいと思います。","id":"exchange-072"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほど来より出ている新学習指導要領のもとでの週５日制等々に絡んで、その件につきましてお伺いをしたいと思います。これまでの経過等々はお伺いしましたが、１４年度においての、そういう対象者はどういう方を想定されていらっしゃるんか尋ねました。","respondent":"上川内生涯学習課長","answer":"１３年度に実施しました年代を見てみますと、５０代、６０代の方が５０％以上いらっしゃいます。最高齢８８歳という方もいらっしゃいますし、今年度は生涯学習課も、今年度は特にその辺を中心にＰＲをして実施していきたいと考えています。","id":"exchange-073"},{"speaker":"田中委員","kind":"質問・要望","question":"全国的な計画がある中で、検討をということなんですが、これからさらにますますシステム化というのはさまざまな面で進行してこようかと思います。そういう懸念というんでしょうか、継続的な事業としてぜひとらえていただきたいと思っているんですが、その点ではいかがか尋ねました。","respondent":"上川内生涯学習課長","answer":"国の補助の対象ということでは１４年のところまでしかわかりませんが、シルバー大学のうるおい塾ですとか、そういうところでもこれからやっていくようになると思いますので、そういうところで検討させていただきたいと思います。","id":"exchange-074"},{"speaker":"田中委員","kind":"質問・要望","question":"ステップ１からステップ３に向けて、評価基準が１から６までありますが、この中の５番目に公平性という評価基準があります。当該事業の便益や負担が公平に配分されているかどうかという観点でチェックするということと、どのようにお考えなんか尋ねました。","respondent":"田中情報システム課長","answer":"ＩＴ講習会の中では障害者対応の講習会等を行っています。いろいろアンバランスがありますので、それに対応したような公開端末の配備ですとかを含めまして、十分検討していきたいというふうに考えております。","id":"exchange-075"},{"speaker":"田中委員","kind":"質問・要望","question":"高齢者あるいは障害者ではなく、ぜひこれは恒常的な政策として取り組んでいただけたらということの要望をします。小学校、そういう意味からの不安をまだぬぐい切れないところがあるんですが、その辺も含めた基礎・基本のお考え方をお示しをほしいと求めました。","respondent":"青木指導課長","answer":"３割減ったというよりは、３割スピードを落として、そうした考え方で基礎・基本を考えていくことができるのではないかなというふうに考えております。どうぞよろしくご理解ください。","id":"exchange-076"},{"speaker":"田中委員","kind":"意見","question":"英語も対象にすべきではないのかなというふうな印象といいますか、あと調査する項目は基礎・基本ではなくて総合力を見るべきではないかなというふうに思うんですが、その点のお考えを説明を求めました。","respondent":"青木指導課長","answer":"自ら考え、自ら解いていこうとする、そうした力を見ていきたいというふうに考えております。二つの力を両面測定できるような、そうした問題を作成し、実施していきたいというふうに考えております。","id":"exchange-077"},{"speaker":"田中委員","kind":"質問・要望","question":"ですから学生というのは、どういう新学習要綱を導入しているかというところに若干の疑問がある、疑問というか心配があるんです。要は入試の問題というんでしょうか、若干疑問というか不安は感じるんですが、その点どのようなお考えなんか尋ねました。","respondent":"青木指導課長","answer":"公立学校として基礎・基本の定着ということに力を入れてまいりますが、次の段階として発展的な力につなげるものであるというふうに考えております。そういう中で、また上位校…","id":"exchange-078"},{"speaker":"桜井委員","kind":"質問・要望","question":"２点、ご質問します。プラン２１関連事業、要望されたけれども、それからつかなかった内容の理由。","respondent":"久保田学務課長","answer":"中学校も３,１１０万円ほどということになるかというふうに思っております。それから、プラン２１関連事業がプラスアルファの部分というふうに見ていただいてもいいかなというふうに思っております。","id":"exchange-079"},{"speaker":"桜井委員","kind":"質問・要望","question":"私がもう一つお聞きしたいのは、児童１人当たり幾らとか、あるいは面積とかありますね。今言ったように、要望されたけれども、ついた予算とつかなかった予算の内容を教えてくださいというふうに言ったんです。","respondent":"久保田学務課長","answer":"その点で若干ご説明しますけれども、ほとんど平成１３年と１４年は変わりなく、配当予算はここで予算を計上しています。査定を受けて、先ほどのプラン２１関連事業費という形に今、なっているです。","id":"exchange-080"},{"speaker":"桜井委員","kind":"質問・要望","question":"何回も同じ質問をさせないでいただきたいんですけれども、じゃあ、教育長のほうに聞いたほうがよろしいんでしょうか。そういうものが要望あったけれども、ちょっと委員長、質問しているんですけれども。","respondent":"市岡企画財政課長","answer":"それから備品購入費でも同じ考え方で１７５万円。ただしこれは、特定の学校のどこへつけたということではなくて、あくまで教育費として、こういう枠で予算を計上したと、こういうことです。","id":"exchange-081"},{"speaker":"桜井委員","kind":"質問・要望","question":"教育長自身が公表します、各学校への予算配分は必ず公開しますというふうに言っているわけです。今していなければいつするのか、あるいはこの場で公表いただければ公表していただきたいというふうに思います。","respondent":"指田教育次長","answer":"国際理解教育が１,０２０万円、まちの人々から学ぶが約３００万円、ふれ合い教育と合同部活で約７０万円近くというふうな状況にあります。習熟度別であるならば、全体的な２次査定分がまだ残っていますので、それはこれからというふうな状況になります。","id":"exchange-082"},{"speaker":"桜井委員","kind":"質問・要望","question":"そこをもう一度確認をしたいのと、その前段の質問です。そちらのほうで教えていただきたいんですけれども、３年間のところでお話しいただきたいんですけれども、説明を求めました。","respondent":"鷹倉庶務課長","answer":"児童１人当たり、小学校ですね、これが１０年度が４８万円、１１年度が５２万円、１２年度が５４万円。１１年度が５１万３,０００円、そして１２年度が……、ちょっと１２年度が数字がおかしいのでまた後ほど申し上げます。","id":"exchange-083"},{"speaker":"桜井委員","kind":"確認","question":"それで、区民１人当たりの教育費を教えていただけますでしょうか。その理解でいいのかどうか、もう一度確認と、説明を求めました。","respondent":"指田教育次長、鷹倉庶務課長","answer":"当然、例えば学校施設整備費や何かについては、今年度からいろいろな形でもって学校教育の中に継ぎ足していこうという考え方を持っています。同時に、必ずしも下位にあるというふうなご懸念がご指摘に当たるかどうかというのは… これはどの数字をとるかというのはなかなか難しいんですけれども、２３区そろっている数字で１２年度ベースで持っている数字があります。これを除いても１０位という形でちょっと数字をとらえてあります。","id":"exchange-084"},{"speaker":"桜井委員","kind":"質問","question":"私がなぜしつこく教育予算の質問をしているかというと、公立ですからどの学校を選んだにしても、それはもう基本だと思うんですね。局面で見るわけですから、非常に成長が遅い子もいるし、中学になってぐっと伸びる子もいますよ。","respondent":"若月教育長","answer":"経営の論理が優先しているのではないか、こういうご指摘でありますが、そんなことはないんです。教育の論理を正しく機能させるためには、もっと経営的なセンスを取り入れなければだめだ、こう言っているだけのことであります。","id":"exchange-085"},{"speaker":"桜井委員","kind":"質問・要望","question":"その経営的センスを私は質問したんですけれども、経営論的発想に基づく指導システムづくりや学校体制づくりが大切であると。そこにコストの問題と効率主義がね……、人間を見る上では大変だと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-086"},{"speaker":"本多委員","kind":"質問・要望","question":"１点目は、学校管理費の教材・教具費について、２点目は、教育改革プラン２１を進めていく上での教職員について、２点お伺いします。三つ目が私費で購入しているものの会計について、４点目が小中学生対象の傷害保険がどのようになっているのか内容を教えてほしいと求めました。","respondent":"久保田学務課長","answer":"私費につきましては、これには監査を当然つけるんですけれども、そういう形で保護者に説明して了解を得ているというようなものが多うあります。これは各学校のＰＴＡがそれぞれ保険会社に契約しているという状況です。","id":"exchange-087"},{"speaker":"本多委員","kind":"質問・要望","question":"中学校１,６３８万円、定価に対する購入率というんでしょうか、その辺についてお聞かせほしいと求めました。","respondent":"久保田学務課長","answer":"できるだけ長もちしたいということで、それぞれの学校で最低限必要な部数、こうした調査もしながら手配しているという状況です。それから、指導書の割合ですけれども、これは各学校によってそれこそ千差万別がありますので、統計的な数字は今のところ持ち合わせておりません。","id":"exchange-088"},{"speaker":"本多委員","kind":"質問・要望","question":"学校単位でまとまった数で購入をしていくものというものはどのくらいあるのか、概要をちょっとお聞かせいただきたいと思うんですが。","respondent":"久保田学務課長","answer":"学校単位でまとまって購入するものは、いっぱいあると考えています。例えば何人いるかというのはそれぞれ学校によって違いますけれども、その部数をまとめて発注するというような形になるかというふうに思っております。","id":"exchange-089"},{"speaker":"本多委員","kind":"質問・要望","question":"納入をされました教材・教具で、使用されないものというものがもしあれば、お聞かせほしいと求めました。そういった個々の教材ですとか、あと共通して学校に置いてあるもので使わないようなものなどがあれば教えてほしいと求めました。","respondent":"久保田学務課長","answer":"当然会費を取って、要するに予定していたけれども買わなかったと、こういうものについては返還しておりますので。それから、今の共通したものというのは、そういう点でも十分に活用はしているんじゃないかというふうには思っております。","id":"exchange-090"},{"speaker":"本多委員","kind":"質問・要望","question":"人事制度につきましては構造的な変革が求められており、今の現行に関しまして、都との関係の現行の制度について教育委員会はどう思われているのか。先ほども若干答弁であるんですが、現行の制度、例えばこの部分がネックだとか、そういった部分があればお聞かせいただきたいと思うんですが。","respondent":"青木指導課長","answer":"既にご説明させていただきましたけれども、今、私どもがこの人を採用したいということで採用できるものではございません。そういう意味で、もしくは異動してきていただくというようなことができない、そうしたことが大きなネックになっているというふうに認識しております。","id":"exchange-091"},{"speaker":"本多委員","kind":"質問・要望","question":"これは選挙で、任期が３年ということなんですが、生徒を除く部分ですね。非常にやりやすいというような部分があると思うんですが、その点についての感想などがあったら、お聞かせほしいと求めました。","respondent":"青木指導課長","answer":"確かにそういう意味で、教育委員会の制度を超えた制度ではないかなというふうに考えております。そういう意味で、そうした社会の風土、社会の体質ということも考えていかなければならないなというふうに今お伺いしました。","id":"exchange-092"},{"speaker":"北野委員","kind":"質問・要望","question":"すまいるスクールについて伺いますけれども、宮前小学校の３校が新たに開設されるわけですけれども、場所としてはどこが使われるのでしょうか。そうしたときに、今後そういう身障者のお子さんたちを放課後どうするかということについても再度お伺いしたいと思います。","respondent":"富田教育改革担当課長","answer":"具体的には各学校と今後詰めていく予定ですけれども、それぞれ比較的独立して、まとまった３教室以上とれるところというところで考えております。他の２校については、保護者の方なりにつけていただくことが必要になるという考え方、この基本的な考え方に変わりはございません。","id":"exchange-093"},{"speaker":"北野委員","kind":"質問","question":"３教室以上とれるというところと、原小学校についてお伺いしますけれども、また土曜日も使われているという経緯がありますよね。住宅が３００戸増えるということで、そういうことも考えて教室というのは検討されるのでしょうか、お伺いします。","respondent":"富田教育改革担当課長","answer":"例えば同じ施設を時間で分けていくとかさまざま考えられると思いますが、学校を中心に今後検討してまいりたいというふうに考えております。今のところ、すまいるスクールを西校舎につくっても大丈夫であるとの認識の上に判断したものです。","id":"exchange-094"},{"speaker":"北野委員","kind":"質問","question":"まあ、そこは理解するところなんですけれども、今言ったことについてお伺いしたい。学識経験者の人が５校ぐらいを大体受け持ちまして、そういう基準というのはどういうふうに設問については設定していくんでしょうか、お伺いします。","respondent":"富田教育改革担当課長、青木指導課長","answer":"原小学校においてすまいるスクールをその場所に設置することについて問題はないと、そのような認識でおりまして、すまいるスクールはそういった西校舎に設置をしていくという予定です。 学校は今年はここに力を入れていきますという具体的な方針が示され、さらにそれをもとに、その具体的な方針と観点でそれぞれの基準が出てきます。そういう意味で、学校側の説明も含めて…","id":"exchange-095"},{"speaker":"北野委員","kind":"質問・要望","question":"どういうところが一番いいのか、生活の中で安定していけるのかということを、やはり前向きに検討してほしいと求めました。「１ 学校の総体」と、それから５項目ありまして、もう１回教えてほしいと求めました。","respondent":"青木指導課長","answer":"その五つの対象にそれぞれ、その学校総体に関して、学校の姿はどうなのだろうか、児童・生徒の姿はどうなのだろうかという項目があります。そこの項目についてそれぞれ評価していただくような、そうした評価表の仕組みになってあります。","id":"exchange-096"},{"speaker":"北野委員","kind":"提案","question":"それも内部評価の中に入れるべきではないかなということを提案いたします。調査内容は品川区独自のものをつくるということなんですけれども、どういうようなことで調査表をつくっていくのかというのを伺いたいと思いますとの意見を述べました。","respondent":"青木指導課長","answer":"先ほどの項目についての設定についてはご説明しましたが、一つだけ補足いたします。そうした委員会を設置いたしまして、そこで問題作成に当たって検討していきますが、民間の機関との連携で進めていきますが。","id":"exchange-097"},{"speaker":"北野委員","kind":"質問","question":"子ども自身の評価というんですか、それについてはいかがでしょうか。そういう学校独自に子どもの姿というんですか、やはり評価していくということが大事だと思うんですけれども。","respondent":"青木指導課長","answer":"外部評価者を集めて説明もいたしますし、全く同じような観点で、子どもたちを同じ物差しではかるというようなことではございません。独自の特色ある教育活動という、一律５８校の児童・生徒が全く同じような形で評価されるということではございません。","id":"exchange-098"},{"speaker":"北野委員","kind":"質問・要望","question":"そういうのが学校の判断にならないように、要するにいい学校、悪い学校という判断にならないような形で進めていってほしいと求めました。この減っている理由を教えてほしいと求めました。","respondent":"久保田学務課長","answer":"ほかの費目には流用しないということを限定して、今までやってきた部分について精査した形で、今回はこういう形で予算を計上したと。ほかの費目、あるいはほかの事業には、この予算は絶対流用させないという思いでこれをやってきたです。","id":"exchange-099"},{"speaker":"北野委員","kind":"質問・要望","question":"ですから学校図書の充実も図りながら進めていっていただきたいと。ですから来年度は、ちゃんとした計画を立てて、要望があれば出していただけるということなんか尋ねました。","respondent":"久保田学務課長","answer":"さらには、さらに充実させたいという学校につきましては、プラン２１の特色ある教育活動の中で予算計画を上げてもらおうというふうに思っております。それに応じて新たにそういうところにも予算をつぎ込んでいく、強化していくという考え方は現在持っております。","id":"exchange-100"},{"speaker":"北野委員","kind":"質問・要望","question":"子どもが読みたい本がやはりあると思いますので、そういうのも選びながら進めていってほしいと求めました。防災センターなど人が来るところなどがいいと思いますがいかがか尋ねました。","respondent":"鷹倉庶務課長","answer":"これを踏まえながら検討委員会で、こういう形で集約したという形で、ご意見を運営に反映しているという考え方を持ってあります。具体的なことが、学校改築が進む中で、子どもたちの絵を展覧する機会があればやってみたいなと思います。","id":"exchange-101"},{"speaker":"北野委員","kind":"提案","question":"これは私も、絵とか文章なりで、ぜひ子どもの意見を取り上げてほしいということで提案させていただいたことが実現したということなんですね。やはりいろいろな方が学校に向けて、ぜひ機会をとらえてではなく、前向きに進めていっていただきたいなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-102"},{"speaker":"金高委員","kind":"質問・要望","question":"どういう資格といいますか、そういうのを持った方なのかどうか、そういうのをお伺いさせていただきたい。中学校は確かニュージーランドのほうですか、向こうの教育委員会のほうから派遣されている先生が来ているということも伺っておりますけれども。","respondent":"青木指導課長","answer":"そして４点目には、帰国子女、外国子女の適応指導ということで、今日本語に困っているお子さんたちの教室についての件です。もう一つは、そのポートランドとオークランドの学校の先生を直接招致して本区の学校に派遣をすると、こういうような形で現在進めております。","id":"exchange-103"},{"speaker":"金高委員","kind":"意見","question":"それぞれ小学校、中学校、内容が違うわけですけれども、３年目に入りまして、この３月、いよいよちょうど３年目が終わるわけです。これらを実際に実施されてきて、それぞれの学校での成果といいますか、その辺をお聞かせ願えればと思いますがとの意見を述べました。","respondent":"青木指導課長","answer":"プラン２１のスタートから、小学校の国際理解教育、全校で小学校は取り組んでおりますので、その２年目が終わるということになります。ほんとにコミュニケーションといいますか、子どもなりに大変なれ親しんできたというようなことで、成果が少しずつ目に見えてきているところで…","id":"exchange-104"},{"speaker":"金高委員","kind":"質問","question":"中学校のほうはどのような形になりますか尋ねました。","respondent":"青木指導課長","answer":"プラン２１にかかわらず、こういうような形で従来から行ってきております。それから実際に会話を通してコミュニケーションを深めるという意味では、大変ＡＬＴという存在は大きいものというふうに考えております。","id":"exchange-105"},{"speaker":"金高委員","kind":"意見","question":"市などの教育委員会のほうでの費用の分担だろうというふうに思いますけれども、もう一つ、人材派遣会社のほうから先生が派遣されているです。ちなみに１人当たりの単価というのはどのぐらいの単価になっているか、参考までにお聞かせ願いたいと思いますがとの意見を述べました。","respondent":"青木指導課長","answer":"１時間当たり７,３００円ということで行っております。","id":"exchange-106"},{"speaker":"金高委員","kind":"質問","question":"その次に、帰国子女の問題点で、ちょっとお伺いします。期間が何日ぐらい、あるいは何カ月ぐらいの勉強をされているか、それをお聞かせ願いたいと思います。","respondent":"青木指導課長","answer":"今年度につきましては、２２人がきゅりあんの教室に通っております。ほぼ集中講座ですので、３カ月ほど通うと日本語になれるということで、また学校のほうで普通の生活に入れるようなケースが多くなっております。","id":"exchange-107"},{"speaker":"金高委員","kind":"質問","question":"先日、このきゅりあんのほうにお伺いさせていただきまして、授業内容をちょっと見せていただきました。なぜかといいますと、３カ月でもって、確かに日本語を話すことはできる。","respondent":"青木指導課長","answer":"学校と、それからこの教室のほうの指導員と連絡を密にとって、問題の解決に当たっていきたいと思います。学校も通ってありますので、言葉は最初は理解できなくても、学校のほうの教師もそうしたことを十分配慮して指導に当たっております。","id":"exchange-108"},{"speaker":"金高委員","kind":"質問","question":"先日この教室のほうに伺いましたところ、ちょうど３人の先生方がおりまして、きめ細かにそれぞれの言葉でもって教えております。もしやっているのであれば、品川区とどういう違いがあるかどうか、その辺を、もしありましたらお聞かせ願いたいと思います。","respondent":"青木指導課長","answer":"このような取り組みがあるということは聞いておりますけれども、具体的にどういうような状況であるかという、まあ、正確な情報としては把握してございません。","id":"exchange-109"},{"speaker":"金高委員","kind":"質問・要望","question":"それから３カ月が終わりまして、学校の学業についていけない子どもたちを、一般の塾ですとなかなかそれはできないだろうと思うんですね。多分ＮＰＯですか、行政のほうでもって手を差し伸べる枠があるかどうか、その辺のご意見をほしいと求めました。","respondent":"青木指導課長","answer":"主に３カ月というふうにお答えいたしましたけれども、中には５カ月、また再びこの教室に戻ってくるというようなお子さんもいらっしゃいます。今後も一人ひとりのそうしたお子さんに対して対応できるような教室であるように運営をしていきたいというふうに考えております。","id":"exchange-110"},{"speaker":"金高委員","kind":"意見","question":"いずれ日本でもってずっと生活していくわけでありますので、日本の貴重なる財産、人材であると思います。やはり社会の中でもって１日でも早く入っていけるようなそういう体制は、絶えずとっていただきまして、教育行政に取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-111"},{"speaker":"辻委員","kind":"確認","question":"ちょっとお伺いしたいんですけれども、人的な配置というのが、今後大事になっていくかと思うんです。ちょっと確認しておきたいんですが、品川区の小・中学校に教育実習として来る実績というのはどのぐらいあるんですか、年間。","respondent":"青木指導課長","answer":"毎年教育実習生は品川区で受け入れております。その人数は年によって違いますけれども、ほぼ２０人程度の実習生は受け入れているところです。","id":"exchange-112"},{"speaker":"辻委員","kind":"質問・要望","question":"そういう部分の子どもに対する要望にもこたえていくということでいくと、私は、改めてこういう教育課程をとっている大学の先生。品川区が悲鳴を上げるぐらい殺到していい教師が集まってくる、こういうことにもなるんじゃないかと思うんですけれども、いかがか尋ねました。","respondent":"富田教育改革担当課長","answer":"ぜひとも夏休みについては、大学の、特に教員を目指すような方々を対象に学生アルバイトというような形で募集をしていきたいというふうに考えております。","id":"exchange-113"},{"speaker":"辻委員","kind":"質問","question":"次に習熟度別の学習のことについてお伺いします。おくれている子どもについては指導助手なんかをつけていろいろやるっていうんですけど、進んでいる子どもについてはどういう形で……。","respondent":"青木指導課長","answer":"いろいろな習熟度別学習の進め方がありますが、今、そういうような形でグルーピングをして指導に当たるというような方法をとってあります。指導助手が入ったり、学年全体で行うような習熟度の形もありますので、さまざまな形態で習熟度別の学習を進めているところです。","id":"exchange-114"},{"speaker":"辻委員","kind":"意見","question":"その辺はもう、とことんやらせていく方向なのかどうか。その辺で、どういう考えがあるのかとの意見を述べました。","respondent":"青木指導課長","answer":"基礎、さらにはその応用的な問題に挑戦する子と、それぞれのグループに分かれてそれぞれの課題に取り組むというようなケースが多く見られます。それからさらには、非常に難問題というんですか、そういうような問題に挑戦するようなグループもあります。","id":"exchange-115"},{"speaker":"辻委員","kind":"質問・要望","question":"これが今月の２５日までということになっているんですが、出すか出さないかは別として、この課題についてはどのように考えていらっしゃるか。この辺の感想、ご意見、ご見解をお伺いしたいと思います。","respondent":"富田教育改革担当課長","answer":"小学校設置基準および中学校設置基準の制定に関して、文部科学省のほうでパブリックコメントを求めているわけですけれども、品川区教育委員会といたしましても、小・中一環校の問題等々あり、積極的に事務局内で考えをまとめて期限までに提出していきたい考えです。","id":"exchange-116"},{"speaker":"辻委員","kind":"提案","question":"平成１３年の第１定で一般質問し、うちの嶋議員が一般質問で取り上げて、改めて品川区の現状をちょっとお知らせほしいと求めました。私は朝１０分ぐらいの、まずそこから入っていこうというような提案もしていたわけですけれども、どんな形で進まれているのか尋ねました。","respondent":"青木指導課長","answer":"読書活動を取り入れた教育活動ですけれども、現在、読書活動を教育課程に位置づけて実施している学校が、小学校では３０校、中学校では７校あります。その他放課後、授業時間、さまざまな形で読書活動を取り入れて現在進めているところです。","id":"exchange-117"},{"speaker":"辻委員","kind":"質問","question":"教育委員会というのは、このことについてやれとかって首に縄をつけてはいけないでしょうが、どういうことなんでしょうか。やれないのとやる学校の差というのは。","respondent":"青木指導課長","answer":"先ほど小学校３０校、中学校７校というふうにご説明いたしましたけれども、何らかの形ではどこの学校でも実施しています。例えば来年度の予定ですが、それぞれの学校の予定を私ども調査しましたけれども、現在予定をしています。","id":"exchange-118"},{"speaker":"辻委員","kind":"質問・要望","question":"ですから、この授業というか、国語というんじゃなくて、学校の一つの大きな行事として読書というのは位置づけていただきたい。どうでしょうかね、それこそ差をつけてでもいいから、奨励してあげてぐらいに私は意味があると思うんです。","respondent":"山岡総務部副参事","answer":"スポーツ協会と教育委員会と共催の形で事業を実施しているですけれども、例えば午前中でしたらどういう種目があるという形でなっております。区民の方、区民在住、在勤、在学の方でしたら参加できることになっております。","id":"exchange-119"},{"speaker":"辻委員","kind":"質問","question":"そのときに、私のところにある区民の方から電話をいただきまして、フリースクールというのは個人参加なんですか、それとも団体参加なんですか。この辺をちょっとお伺いしたいと思います。","respondent":"山岡総務部副参事","answer":"個々の方が、自由にフリーに参加できるです。団体の競技もありますけれども、個人で参加してその団体の皆さんと一緒にやると、そういう形を今、とっております。","id":"exchange-120"},{"speaker":"辻委員","kind":"質問","question":"時間がないので端的にお伺いします。入口で、あんた品川区じゃないからといって断るんですか、どうか尋ねました。","respondent":"山岡総務部副参事","answer":"原則として先ほど申しました条件ですので、そういうふうにお尋ねをされましたときは、区外の方はご遠慮していただきますと、そういうふうにお答えしております。","id":"exchange-121"},{"speaker":"辻委員","kind":"質問・要望","question":"５人がバスケットやろうといって来たときに、料金体系をどうするかというのは、ひとつこれはぜひ検討していただきたい。いかがでしょう。","respondent":"山岡総務部副参事、指田教育次長","answer":"今の問題につきましては、スポーツ協会サイドだけで決めるわけにもまいりませんので、教育委員会と協議しまして前向きに検討してまいりたいと思います。 大変申しわけありません。区民の方がいれば、そういう差別をしないで必ず入れるような形でもって対処してまいります。","id":"exchange-122"},{"speaker":"築舘委員","kind":"質問・要望","question":"この４月から完全週５日制ですか、土曜日が結局先生方が教えていたんだけど、それがお休みになると。そこの現状がどういう状況になっていたのか、それでなぜその３校に絞ったのかというのを説明を求めました。","respondent":"青木指導課長、富田教育改革担当課長","answer":"それぞれのところで教員同士の１年間の反省を出して、職員会議を通して、それをみんなで検討をしてきた。その検討事項を来年度の計画に盛り込んできたのが内部評価という形だったというふうに考えていただければと思います。 学校選択ブロックが４ブロックありますので、そのブロック１つに１校ずつということで、各学校施設の状況等を勘案して決定したものです。１５年度以降は年次計画を立てて拡大をしてまいりたいと考えておりまして…","id":"exchange-123"},{"speaker":"築舘委員","kind":"質問・要望","question":"それは要望で結構です。ですから、そういうことが考えられることなのかということを、ちょっと説明を求めました。","respondent":"青木指導課長","answer":"すまいるスクールの職員と学校の教員では、やはり勤務の上で重なりがどうしても出てきますので、ちょっと今のご提案は無理な形になります。","id":"exchange-124"},{"speaker":"築舘委員","kind":"質問・要望","question":"ただやっぱり、そういう意欲のある先生が出た場合、どうなるんですか。どうか尋ねました。","respondent":"青木指導課長、若月教育長","answer":"それはそれぞれの教員が、そういうふうに意欲的に取り組んでくれれば、私たちは大変うれしく思っています。そうした学校との連携、教員との連携ということは、ひとつ課題として検討していきたいというふうに考えております。 したがいまして、夏休み、これは子どもが夏休みであって、先生は夏休みではありません。８月の学校の教員の指導のあり方としては、このように考えておりますし、こんなふうに考えているところです。","id":"exchange-125"},{"speaker":"築舘委員","kind":"質問","question":"ですから、校長先生が権限を持って、しっかりとやる気のある先生を常に引き立てるというか伸ばしてあげる。ですから、そこの点をひとつ、しっかりと考えていただいて、教育長からもお答えいただきましたけれども、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-126"},{"speaker":"沢田委員","kind":"質問","question":"小中一貫校に関して、大きく２点、質問したいと思います。回答は、そういうことは考えていないんだということだけなんですけど、もう少し詳しくお伝え願いたいと思います。","respondent":"富田教育改革担当課長","answer":"小中一貫校の結果として周辺校が統廃合につながるのではないかというご質問ですけれども、代表質問でもお答えしておりますとおり、プラン２１または小中一貫校につきましても、統廃合を前提としたものではないです。","id":"exchange-127"},{"speaker":"沢田委員","kind":"質問","question":"そう思っていないというのはわかるんだけど、そう思ってやった結果がどうなるかというのは、また別問題だというように思うんですよ。小学校６年まではいいけれども、６年卒業したときには、この一貫校に入れるんですか、必ず。","respondent":"富田教育改革担当課長","answer":"小中一貫校の対象児童等々、そういった具体的なことにつきましては、今後設置いたします小中一貫校準備委員会の中で検討してまいる課題の一つです。","id":"exchange-128"},{"speaker":"沢田委員","kind":"意見","question":"９年間一貫した教育をやることによって、シームレスに子どもたちを教育したいという、こういうことで一貫校ができているわけですね。だから、そこのところどうなのかということを聞いているんで、ちょっとお答え願いたいと思いますとの意見を述べました。","respondent":"富田教育改革担当課長","answer":"ＰＴＡの役員の方を回ってご説明しております趣旨と申しますのは、そういった課題は大変大きな課題であるというふうに認識をしております。したがいまして、少なくとも来年度の新１年生なりが学校選択をしなければならないような時期には間に合わせて…","id":"exchange-129"},{"speaker":"沢田委員","kind":"質問","question":"小中一貫校の策定経費を予算化するときに、そこのところをきちっとしておかなければだめなんじゃないですか。こうだから安心してくださいということを私は言うべきだと思うんですが、教育長、いかがか尋ねました。","respondent":"富田教育改革担当課長","answer":"先ほどから申し上げておりますとおり、私ども、そういった課題がさまざまあるのは承知しております。さまざまある課題を洗い出しながら、一つ一つ解決をしていきたい、決定をしていきたいです。","id":"exchange-130"},{"speaker":"沢田委員","kind":"質問","question":"中学に行けば４クラスだから、どうぞ地元の小学校に入ってください、そういうふうに言えばそんな問題はないと思います。ここは、ぜひ教育長なり次長のほうで、どう考えているのかお答え願いたいと思います。","respondent":"指田教育次長","answer":"反論するわけではありませんが、早くそのことについては結論を出していくんだ、私どもは決して間違ったことを言っているつもりはないんですよ。そうではなくって、そこでもって話をちゃんとまとめて…","id":"exchange-131"},{"speaker":"沢田委員","kind":"質問","question":"これはもっと具体化に向けて、委員会、部会をつくってどんどん進めるということですから。ちょっと別の角度から質問したいと思うんですが、公民で、地方自治をどのように教えるか尋ねました。","respondent":"青木指導課長","answer":"突然の質問で、今、とまどっておりますけれども。中学校の公民でも、小学校の社会でも、やはりよき社会の一員として、どのように物を考えるのかというようなことを常に指導しています。","id":"exchange-132"},{"speaker":"沢田委員","kind":"質問・要望","question":"突然の質問ですから、「住みよい地域社会をつくっていくために、住民の意思で行う政治が地方自治である」って書いてあるんですよ。４年生、この中学校で教えている地方自治とは何なのか、住民の意思で決定していくんだということに教育委員会が反してないでしょうかね。","respondent":"富田教育改革担当課長","answer":"私どもが言われてまいりましたことというのは、こうやって、まだ決まっていない段階だということはわかりましたと。ご説明に上がりたいと考えていますし、それぞれの関係の学校のほうにも、その都度説明をしに上がりたいです。","id":"exchange-133"},{"speaker":"沢田委員","kind":"質問・要望","question":"そうしますと、まだ決まっていないんだから、この計画はゼロから見直すこともあり得るということですか。小中一貫校を、日野中を移設してやるという計画そのものを見直す余地があるのか、どちらなんか尋ねました。","respondent":"富田教育改革担当課長","answer":"小中一貫校につきましては、第二日野小学校の地に、第二日野小学校の改築とあわせ、日野中学校移転・改築、この方向は決まっております。こちらで決めていただくことと考えております。","id":"exchange-134"},{"speaker":"沢田委員","kind":"質問","question":"不安だ、小中一貫校は困るという声があっても、既に結論決まっちゃってるんじゃないですか。どんな説明をしてきたのか、どんな意見が出ているのか、お答え願いたいと思います。","respondent":"富田教育改革担当課長","answer":"２月８日のプレス発表以降、小学校ＰＴＡ連合会の役員、第三日野小学校ＰＴＡの役員等々にご説明を申し上げてきております。その中では、小中一貫校を開設に至った経緯等々、考え方について説明をしております。","id":"exchange-135"},{"speaker":"沢田委員","kind":"意見","question":"今、言った中に第四日野が入っていないんですけれども、なぜ第四日野が──ちょっと聞き逃したらごめんなさいね、入っていないのか、ちょっと説明願えますかとの意見を述べました。","respondent":"富田教育改革担当課長","answer":"こちらでは、要請があれば説明に伺いますということを、学校長を通してお話をしておりまして、要請があったところに伺ったという経緯です。","id":"exchange-136"},{"speaker":"沢田委員","kind":"質問","question":"こういうことを考えているけれどもどうなんだ、不安にこたえ、物事を決めるというのが地方自治体のあるべき姿じゃないんでしょうか。それで、こういうときがあるときに、第四日野小なんか、もう真っただ中じゃないか尋ねました。","respondent":"指田教育次長","answer":"それまでの間はこういう考えでいますよ、ついてはそのことについて校長先生からＰＴＡの役員の方々に、まずお話をしてくださいと。校長先生のところでもって、まだ大丈夫ですということですから、まだご要請がないから伺っていないという状況です。","id":"exchange-137"},{"speaker":"沢田委員","kind":"質問","question":"で、そのほかの子どもに対しては中学校をどこに選ぶかと、不安をこんなに拡大するのが公教育でしょうか。私は、入った子だけじゃなくて、入れない子、悩んでいる子も同じように不安を取り除くのが教育だ、そのことを指摘して終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-138"},{"speaker":"船波委員","kind":"質問","question":"第一は、小中一貫校基本計画策定経費というところで２,０００万円予算が計上されているので、その内容はどういうものになっているんでしょうか。建物をどうするかというのを考える前に、この基本計画策定の内容はどういうものになっているのか、お伺いします。","respondent":"鷹倉庶務課長","answer":"ソフト面のものを、基本計画のハード面に反映していくという意味で、十分この部分で対応できるのではないかというように考えております。ただ、いろいろなケースの場合に、いろいろ経費がかかっていることがありましたらば、また補正で対応していただく部分があるのかもしれませ…","id":"exchange-139"},{"speaker":"船波委員","kind":"質問","question":"それに関して、前提として考えないということだけでいいのかということを主体的に考えていくべきではないかと思うんですけれども、いかがでしょうか。学区域の自由化、主体的にそういった事柄を考えていくべきではないかと思いますけれども、その点に関してどういったお考えなのか尋ねました。","respondent":"鷹倉庶務課長","answer":"こういうものを地域の中に、先ほど教育改革担当課長が申しましたとおり、地域の中に説明してまいります。きめ細かく説明していく中で、意見を聞いて、そしてまたそれをそういう委員会なりにフィードバックする。","id":"exchange-140"},{"speaker":"船波委員","kind":"質問","question":"そのときに考えるということですけれども、でもやはり教育委員会として、どうなんでしょうか。ほかの自治体では、品川区でもかつてはそういった検討がなされたこともあったかと思いますけれども、どうなんか尋ねました。","respondent":"久保田学務課長","answer":"私の方からお答えしますけれども、庶務課長が答えたとおり、このプラン２１というのは学校の統廃合前提にしては考えてございません。プラン２１でそれぞれの学校の取り組み、教育委員会は全面的に支援してまいりましたので、こんなふうな考えを持っております。","id":"exchange-141"},{"speaker":"船波委員","kind":"質問","question":"ですから、やはりこの内容に出ているほかの活動もするべきではないかと思いますけれども、どうなんでしょうか。年に１０時間ぐらいの英語の授業をするよりか、そういった活動ができるようにするべきではないかと思いますけれども、いかがか尋ねました。","respondent":"青木指導課長","answer":"今、英語がどれだけ重要な外国語になっているかという認識のもとに、私どもはこの国際理解教育を考えております。私たちはこの英語活動以外にも、それぞれの取り組みは、学校によって実施しています。","id":"exchange-142"},{"speaker":"船波委員","kind":"質問・要望","question":"一つの学校ごとにやって、そういったことを見るということもできると思うんですけれども、どうして全区一斉にしてしまうんでしょうか。全区一斉にすると、そういったことで子どもたちがやる気をなくしたりとかしないようにするための対策は、どういうふうに保証していくんか尋ねました。","respondent":"青木指導課長","answer":"異文化理解につきましては、ボランティア活動も導入していますし、それからまちの人から学ぶという授業もやっております。全区的に行う学力調査につきましては、やはり今プラン２１を進めているこの品川区という自治体として学力を把握したいという考え方です。","id":"exchange-143"},{"speaker":"石田委員","kind":"質問","question":"もう１個、もう１点やりたいのは、国旗国歌をやりたいと思いますが、国旗国歌からまずお伺いをしたいと思います。小学校１年生から指導しているという話でありますが、まずどのような指導を１年生からしていくかというところをお聞かせ願いたいと思います。","respondent":"青木指導課長","answer":"学校行事の儀式の際に、国旗と国歌を理解させるという、発達段階において理解させていくということが共通して言えるかと思います。国旗とは何か、国歌とは何かというようなことを、それぞれの発達段階にふさわしい形で指導しております。","id":"exchange-144"},{"speaker":"石田委員","kind":"質問","question":"２年生のある子どもから、すべてのものをちゃんと指導したんだと思いますが、その２年生の子から逆に私のほうが質問を受けました。これは小学校２年生ですから、教育委員会としてどういうふうにとらえているかというところだけ、ちょっと説明を求めました。","respondent":"青木指導課長","answer":"国旗や国歌に対しての指導については、一面的な指導ではないかなというふうに認識しています。","id":"exchange-145"},{"speaker":"石田委員","kind":"確認","question":"何人か確認したらやっぱりそんなことがあったから、やっぱりそういうことがあるんだけれども、教育委員会としてそういうことを把握しているのかどうかというところを……。","respondent":"青木指導課長","answer":"そのような指導があったということは、今、初めて聞きました。","id":"exchange-146"},{"speaker":"石田委員","kind":"質問","question":"ですからね、逆に教員に対して指導していこうということをお考えなのか、お考えがあったらちょっと説明を求めました。","respondent":"青木指導課長","answer":"今、改めてこの国旗国歌問題について、もう論議する時代ではないというふうに私は認識しております。それは、私たち学習指導要領に準拠した形でのそれぞれの現場での指導は、校長会等におきましてもこうした考え方で指導しています。","id":"exchange-147"},{"speaker":"石田委員","kind":"質問・要望","question":"これがどういうわけか、それがどういうわけかそこでとまっているみたいで、ほかの学校にもそのボランティアの方は行ってもいいわけですよ。ちょっとそこら辺を教えていただきたい。","respondent":"青木指導課長","answer":"私ども、このプラン２１にかかわる研修会を、校長レベル、教頭レベル、またその研究主任や教務主任レベルで研修会を持ってあります。それぞれの推進校の取り組みや、こういうボランティアの方の取り組み、そこで情報交換を深めていきたいというふうに考えております。","id":"exchange-148"},{"speaker":"石田委員","kind":"質問","question":"あわせてお聞きしたいのは、そういうところもどういうふうにお考えなのか、あわせてお聞きしたい。","respondent":"青木指導課長","answer":"今、企業と学校がタイアップして教育の活動を進める、研究を進めるというような事例が幾つか出始めております。企業と学校がどういうような形で実際にできるのかというようなことを検討してまいりたいと思いますし、また、そうした声があればぜひ。","id":"exchange-149"},{"speaker":"石田委員","kind":"質問","question":"そういうのをやっているところはボランティアで、もう完全なボランティアで、商売を離れてやっているようなところがやっているわけですよ。済みません４０校あるんだけどやってくださいとか、そういう動きをかけられるのは教育委員会だと思うんですが、そこら辺のご見解をお願いします。","respondent":"青木指導課長","answer":"今、こういうような、企業が学校教育に支援をしていただけるというような状況が、いろいろな場面で見られてきております。私どものところにもいろいろとお声がかかってきてありますので、積極的に取り入れて、全区的な形で取り組んでいきたいというふうに考えております。","id":"exchange-150"},{"speaker":"石田委員","kind":"質問・要望","question":"それは教育委員会のほうでまとめていただくシステムを、まずつくっていただくことが先決だと思いますので、そこら辺のことはぜひぜひ要望をします。先ほども８日間か９日間かわかりませんが、そういうところのお考えはあるのかないのか、そこら辺をちょっと教えていただきたい。","respondent":"青木指導課長","answer":"いよいよ完全学校週５日制ということで、土曜日がすべて休みになる。それぞれの学校から保護者にも説明がされると思いますし、今、ちょうど時期的にも学校と教育委員会が連絡をとり合いながら検討していますので。","id":"exchange-151"},{"speaker":"石田委員","kind":"質問","question":"もう１個突っ込んで、それは校長先生が判こをつけばオーケーです、そういうことを公にしちゃえばいいわけですよ。一人ひとり頑張っていきますという答弁ばっかりなんで、そこら辺のことをどうお考えなのか、最後にそれだけをお聞きしたい。","respondent":"指田教育次長","answer":"基本的にはきょういただきましたお話、校長会等の中でもって周知徹底を図っていくのが基本です。そういう姿勢のもとに、あるいはＰＴＡを通してといいましょうか、そういう中でもってお話しをして申し上げていきたいというふうに思っています。","id":"exchange-152"},{"speaker":"上山委員","kind":"質問","question":"ちょっと関連で質問します。日の丸・君が代でどういうふうに教えているんだというような趣旨の、改めて伺いたいんですけれども、あるいは中学校でこういうふうに教えている。","respondent":"青木指導課長","answer":"いろいろな場面がありますけれども、例えば学校行事などでは、入学式や卒業式などにおいては、その意義を踏まえ、国旗を掲揚するとともに国歌を斉唱するように指導するものとするというような形で学習指導要領に位置づいております。","id":"exchange-153"},{"speaker":"上山委員","kind":"質問","question":"まあ、そういうふうなこともあったというんですけれど、そういうふうなことまで何か教えるとなっていらっしゃるんか尋ねました。","respondent":"青木指導課長","answer":"具体的にはそういうような形で学習指導要領には示されておりません。","id":"exchange-154"},{"speaker":"上山委員","kind":"質問","question":"何ていうんでしょうかね、君が代の君は何と教えてらっしゃるんですか、現場では。どうこう言って、私は本筋じゃないのかなと思うんですけれども、いかがか尋ねました。","respondent":"青木指導課長","answer":"小学校４年生の社会科の時間に、我が国や外国には国旗があることを理解させるというような指導があります。ほかにもいろいろな場面でありますけれども、要するに国旗として日の丸を教える、国歌として君が代を教えるです。","id":"exchange-155"},{"speaker":"土井委員","kind":"質問","question":"先般１５日の日だったですか、プラン２１の冊子を配っていただいて、こういう意味だろうというふうに考えさせていただきました。そして、その対象等々によっては、これの中身のつくりはこれでいいのかなということ等があるものですから、まずそれを１回最初に聞かせてください。","respondent":"青木指導課長","answer":"で、３月９日に、文部科学省の研究開発学校の報告会が本区で行われました。プラン２１のこの冊子につきましては、今、今後も本区に視察をされるような方たちも含めてお配りしていきたいというふうに考えております。","id":"exchange-156"},{"speaker":"土井委員","kind":"質問・要望","question":"そのトータル時間は年間どれだけあるんですか。やり方の、総合商社みたいにいっぱい書いてあって、でも実は売り込みたいのはこれよということになるんじゃないんか尋ねました。","respondent":"青木指導課長","answer":"冒頭ですが、このプラン２１の説明に当たって、ちょっと問題がある、具体性に欠ける、ちょっとわかりづらいというような点がございました。そうした授業の展開の中で、国際理解教育を進めている学校もありますので、そうした形で今後も進めていきたいというふうに考えております。","id":"exchange-157"},{"speaker":"土井委員","kind":"質問","question":"要するに、それらを含めた時限のもの以外の時限は何時間あるんですか。そうすると、全体ほかはどうなるんですか、どう配分されるんでしょうねということを伺ったんです。","respondent":"青木指導課長","answer":"時間ですが、来年度より総合的な学習というのが、年間１０５時間予定されます。今、中学校における福祉教育とかふれあい教育というようなものも、その１０５時間を活用して進めていきたいというふうに考えております。","id":"exchange-158"},{"speaker":"土井委員","kind":"質問","question":"それは、逆の意味で、先ほど一番最初に言った、習熟度学習のところに具体的にどうなさるんですか、グループ別ですよとおっしゃった。グループ別ですよというのは、部屋を別にするんですか、どうなんでしょうか、ということ等も起こるわけですね。","respondent":"青木指導課長","answer":"そういう、それぞれの学校間の競争というような認識で実施するようなことではございません。子どもたちもそういうようなことで、劣等感だとかを持たないような、そういう一人ひとり個に応じた指導をしていきたいというふうに考えております。","id":"exchange-159"},{"speaker":"土井委員","kind":"質問・要望","question":"研究課題ですからいいんですけれども、ぽろんと突然出てくるというのでは、どうにも理解ができないという形になるんですね。皆さんも知りたかったら聞きに行かれたらいかがでしょうか、と思います。","respondent":"若月教育長","answer":"決してそこにおいて、何かの感情や、あるいは別の要素が入るということはありません。それで淡々とやってあります。","id":"exchange-160"},{"speaker":"南委員","kind":"質問","question":"私は３０人学級について質問をしたいと思います。そして今年度からですか、その現況と、その効果はどういうふうにあるのかということをちょっとお尋ねします。","respondent":"青木指導課長","answer":"中学校では１８校、３３名の加配という状況です。この教員たちの活用をしまして、先ほども話題になりました習熟度別学習等も含め、成果を上げているところです。","id":"exchange-161"},{"speaker":"南委員","kind":"確認","question":"もう１回、ちょっと確認をしたいと思うんですけれども。ですから、こういう動きについて、品川区の教育委員会はどういうふうに評価をしていらっしゃるのか、ちょっとその点についても伺いたいと思います。","respondent":"青木指導課長","answer":"この学習の内容において、それぞれの効果があるということはあります。ほかにいろいろ学校では教育活動に取り組んですが、方法として取り入れているというところで、評価をしています。","id":"exchange-162"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、３０人学級をぜひとも実現していただきたいというふうに思っているんですが、なかなかそこには踏み出していない。別の手法でやれ、やっていくんだということから全然抜け出していないんですが、なぜ３０人学級をやろうというふうにならないんか尋ねました。","respondent":"久保田学務課長","answer":"今、東京都の教育委員会はどういう考え方をしているかというと、１学級は４０人定員でやるんだということが基本です。そういう形で東京都のほうは現在進めておりますが、基本的な４０人学級という考え方に変更する考えはないというふうに聞いております。","id":"exchange-163"},{"speaker":"南委員","kind":"質問","question":"そういうところで品川区がこれだけの教育改革をやろうってところに、どうして３０人学級だけ手をつけないんでしょうか。そこのところをどういうふうに解決しようとしているのか、そこについてもきちんとした姿勢も私は伺っておきたいというふうに思います。","respondent":"久保田学務課長、青木指導課長","answer":"私どもは今の教育の中で、学習集団と生活集団とは基本的に分けてやっぱり考えるべきだろうというふうに思っております。綿密な形で、念入りに教育の内容の充実を図ってありますので… その件について私のほうからお話ししたいと思いますが、この中学校の問題のあった学級は２８人のクラスです。生活指導、学習指導両面からこの学校に対しては指導してまいりましたし、今後も力を入れていきたいというふうに考えておりま…","id":"exchange-164"},{"speaker":"南委員","kind":"質問・要望","question":"そういう授業のあり方っていうものについては、教育委員会としてはどういうふうな見解を持っていらっしゃるか、ちょっと伺いたいと思います。ですからその点についての見解をお願いします。","respondent":"青木指導課長","answer":"学習意欲も身につき、また生活集団の中では、集団生活でどう人間関係を保つべきかということも学んでいきます。したがいまして、生活面と学習面では、やはり規模というものを考える必要があるんではないかなというふうに受けとめております。","id":"exchange-165"},{"speaker":"南委員","kind":"質問・要望","question":"私は要望にとどめますが、極めて東京都の問題ですから、財政の確保をしろということを事あるごとに言ってほしいと求めました。ですから、ぜひその方向で品川区も頑張って教育改革していただきたいということを言って終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-166"},{"speaker":"三上委員","kind":"質問","question":"時間によってはもう１点伺うかもしれませんという予告だけしておきます。そのあたりの稼働的な部分というのは今どうなっているのか、そこらだけちょっと先にお伺いしたいと思います。","respondent":"久保田学務課長","answer":"それから中学校が９校です。コンポスト、生ごみが大体１個当たり８トンぐらい出ますけれども、それの大体６分の１ぐらいコンポスト化されているというような状況です。","id":"exchange-167"},{"speaker":"三上委員","kind":"質問","question":"今、答弁の中から、環境教育にということでこのコンポスト化した肥料になってくるんでしょうか。そういった意味にあってすべての学校で環境教育、そういった部分で取り組んでいる学校の事例というのはどれくらいあるんでしょう。","respondent":"青木指導課長","answer":"今、委員のご質問にもありましたように、どこの学校でも環境教育というものは、社会科なり、家庭科なり、理科なりというような中で実施しています。どこの学校ということではなくて、いろいろな学校で取り組んですので、そのようにご理解いただければというふうに考えております。","id":"exchange-168"},{"speaker":"三上委員","kind":"質問","question":"やっぱりコンポスト化でできたものをどうするのかということでの、現実には学校給食、調理した場合に生ごみは出ているわけです。そうすると、そういった設置されていない学校についてどういった取り組みをするか、そこらあたりどういうお考えか尋ねました。","respondent":"久保田学務課長","answer":"生ごみ処理器を設置していない学校についての対応ですけれども、すべて運んでいただいてコンポスト化しています。設置していないところについては、学校が取り組んできたというのは、それこそ先駆的な役割というんですか。","id":"exchange-169"},{"speaker":"三上委員","kind":"提案","question":"私は平成５年の第４回定例会で、家庭用の生ごみ処理器を導入したらどうかと提案しましたね。こう思ったらそういったこともできるんじゃないか、私はぜひやってもらいたいなと思うんですけれども、いかがなんか尋ねました。","respondent":"久保田学務課長","answer":"当然そういうことも考えられるとは思いますので、教材品として、そういうものを買う考え方もあるかなというふうに思っています。それをフィードバックしてもらうということも、これは可能だと思いますので、その辺についても今後検討していきいというふうに考えています。","id":"exchange-170"},{"speaker":"三上委員","kind":"質問・要望","question":"そこらあたり、いろいろな知恵を出して、そして取り組んでいっていただきたいと、これはお願いしておきたいと思います。体育館、ホールなどの４０施設を対象とするということになっているんで、もうちょっと４０施設の具体的な説明をお願いできませんか尋ねました。","respondent":"上川内生涯学習課長","answer":"区民集会場１４カ所、それから文化センターが５カ所、品川歴史館等です。","id":"exchange-171"},{"speaker":"三上委員","kind":"提案","question":"私は平成４年の一般質問で、第３回定例会で、この問題について具体的にもうちょっと突っ込んで提案している部分があるんです。お金のやりとりだってその場でほんとうはできるのに、やらないで、そこらあたりはどうなんか尋ねました。","respondent":"上川内生涯学習課長","answer":"学校につきましては、スポレク推進委員会というのが今、学校ごとに調整をいたしております。その調整の機能を生かして、同じテーブルの中で調整したほうがいいということで、ここの対象の施設からは除外しております。","id":"exchange-172"},{"speaker":"三上委員","kind":"質問","question":"そのスポレク推進委員会でいろいろやっていることによって、これもあれですよね、１カ月前にはこの調整会議やりますよね。どうなってるんでしょうか、そこは。","respondent":"上川内生涯学習課長","answer":"登録団体でなくても、一般の方でも借りられます。","id":"exchange-173"},{"speaker":"三上委員","kind":"質問","question":"学校を借りた場合は、どういう今、仕組みになっているんでしょうか。それ以降、その学校に申し込みに行った場合には、どういう仕組みになっているんでしょう。","respondent":"上川内生涯学習課長","answer":"申し込みの調整会議に間に合わなかったような場合は、学校のほうから申請したときに納付書をもらって、それで銀行のほうに払い込むことになっています。","id":"exchange-174"},{"speaker":"三上委員","kind":"意見","question":"過去に私はこういう納付書の問題で言ったことは、納付書の銀行に支払いましたという、領収書を持ってこいということになっていたんですよね。それは改善されていますかとの意見を述べました。","respondent":"上川内生涯学習課長","answer":"同じです。","id":"exchange-175"},{"speaker":"三上委員","kind":"確認","question":"見て、それで確認しましたという印か何かを押してもらって、それで返ってくる。ということで１カ月以上その処理ができないということは、まだ続いているんか尋ねました。","respondent":"鷹倉庶務課長","answer":"学校施設の使用料関係の調定は、私ども庶務課でやってありますので、私のほうで答えします。あるいはこちらから払っていない人の追及をできるような流れを研究して実現していきたいなと、このように考えてあります。","id":"exchange-176"},{"speaker":"三上委員","kind":"確認","question":"振り込んだら振り込んだで、それで済んだという形で、確認は品川区がやらなきゃおかしいじゃありませんか。入ったお金について、事務的に連絡するという仕組みになればいいわけですから、それをなぜやれないのか。","respondent":"鷹倉庶務課長","answer":"今、申し上げましたとおり、これから消し込みを即座に私ども電算を使いながらとらえるようなことができれば、かなり時間的な制約が解消されますので、利用者にご不便をかけないような形の方向性が打ち出せると、このように考えてありますので、ご了解いただきたいと思います。","id":"exchange-177"},{"speaker":"松澤委員","kind":"質問","question":"実はこのプラン２１の新しい中にも何ページですかね、７ページに書いてありますけれども、１１月の中学生の新１年生希望申請集計表。今現在、実際にその学校、入学数は何人ぐらいいるのか尋ねました。","respondent":"久保田学務課長","answer":"当該の学校につきましては、入学予定者数９名です。","id":"exchange-178"},{"speaker":"松澤委員","kind":"質問・要望","question":"この９名という数字ですね、教員が一生懸命回っているんだ、教育委員会も一生懸命やっているんだという中で実際９名。これについてのコメントをほしいと求めました。","respondent":"青木指導課長","answer":"この９名の新入生が４月に参ります。学校としても精いっぱいの対応をしていきたいと思いますが、教育委員会といたしましても、今後の指導に生かしていきたいというふうに考えております。","id":"exchange-179"},{"speaker":"松澤委員","kind":"質問","question":"９人の子どもたちがいろいろある中で、この学校を選んでくれたんですからね。その９人のためにも、この学校はしっかりしなくちゃいけないと思いますので、その決意を一言聞きたいと思います。","respondent":"青木指導課長","answer":"私たちはほんとに重く受けとめて今後の指導に当たっていきたいと考えております。来年度の教育活動も、学校とともに教育委員会も全面的に支援してまいりたいというふうに考えております。","id":"exchange-180"},{"speaker":"松澤委員","kind":"質問・要望","question":"これについてコメントをということで伺いましたところ、意気に感じて意欲を持ち取り組もうとする教員、逆にそれを負担に感ずる教員など。もし人数がはっきりわかりましたら、わかる人数をお教えほしいと求めました。","respondent":"青木指導課長","answer":"今年度の異動の人数ですけれども、小学校の転出が１１２名、転入が９２名。中学校の転出が６２名、転入が５２名と、その予備調査と直接関係があるということではございません。","id":"exchange-181"},{"speaker":"松澤委員","kind":"質問","question":"たくさんの希望とそして転入者ということで、一応学級減、あるいは退職者、あるいは新規採用という中で、異動の、例えば聞きたいのは、転出希望した方には、皆さん転出希望どおり出せたということか尋ねました。","respondent":"青木指導課長","answer":"第二希望というようなところで、それぞれ行きますけれども、希望どおりもちろんいかないところもあります。第６希望で来られる方もいらっしゃいますし、バランスとしては、今の段階ではバランスよくいっているというふうに考えております。","id":"exchange-182"},{"speaker":"松澤委員","kind":"質問・要望","question":"ですから、どんどんＰＲして、日本全国からほんとにいい教員を採っていただいて、嫌だという教員はどんどん出しちゃう。ほんとに、どんどん全国的に展開をしていただきたいんですが、ひとつコメントをほしいと求めました。","respondent":"青木指導課長","answer":"品川区に行って、今の教育改革に取り組みたいと。そして新規採用ともに、今後とも教育委員会として、そうした教員を迎え入れて教育改革を推進していきたいというふうに考えております。","id":"exchange-183"},{"speaker":"松澤委員","kind":"質問・要望","question":"もう１問、実は、学校の校庭照明のことでお伺いしたいと思います。こういうプラン２１の中で、今回も補正の中で１校前倒しになりましたけれども、校庭照明を優先に考えるという考え方はできないか尋ねました。","respondent":"上川内生涯学習課長","answer":"スポレクエリア内に１カ所ということを目標にして、総合実施計画の事業として、推し進めております。今、１３年度末で１４校ということになっております。","id":"exchange-184"},{"speaker":"松澤委員","kind":"質問・要望","question":"そのときにサッカーをしてボールを転がしたい、大きなボールですから、そんな大きな照明は要らないと思うんですよ。片側からしてもいいわけですから、一つの何ていうんですかね、施設の一部として校庭を明るくしている。","respondent":"鷹倉庶務課長","answer":"スポーツ開放じゃなくて、夜間照明という形で、避難所的な機能を持つ意味での照明がついているところも何カ所かあります。近所回りから、できるところについては、先ほど申し上げた考え方をベースにしながら進めていってみたいなというふうに考えてあります。","id":"exchange-185"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/799186?Template=document&Id=796#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":134274,"voices":406}},{"id":"h14-20020322-3","meetingId":"h14-c-budget","date":"2002年3月22日","dateIso":"2002-03-22","committee":"予算特別委員会","time":"午前１０時０４分～午後６時０６分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を111件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（真）委員","kind":"提案","question":"質問をなるべく簡潔に、また基本的なところを確認させていただきながら、続けさせてほしいと求めました。最初に平成１４年度の予算編成について、お伺いをさせてほしいと求めました。","respondent":"中尾根企画部長","answer":"具体的に実施したときに、ほんとうの真価が問われるときが来るんではないかと、このように受けとめてあります。区としましては、全事業についての事務事業評価等も行うということによりまして、区民との信頼関係を深めていきたいと考えているところです。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"提案","question":"それを受けたほうの立場として、その施策の提案に対してどのようにとったのか。どのようにお考えでしょうか、その２点について、お答えをお願いしたいと思いますとの意見を述べました。","respondent":"中尾根企画部長、高橋区長","answer":"同時に設けました事業部経営会議をうまくやるにはどうしたいいかということを考えた結果として、プレゼンテーションという新しいことを試みました。各事業部関係の、この大きな原因はプレゼンテーションを行った結果ではないかと… 事業部制の問題ですが、確かに、２３区の中でも品川区が初めて実施をした一つの制度です。それぞれの部長がそれぞれの責任を持って事業を執行できる体制をより強力に進めていきますとともに、事業を進めてまいりたいという決意です。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"３年目の見直しと５年目の改定の部分の関係について、ひとつまず教えてください。事業の遂行に対して保険料が足りなくなってくるということが起きてくるのかどうか、そこの２点について、お答えをお願いしたいと思います。","respondent":"新美保健高齢事業部長","answer":"そういう意味では、介護保険法の制度の骨格そのものを国として検討をしていき、必要があれば見直しを実施するという規定になっているものです。５年目の制度の見直しで、保険料に大きく係わるような見直しがもし実施されるとすれば…","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"では、続きまして、第２期の保険料算定について、お伺いさせてほしいと求めました。一緒にお聞きしますが、その施策について、見直しをすることはできるのか尋ねました。","respondent":"新美保健高齢事業部長","answer":"第１期のときと違いまして、ほぼ２年余の実績が今回は明らかになっておりますので、平成１５年からの供給量を見込んでまいりたいと考えています。当然、介護保険対象サービス以外のサービスをいかにすべきかということも議論してまいりますので…","id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"質問","question":"多数一遍に質問させていただいたんですが、３点目に、お聞きしたいと思います。品川区として施設サービスをどのようにとらえていくのでしょうか、その点について、お答えをお願いしたいと思います。","respondent":"新美保健高齢事業部長","answer":"あるいは、その重度化等々を十分勘案して、必要な施設サービスの整備というものを検討していく必要があると考えております。介護保険事業計画の改定の中でも検討していくわけですが、多様な施設のあり方について十分検討し、必要な量を確保していきたいと考えております。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"次に、介護保険の準備基金について、お伺いさせてほしいと求めました。この辺について、大切に扱っていただきたいという思いの中から、お答えをお願いしたいと思います。","respondent":"新美保健高齢事業部長","answer":"私ども、平成１１年度までの実績に新制度移行の要素を加味して第１期の給付額の見込みを立てたわけですが、１３年度の利用実績が少なかったです。継続的、今後の作業の中で十分検討をし、制度が安定的に運営できるための基金として活用できるようにしていきたいと考えております。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それともう１点、移転後の建物の利用、それから、取り壊しという問題に関しては、国の予算もまだ全くついていないとお聞きしています。医療態勢という意味と、２点、お答えをお願いしたいと思うんですが、。","respondent":"新美保健高齢事業部長","answer":"地域の住民が医療面での不安がないような対応を、あるいは病院と十分対応がとれるようなことを検討するようにしていきたいと考えています。管理をしているところと十分連絡をとり、地域の方に不安がないような対応ができるよう、連絡をきちんと密に取っていきたいと考えています。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問","question":"決して再開発をすぐに考えてくださいという意味の質問ではありません。それを前提にして、お答えをお願いしたいと思うんですが、。","respondent":"岩野まちづくり事業部次長","answer":"実際に再開発を実施しても、現況のように、戦後のああいったような形で残っているです。２６号線を挟んだ向かい側のＢ地区に東京臨海高速鉄道(株)が持っている土地がありますので、何からのアプローチを考えていきたいと考えています。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その辺も考えていくと、どうなのかという点が１点あるんです。他の事業部とどのようなつながりを持っていらっしゃるのか、その２点について、お答えをお願いします。","respondent":"岩野まちづくり事業部次長","answer":"やはり商業調査等を行いまして、その過程で、例えば当時の商工課等と連携を図りながら進めておりました。補助１６３号線が一本橋の商店街を通りますので、その前から、今で言います産業振興課と連携をとりながら進めているところです。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問","question":"これを出すことについて、区としては、補助金だけの範囲でタッチしていくのか、もう少し深く入っていくのか、その辺の１点。システム体制について、どのようにお考えになっていらっしゃるのか、その２点をお願いいたします。","respondent":"小栗区民生活事業部長","answer":"取り組みの中で、区といたしましては、地域の魅力づくりに向ける意識に関心を高めていただくような努力をしてまいりたいと考えているところです。あるいは各種地元スポンサーの協力を得まして、こういう方々とコーディネートをするような役割を…","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"品川区として、市街地活性化事業自体を考えていくことはできるのでしょうか。広域的な広がりを結びつけるための検討をどういうふうに考えていらっしゃるのか、その点について、お答えをお願いいたします。","respondent":"小栗区民生活事業部長","answer":"活性化の取り組みに対しまして国庫補助が使える事業ですが、この補助事業を活用することは難しいだろうと考えています。大井銀座商店街が取り組む情報システムを開発し、大井町の再構築に実践的な取り組みを展開していく方法を検討していきたいと考えているところです。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"というのは、外郭団体でしたら区自体ではないんですから、第３者にその情報が出てしまう。その２点について、お答えをお願いしたいと思います。","respondent":"相川収入役","answer":"不安が出てきた金融機関につきましては、当然、その情報収集に努めた上で、どの程度不安があるのか、それによって対応が変わってくる。そのほか、何か緊急な事態が出れば、その都度それには対応していくと考えているものです。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうすると、基本的に出るのは、運用方針を外郭団体に伝えるということでよろしいのでしょうか。運用方針だけが出るということで、よろしいわけですね。","respondent":"相川収入役","answer":"これは、運用方針だけを説明しています。","id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問","question":"１３億円ありますが、平成１４年度は、利子補給制度などを検討した上での継続なのか。それともう１点は、どのような検討をなさっているのか、お答えをお願いしたいと思います。","respondent":"小栗区民生活事業部長","answer":"具体的な検討といたしましては、預託金の廃止、それから、利子補給制度の切り替えといったようなことを検討してまいりました。円滑な融資あっ旋制度を継続するには、平成１４年度については、預託金の継続を決定させていただいたところです。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ですから、この辺のところは十分に検討しながら、改正の方向に向かっていただきたいという思いがあります。その辺、ちょっとお答えをお願いしたいと思います。","respondent":"小栗区民生活事業部長","answer":"産業振興を所管する部の思いですが、同じ産業振興の新しい時代に応じたニューニーズに支援できるような施策を充てていきたいという思いがあります。しかし、検討する際には…","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"現在の融資あっ旋は、あっ旋はしていただけるけど、現実に事業主にとって、使いたい資金が使えないというケースもかなり出ております。この辺のところも十分な対応をお願いしたいの同時に、１３億円の基金を取り崩した際には、私の質問を終わらせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"塚本委員","kind":"意見","question":"私どもの主張と違っております。大変不適当であると認識しておりますので、人権問題に関連する人権教育について、改めてどうお考えか質しておきたいと思いますとの意見を述べました。","respondent":"指田教育次長","answer":"学校教育で、とりわけ人格形成期にあります小中学校において、人権尊重教育を推進することは非常に重要なものであると認識しています。こうした観点から、先般の款別審査での上山委員の発言につきましては、私どもといたしましては到底受け入れがたい発言であると認識しています。","id":"exchange-017"},{"speaker":"塚本委員","kind":"質問","question":"次に、都区制度改革に関連してお伺いいたします。どこをどう苦労されて、４年後の見直しにどういう準備をすべきであるかということに関して、ご見解を伺いたいと思います。","respondent":"野本環境清掃事業部長","answer":"輸送事業という格好で対応するのか、３度と動き回っているわけですが、どうも中途半端になりやすい。こういうことを考えますと、直営という形ではとてももたないだろうと認識をしておりましたので、いろいろな施策をさせていただいてきたわけです。","id":"exchange-018"},{"speaker":"塚本委員","kind":"質問","question":"１年前にそのことが決まっても構わないわけですから、今がちょうどその仕組みをつくる時期であると思います。２３区がどう仕組みを変えていくかについて提言をできる立場にあると、この件に関してご見解があれば、伺っておきます。","respondent":"野本環境清掃事業部長","answer":"そういう中で考えてみますと、端的に言えば、平成１８年に竣工する大井清掃工場の能力をどう使うのか。総合的なサービスという面で認知されるのか、あるいは、輸送業という格好で徹底していくのかということが問われる時間になるのかなと考えております。","id":"exchange-019"},{"speaker":"塚本委員","kind":"質問・要望","question":"なかんずく第３セクターに仕事の場を求めて、端的にあらわれたこの事態は、何らかのサインであると理解しております。このことに関して、人を送り出すほうの責任者として、お考えがあれば、ご見解を承りたいと思います。","respondent":"高橋区長","answer":"皆さんからいただきましたご提言等を参考にいたしまして、早急に、特に人事に刷新を図ってまいりたいと考えています。それから、民間の方々のお力をお借りをして、より区民の意見に沿った団体の運営に徹していきたいと考えています。","id":"exchange-020"},{"speaker":"塚本委員","kind":"質問","question":"よく働いた人、能力のある人が６０歳以降も力を出せる仕組みがあるということは、モチベーションとして大事なことであるという認識も持っております。この件に関して、ご見解があれば、伺いたいと思います。","respondent":"本間総務部長","answer":"区民の皆様にも、年に１回、職員の給与等を公表しています。年俸制まではまだ行きませんが、そういう状況ですので、ひとつご理解のほどをお願いいたします。","id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"モデルをつくって、何号、何等なんて言ったってわからない人が多いわけですから、私もよくわかりません。そのことを言っているわけですから、もう一度、お答え願いたいと思います。","respondent":"本間総務部長","answer":"その点につきまして、年に１回、広報「しながわ」で、我々職員の平均的なモデルを取りまして、それぞれの給与だけではなくて、いただいている手当等、超勤も含めまして、すべて区民の皆様に、現在、公表しています。","id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"それに関連して、お伺いいたします。改めまして、ここに至った経過について、どのように認識をされているか伺いたいと思います。","respondent":"中谷まちづくり事業部長","answer":"りんかい線が、本年１２月にいよいよ全線オープンという形になります。区といたしましては、このような地域の皆さんに、常日ごろからいろいろな形で感謝を申し上げているところです。","id":"exchange-023"},{"speaker":"塚本委員","kind":"質問","question":"区は、これにどう臨もうとしているのかということが１点。私は思っておりますけれども、この２点について、お伺いをいたします。","respondent":"中谷まちづくり事業部長","answer":"区では、今後、活性化を進めていく上で、地域の推進体制についても、いろいろ考えなくてはいけないです。今後とも、いろいろな場面で、区としての働きかけをしてまいりたいと考えているところです。","id":"exchange-024"},{"speaker":"塚本委員","kind":"質問・要望","question":"せっかく大変な機会です、また、１２月までにはまだ時間があります。そういうものをどうぞ掘り起こして、人のネットワークをつくっていただきたいと念願しておりますけれども、いかがでございましょうか。","respondent":"高橋区長","answer":"私は、「大井町の商店街の皆様方が何をしようかということをお考えになるほうが先ではございませんか」ということを申し上げてきております。４月に入りまして、具体的にどのような事業ができるか検討し、区も一緒になって検討してまいりたいと考えています。","id":"exchange-025"},{"speaker":"塚本委員","kind":"意見","question":"ひるがえって、このまちの道路のアクセスはどうなっているのかということを心配する声が、あちこちで聞こえてまいっております。道路のアクセスに関してどのように考えていられるか、ご見解を承りたいと思いますとの意見を述べました。","respondent":"中谷まちづくり事業部長","answer":"区として、かねがね大井町駅周辺の交通アクセスを改良するために検討しておりまして、その一つが補助１６３号線。駐車が交通渋滞の一因でもあると認識しておりまして、いろいろここの違法駐車対策の啓発活動を強めておりまして、キャンペーン等も行っております。","id":"exchange-026"},{"speaker":"塚本委員","kind":"意見","question":"それを促進させるには、今までのやり方でいいのかどうか、そこに根本的な反省のメスを入れるときに来ていると思うんです。そこをお知らせ願いたいと思いますとの意見を述べました。","respondent":"中谷まちづくり事業部長","answer":"まちづくりの中で道路を１２ｍ拡幅し、補助２０５号線の整備を同時に行うなど、いろいろな部分で都市基盤の整備を行ってまいりました。こういうふうにまず自分でできることを進める中で、こういう問題については東京都と連携し…","id":"exchange-027"},{"speaker":"塚本委員","kind":"質問・要望","question":"与えられた条件でもって最適の解答を求める、よくなるんだ、そのことに向かって努力をしようという意識が欠けている点があると思います。国民の福祉にどう最有効に使われるかという視点に立てば、もう一度、重ねて伺います。","respondent":"高橋区長","answer":"したがいまして、この問題につきましては、将来、東京都に、２６号線対策として強く要望をしてまいります。２６号線対策の一番の問題は、区役所通りから仙台坂の問題で、私はいつもその前を通るたびに考えている、一つの大きな問題です。","id":"exchange-028"},{"speaker":"塚本委員","kind":"質問・要望","question":"このことが果たして、子どもにとっていいことなんでしょうか。明らかになってきておるわけですから、各施策の最適の解答を求めていく今の状況について、大変な危惧を持っている。","respondent":"小沼福祉事業部長","answer":"子育ての基本的な考え方をどこの視点に置くかということにつきましては、欠けているところ、行政として支えていくというのが基本的な考え方です。ですから、必ずしもすべてにおいて国の、あるいは都のというところで迎合しているとは、私どもとしては考えてございません。","id":"exchange-029"},{"speaker":"塚本委員","kind":"意見","question":"私も、その認識から出発してほしいと考えています。ご静聴、ありがとうございましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"中島委員","kind":"質問","question":"そこで、仮称家庭あんしんセンターの事業内容についてお伺いしたいと思います。トワイライトステイを利用する場合の申込み方法や、事業などの利用者の負担はどのぐらいを想定されているのでしょうか、お伺いいたします。","respondent":"小沼福祉事業部長","answer":"ファミリーサポートセンター関係での利用者の負担を中心としての問題ですが、現在、私どもとしましては、ご利用の会員の方につきましては、時間で８００円程度の料金ということで、援助会員と賛助会員間でのやり取りということを基本に考えてあります。","id":"exchange-031"},{"speaker":"中島委員","kind":"質問","question":"今、手続のことはおっしゃっていただきましたか尋ねました。","respondent":"小沼福祉事業部長","answer":"申しわけございません。どういう人を好むとか、あるいは、ファミリーサポートセンターのほうで当然かかわることになるということでご理解いただければと思います。","id":"exchange-032"},{"speaker":"中島委員","kind":"質問・要望","question":"これは、電話でも申込みができるのでしょうか。せっかくできたいい事業ですので、手続はできるだけ簡素化をしていただきたいという要望もあって、今、質問させていただきました。","respondent":"小沼福祉事業部長","answer":"保育所等で考えてありますような定形的な保育サービスと違いますので、欠けないというようなことを主として問うというものではございません。負担の問題ですけれども、先ほど、申し上げましたけれども、私どもとしましては、今の段階では…","id":"exchange-033"},{"speaker":"中島委員","kind":"質問・要望","question":"このファミリーサポートセンターの事務局をこの４月から立ち上げると伺っておりますが、ぜひ、実現していただきたいと願っております。この点について、どのような運びとなっているか尋ねました。","respondent":"小沼福祉事業部長","answer":"ファミリーサポートセンターでの子育ての支援事業の一つとして、それから保健所等との連携の問題を含めて、積み上げているという段階です。","id":"exchange-034"},{"speaker":"中島委員","kind":"質問・要望","question":"ぜひ、前向きに展開をしていただきたいと要望をしておきます。この協議会の構成メンバー、開催回数、検討する具体的な内容などをお知らせください。","respondent":"小沼福祉事業部長","answer":"検討の内容といいますか、こちらで考えてあります点は、いわゆる情報の共有に関することが１点あります。おおむね２カ月に１回程度、迅速、機敏な対応をするという考えでおります。","id":"exchange-035"},{"speaker":"中島委員","kind":"質問","question":"そうしたときに、児童相談所がうまく機能してくれないという苦情が寄せられております。この点に対しては、どのようにお考えか尋ねました。","respondent":"小沼福祉事業部長","answer":"そこを共通のキーワードとして、両方で臨んでいく、取り組んでいくということを考えてあります。ちょっと時間がかかったとか、あるいは、ちょっと見当違いであるというようなことがないような形でのやり取りをして進めていきたいと考えています。","id":"exchange-036"},{"speaker":"中島委員","kind":"質問・要望","question":"ほんとうに子どもの安全のために、ぜひ、強力に進めていただきたいと要望しておきたいと思います。その際、区民の方から、「害虫駆除はどうなっているんですか」という声がたくさんありました。","respondent":"中谷まちづくり事業部長","answer":"公園管理人、あるいは地域の方々から通報をいただき次第、速やかなる駆除を行っているです。今後、こういうものにつきましても、さらに充実に努めてまいりたいと考えているところです。","id":"exchange-037"},{"speaker":"中島委員","kind":"質問","question":"建築課では、先日、解体業者に、事前の駆除をするように指導されていると伺いました。その後に、駆除をしたという報告を受けるなど、チェックはされているのか尋ねました。","respondent":"山室住宅指導担当部長","answer":"ネズミ駆除の問題ですが、窓口での解体の指導はしておりますが、確認というのは特段しておりません。","id":"exchange-038"},{"speaker":"中島委員","kind":"質問","question":"この点は、ぜひ強化してほしいと思います。品川区のホームページにもネズミ対策が載せられておりますが、ほかにどのような対策を考えて、実施されているのか尋ねました。","respondent":"新美保健高齢事業部長","answer":"町会に殺鼠剤を配付し、地域でネズミ駆除の取り組みをしていただくということを、年１回やっております。そのほか、個別のご相談があれば、助言や、必要な事業所の紹介等を行っているところです。","id":"exchange-039"},{"speaker":"中島委員","kind":"質問","question":"続きまして、大井町駅周辺の整備および駐輪対策について、お伺いいたします。エレベーター２基と、障害者用のエスカレーターが設置されるとありましたが、障害者用のエスカレーターはどこに設置されるのか尋ねました。","respondent":"中谷まちづくり事業部長","answer":"バリアフリー対応のエスカレーターですが、りんかい線のホームから地上までのエレベーターに対応できるような形になっております。","id":"exchange-040"},{"speaker":"中島委員","kind":"質問","question":"既に設計はできているんでしょうが、あくまでも利用者の視点に立って、再度、細かいチェックをお願いしたいと思います。この手前にプランターが置かれているんですが、あれは何のために置かれているんか尋ねました。","respondent":"中谷まちづくり事業部長","answer":"大井町駅阪急前のプランターですが、この場所は、以前は放置駐輪が二重、三重になっておりまして、区民の皆さんから陳情をいただいておりました。そして、ここの歩道の整備を行った際に、植え込みとともにプランターを設置しまして…","id":"exchange-041"},{"speaker":"中島委員","kind":"質問","question":"そのときに、「路上の駐輪は」と言われたんですが、じゃあ、自転車はだめでも、プランターはいいのでしょうかと逆に質問をしたと思います。そういった意味で、大井の陸橋化だけでは足りませんので、今後の課題だと思いますが、どのような計画をなさっているかお知らせください。","respondent":"中谷まちづくり事業部長","answer":"りんかい線のオープンを控え、大井町駅の駐輪対策につきましては、検討しなくちゃいけないと考えております。委員、ご提案の阪急前の駐輪のラック設置等につきましても、自転車の動向を見ながら検討していかなくちゃならない課題だと考えております。","id":"exchange-042"},{"speaker":"中島委員","kind":"質問・要望","question":"３人に１人が、この点について、品川区としての対策をいろいろなさっていると思います。きょうは、ケーブルテレビも入っておりますので、ＰＲも兼ねて、アレルギー対策についてお答えほしいと求めました。","respondent":"青山品川区保健センター所長","answer":"あるいは、ダニの状態を見た上で、ご指導申し上げるということをいたしております。専門の職員が対応いたしますとともに、ご要望に応じまして講演会や座談会等の中でも、お話し申し上げているところです。","id":"exchange-043"},{"speaker":"中島委員","kind":"質問","question":"これからは、いわゆるバリアフリーから、だれにとっても使いやすいユニバーサルデザインへ整備をしていくことが大事ではないかと思います。品川区の第２次いきいき計画というのがありますが、ここにシニアの目線をどのように入れているのでしょうか、お伺いいたします。","respondent":"新美保健高齢事業部長","answer":"第２に、健康づくりプラン２１ということで、健康づくりに力を入れる。第７のプロジェクトで、障害者の視点でまちづくりを進めるなど、かなりシニアの視点を入れたつもりです。","id":"exchange-044"},{"speaker":"中島委員","kind":"提案","question":"ステップ２という福祉改革が打ち出されておりますが、地域全体で継続的に見守っていくために、ひとり暮らし高齢者カルテの作成を提案いたしました。しっかり応援したい」という答弁をなさっておりますが、この点について、区としてはどのようにお考えか尋ねました。","respondent":"新美保健高齢事業部長","answer":"先ほども出ました第２次いきいき計画２１の中で、重点プロジェクトに、自立支援ネットワークの充実というプロジェクトを掲げております。地域活動課等々、関係部署が協力し合って、区民の参加のもとに、見守りのシステムを今後充実していきたいと考えております。","id":"exchange-045"},{"speaker":"中島委員","kind":"質問","question":"しかしながら、これがわからなかったということなんです。この辺について、どのようにお考えか尋ねました。","respondent":"新美保健高齢事業部長","answer":"介護の場合は支援センターという形で、お電話一本、あるいは民生委員の通報等で対応できる仕組みになっております。あるいは高齢者クラブ、そういった方々との協力の中で、どこまでサポートができるかというのがかぎになるかと思います。","id":"exchange-046"},{"speaker":"中島委員","kind":"質問・要望","question":"先ほども申しましたが、高齢化社会２０２５年には３人に１人が高齢者、３世帯に１世帯が６５歳以上の高齢者世帯となると言われております。ですから、しっかりこれから計画を立てていただきたいと要望いたしまして、私の質問を終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"鶴委員","kind":"質問・要望","question":"２月２７日の代表質問における再質問の際に、うそをついている、こんなやり方が今回の事態を招いた。今後の是正課題など、調査結果に基づいて、区民の皆さんにわかりやすい説明をまず求めます。","respondent":"中尾根企画部長","answer":"１点目の、昭和６１年設立以来、国の公益法人会計基準に基づきましてさまざまな運用をしてまいりました。その後、平成１２年に入りまして、国際的な経済変化が出ましたので、機会を見て処分を進めておりました。","id":"exchange-048"},{"speaker":"鶴委員","kind":"質問・要望","question":"監督責任を求められている理事長も、新しい体制のもとで、事業団への信頼回復に努めるべきであると進言をいたします。区長の潔いご決断を期待し、改めて、ご所見を伺っておきたいと思います。","respondent":"高橋区長","answer":"私は、４月中にそれぞれの外郭団体の総会を開いていただきまして、そこで辞任をする覚悟で、今いるわけです。これから区長に専念するために、全部辞任をする気持ちで、理事会を開く予定になっております。","id":"exchange-049"},{"speaker":"鶴委員","kind":"質問・要望","question":"品川区職員服務規程第２条および第３条はどういうふうになっているか。品川区職員氏名札着用規則第１条および第３条の規程、ならびに現在の氏名札の定められた様式がどうなっているかも、ご説明ほしいと求めました。","respondent":"本間総務部長","answer":"第１項は、「職員はみずからの行動が公務の信用に影響を与えることを認識するとともに、区民の疑惑や不審を招くような行為をしてはならない」。それから最後に、氏名札の様式ですが、縦２０mm、横５０mm、中には、区の紋章と、氏名のうちの姓のみを記載しています。","id":"exchange-050"},{"speaker":"鶴委員","kind":"提案","question":"昨年３月の予算特別委員会で、私は、ノーネクタイの導入を強く求めましたが、その立場から、その省エネ効果に注目しております。昨年３月の予算特別委員会で、私があわせて提案したカラー写真つきで、「貴重なご意見をちょうだいしたとの意見を述べました。","respondent":"本間総務部長","answer":"今の氏名札に変えてからあまり年数が経っていないことから、対費用効果等々、いろいろと検討をしています。このようなことから、今後、サマールックキャンペーンの実施の状況等も加味しながら、引き続いて検討していきたいと考えているところです。","id":"exchange-051"},{"speaker":"鶴委員","kind":"質問・要望","question":"ホームレスになるしかありません」と言ったところ、「どうぞ、ホームレスになればいいじゃないですか」と言われたんですと。先日の事例ということですから、担当職員に事実関係を確認されていることと思いますので、事実を明らかにしてほしいと求めました。","respondent":"小沼福祉事業部長","answer":"私のほうも、事実とすれば大変由々しき問題ですから、即刻調べました。結論から申し上げますと、私ども職員のほうから、「ホームレスになればいいじゃないか」と言ったことはございません。","id":"exchange-052"},{"speaker":"鶴委員","kind":"質問・要望","question":"そこで売っているズボンは、まちで買えば２,０００円ぐらいのものが６,０００円もする」と紹介し、改善を求められました。あわせて、支援センター等では、６,０００円もするズボンなどの生活用品も販売している事実があるのか、ないのか、お知らせほしいと求めました。","respondent":"小沼福祉事業部長","answer":"１３日の昼について見ますと、帆立ての酢みそあえ、それから香の物というようなものを供されてあります。〔「大田寮でも支援センターでもない」と呼ぶ者あり〕","id":"exchange-053"},{"speaker":"鶴委員","kind":"質問・要望","question":"〔「場所が違う」と呼ぶ者あり〕 違うんだったら、その委員会のときに言えばよかったじゃないですか。事実確認を怠り、関係者の名誉を棄損したり、人権を侵害することもあります。","respondent":"本間総務部長","answer":"オストメイトについてのご説明ですが、大腸ですとか、小腸、それから直腸、膀胱等の悪性腫瘍疾患のために、延命手段として、外科的に疾患部の全部または一部の切除手術を受けて、腹部に排泄のためのストーマー、つまり排泄口を設けた方を言います。","id":"exchange-054"},{"speaker":"鶴委員","kind":"質問・要望","question":"品川区でも、約２３０人の方が社会復帰をし頑張っていらっしゃいます。品川区にも１カ所もありませんが、品川区内の公共施設をはじめとして、対応策を求めておきたいと思いますが、いかがか尋ねました。","respondent":"本間総務部長","answer":"お尋ねのオストメイト対応トイレですが、交通バリア法に基づく整備基準では、駅の中のトイレにつきましては設置が義務づけられております。本格的なオストメイト対応のトイレの設置には一定のスペースが必要であるとか、簡易な手法です…","id":"exchange-055"},{"speaker":"鶴委員","kind":"提案","question":"ところで、この公衆トイレが、オストメイト対応トイレの品川区における第一歩だと言われるような工事をやっていただきたいということを提案します。ご答弁を求めますとの意見を述べました。","respondent":"中谷まちづくり事業部長","answer":"今般、委員、ご指摘のとおり、大井町駅東口に、スロープの下に公衆トイレをつくることになっております。だれでもトイレを設置する予定ですので、オストメイトの簡易型のものについて、設置する方向で検討してまいりたいと考えております。","id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"我が党は、人権教育は大事であり、男女差別、障害者差別、思想差別をなくすことは、憲法が求めている課題だと考えます。品川区のこの３年間の認定実績について、説明を求めました。","respondent":"新美保健高齢事業部長","answer":"控除額ですが、一般控除が、所得税で２７万円、特別障害が４０万円です。平成１２年が４件、１３年が６件、１４年に入りまして３件です。","id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今の部長のお答えですと、ねたきり老人だけということですけれども、昭和４５年、１９７０年の拡大の所得税法施行令第１０条第１項の７号についての拡大された中身についてお聞きしましたので、そのことについてのお答えをお願いします。","respondent":"新美保健高齢事業部長","answer":"先ほど申し上げました社会局長通知そのものは、障害者控除の拡大という通知ですけれども、ねたきり老人につきましての取り扱いは、昭和４５年通知以降、基本的に変わっていないものです。","id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"例えば障害者控除を受けられる３から６級に準ずるもの、これがどの程度のものなのか、具体的にお示しほしいと求めました。呼吸器障害、そして下肢不自由の方、この場合について、お答えほしいと求めました。","respondent":"新美保健高齢事業部長","answer":"したがいまして、３から６級というような軽度の部分について、特段の認定基準はございません。したがいまして、特段、想定人数は、今、持ち合わせておりません。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"「片下肢障害のため、１ｍ以上歩けない」等さまざまあるわけですけれども、こういう方も３から６級に準ずるという判定書になっていると思うんです。こういうことで言えば、認定を受けている方のかなりの部分が認定証の発行が可能かと思うんですが、その点については、いかがか尋ねました。","respondent":"新美保健高齢事業部長","answer":"ねたきり老人の障害者控除の判定は、６カ月以上の臥床状況、さらに、常時、排泄、あるいは食事といったところでの介助が必要というのが基本的な認定基準で、従来から認定をしているものです。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、「身体障害者に準ずる者」という形で障害者控除の対象になるという方向がきちんと出されているわけですから、調査をしてほしいと求めました。それをさらに拡大するという形で、「準ずる者」が控除を受けられるという通知が来ているわけですから、きちんと調べてほしいと求めました。","respondent":"新美保健高齢事業部長","answer":"ただいま、ご答弁申し上げましたのは、従来、または現在の対応についてお答えをしたものです。しかしながら、いろいろとご質問等もありますので、引き続き調査はしていきたいと考えております。","id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"時間がなくなりましたので、次の質問に移らせてほしいと求めました。はじめに、特別養護老人ホームの入所希望者の推移について、平成１３年２月末、９月末、そして、今年の２月末で締め切った申請数を説明を求めました。","respondent":"新美保健高齢事業部長","answer":"これまでもご説明しましたとおりケアハウス制度に特定施設を組合せ、上乗せ負担をいただいて、個室でユニットケアをする施設です。いろいろなところにお入りの方の経費負担を伺いますと、一定の負担をされている方も多うありますので、希望の方はいらっしゃることと考えています。","id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"半年間に入れる人数は９０人ということですけれども、今回で言えば５２２人、残りの４３２人に対して、区はどのように考えているんでしょうか。今後、入所希望者がどんどん増え続けると思うんですけれども、区はどのように対応しようとしているのか説明を求めました。","respondent":"新美保健高齢事業部長","answer":"しかし、再申込みの方で見ますと、２０％程度に下がる。老人保健施設等の施設もありますので、その分どうしても、そういったところでの待機の方もいらっしゃるという傾向が見えているところです。","id":"exchange-063"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今回で言えば、半年間で入れない残りの４３２人に対して、どう考えているのかということについて説明を求めました。","respondent":"新美保健高齢事業部長","answer":"入れるまでの間の在宅サービスをより使っていただくようなケアマネージメントに努めますし、老人保健施設の利用についてのご相談があれば、乗っていきたいと考えております。","id":"exchange-064"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところで、ぜひ、特別養護老人ホームを建設していただきたいというのが要望です。今回、厚生労働省が新型特別養護老人ホームを打ち出していますけれども、それの内容と、利用料に対しての区の考え方について、説明を求めました。","respondent":"新美保健高齢事業部長","answer":"これまでも取り組んでまいりまして、ケアハウス制度を使って特定施設、介護保険制度も活用した個室ユニットケアの介護施設を建設しております。区としましては、特別養護老人ホーム以外の多様な形の入所型の介護施設を、これからもいろいろ工夫をしていきたいといった考え方です。","id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今度の新型特別養護老人ホームも視野に入れて、ぜひ、検討をしていただきたいと思うんですが、いかがでしょうか。どういう特別養護老人ホームにしていくのか検討しながら、特別養護老人ホームの建設をしていただきたいと思うんですが、いかがか尋ねました。","respondent":"新美保健高齢事業部長","answer":"やはりスタッフ配置を従来より厚めにしないと、質の高い介護はできないのではないかということがありまして、ケアホームでは考えているものです。品川区におけるスタッフの確保という面から、きちんと考え、検討していく必要があるというのが大きな点かと考えております。","id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"実際は１００ベッドしかありませんから、２７０名は他区にお世話になっているという状況だと思うんです。この都南総合病院の跡地を、ぜひ区が取得して、特別養護老人ホームと老人保健施設の建設をしていただきたいと思うんですけれども、いかがか尋ねました。","respondent":"新美保健高齢事業部長","answer":"今のご質問のようなことについては、考えてございません。","id":"exchange-067"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これだけ増え続けているのに、みんなが入れる特別養護老人ホームをなぜつくらないんでしょうか。改めて、区民の切実な願いである、すべての階層が入れる特別養護老人ホームと、老人保健施設の建設を強く要望して、質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"菊地委員","kind":"質問","question":"４月中に理事長を辞任をするという意向をお話してくださいましたけれども、区民に対する謝罪であると、このように受けとめてよろしいんでしょうか。私は、区長の集中審査のときの認識と若干違うのかなと思うんですけれども、その辺の見解を説明を求めました。","respondent":"高橋区長、中尾根企画部長","answer":"本会議のときにも申し上げましたけれども、品川文化振興事業団の運営に対しまして、大変申しわけなく思っておりまして、おわびを申し上げましたところです。 この間の購入の経過についての、そういう発言の問題ですけれども、区長のほうは、この予算特別委員会でも発言しましたのは、ご自分の経験等から、資金運用の方法や考え方についての感想を述べられた、こういうことです。","id":"exchange-069"},{"speaker":"菊地委員","kind":"質問","question":"先ほど、この間の経過について述べておられましたけれども、３億１,０００万円の外国債を事業団が購入した経過について、改めてお聞きしたい。副理事長にどのような調査を行って、どのような返答を得たのか、この点についてお聞かせを願いたいと思います。","respondent":"中尾根企画部長","answer":"調査した結果として、どういうことが問題点としてあるのか、その対応はどうすればいいのかということを中心に調査したというものです。実質的には、平成１４年１月からいろいろ行いました。","id":"exchange-070"},{"speaker":"菊地委員","kind":"質問","question":"私がお聞きしたのは、現在の理事長、それから副理事長にどのような調査を行ったのか、どのような返答を得たのか、このことをお聞きしました。","respondent":"中尾根企画部長","answer":"そういうやり取りの中で、そのときの立場の部分については、各部分として確認をしているということです。それを逐次報告する中で、理事長としての立場としては、どうだったのかという確認行為をしています。","id":"exchange-071"},{"speaker":"菊地委員","kind":"質問","question":"報告書、まとめについて、実際は満足をされておられるんでしょうか。この辺の見解を、ちょっとお聞かせを願えますか。","respondent":"高橋区長","answer":"特に内部の詳細な処務規程等々についての精査を行い、このような事故をこれから二度と起こさないような方法をとるというような調査書でございました。私は、それで満足をしています。","id":"exchange-072"},{"speaker":"菊地委員","kind":"質問・要望","question":"そもそも、区長、格付ＢＢ債を買ってもいいものだと考えているのか、それともだめだと考えているのか。この辺を明確にしてほしいと求めました。","respondent":"高橋区長","answer":"再三申し上げております。ごっちゃにしますと、この問題はまた何か霧の中に入ってしまいますので、よろしくお願いいたします。","id":"exchange-073"},{"speaker":"菊地委員","kind":"質問","question":"外国債を買うことはいいんだと、それじゃＢＢ債はどうなんですか。ここのところに区長は問題意識を持たれたんじゃないか尋ねました。","respondent":"高橋区長","answer":"ＢＢ債がいいか悪いか、これはその性格、またこれからの経済情勢等が問題になると考えています。安全性のないものには手を出さない、これが、本来の運営の仕方じゃないかと考えています。","id":"exchange-074"},{"speaker":"菊地委員","kind":"質問","question":"これは、決して言葉尻の問題ではなく、調査会そのものの問題ではないでしょうか。ちょっとお聞きします。","respondent":"高橋区長","answer":"「いや、私はそういう株の問題については、あまりよく存じておりませんでした」という返事が返ってまいりました。ですから、財政通が即株について精通しているとは言いきれません。","id":"exchange-075"},{"speaker":"菊地委員","kind":"確認","question":"ただ、今回の事件というのは、確認書にあるとおり、最初から元本割れを起こすリスクが説明をされていたわけですよね。なかなか確認ができなかったということですけれども、この間、信じがたいような組織形態を持っていると思います。","respondent":"中尾根企画部長","answer":"予定をされてありますが、３月１５日、こういうふうに説明を受けてあります。もし、予定額は１４５万５,０００円ほど入ることになっておりましたので、貸借対照表と財産目録に未収入金として計上するということになります。","id":"exchange-076"},{"speaker":"菊地委員","kind":"質問・要望","question":"実質的に３億１,０００万円の原資というのが区民の財産であることは明らかですから、いろいろな形で、区のほうも調査をしてきたんだと思います。この辺に責任を持つのかどうか、ちょっとお聞きしたいと思います。","respondent":"高橋区長","answer":"私の財産を投入して負債を埋めるという考え方は、今、持っておりません。間違えないようにしてください。","id":"exchange-077"},{"speaker":"菊地委員","kind":"質問","question":"だからこそ、いろいろな問題が、区民の間からいろいろな声が起きてているんじゃないですか。ちょっとその点、説明を求めました。","respondent":"高橋区長","answer":"それをひとつ、忘れないでいていただきたい。監督責任を取ってやめるということを、何回も言明をしているわけですから、これ以上聞かないでください。","id":"exchange-078"},{"speaker":"菊地委員","kind":"質問・要望","question":"就任当初は、確かに、知り得ないかもしれませんけれども、アルゼンチン国債を購入したのは、その１カ月ほど後でしょうか。実際に、理事長に対して確認をとるという作業をなぜしなかったのかというところを、お教えほしいと求めました。","respondent":"中尾根企画部長","answer":"比較されていたＡＡというものについては、これはアメリカですけれども、１.幾つというようなことでした。したがいまして、そういう格付けなり、利率なり等をいろいろ検討したという経過の中で、やはり利率の高いものを選んでいったと受けとめてあります。","id":"exchange-079"},{"speaker":"菊地委員","kind":"確認","question":"事務局長についても、お聞きしているんです。なぜ、理事長に確認をとる作業をしなかったのか。","respondent":"中尾根企画部長","answer":"前副理事長から、「このことについて、理事長のほうへの報告はしなくていい」と言われたということ。それと同じことでいいのだ」と、こういう上司の命令でしたので、それに従ったです。","id":"exchange-080"},{"speaker":"菊地委員","kind":"質問","question":"とすると、その時点で、前副理事長が、処務規程ですとかを無視したんだということになんでしょうか。もう一度。","respondent":"中尾根企画部長","answer":"調査の結果は、そう判断せざるを得ないです。","id":"exchange-081"},{"speaker":"菊地委員","kind":"質問","question":"副理事長、お聞きしますけれども、事務局長から就任時に報告を受けたということですけれども、これは２０００年の１１月か１２月ということです。それから、理事長に相談をしなかった理由について、もう少し明確に述べてほしいと求めました。","respondent":"濱野助役","answer":"いわゆる債権というのは、大体１００％で推移をして、アルゼンチン国債について特段低い評価ということではなかったと記憶しています。いずれにしましても、そういうことで、新しいものについては安全なものに切り替えるように、そして…","id":"exchange-082"},{"speaker":"菊地委員","kind":"質問","question":"ＢＢ債について、副理事長は疑問を持たなかったのか。これは、区長にもお聞きをした話ですけれども、ちょっとその点をお願いいたします。","respondent":"濱野助役","answer":"当然、そういう意味では、大変に優良な債権ではないという認識はございました。しかしながら、先ほど申しましたように、財産運用の大前提からすると、これをその時点ですぐにどうこうするという対象ではないと考えた次第です。","id":"exchange-083"},{"speaker":"菊地委員","kind":"質問","question":"そのことが目につかなかったということなんでしょうか。もう一度、そこを教えていただければ。","respondent":"濱野助役","answer":"その時点での価格を見ましても、９９.９幾つということでありますから、その時点でどうこうすべきものということは考えられません。その後、若干値を下げた段階で、やはりこれは基本財産として置いておくことついては問題があるという判断をして、理事長に報告をしたものです。","id":"exchange-084"},{"speaker":"菊地委員","kind":"意見","question":"徹底してこういうしたところを調査をして究明しない限りは、調査会のまとめがありますけれども、徹底してこれを究明……。〔時間切れにより、答弁なし〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-085"},{"speaker":"船波委員","kind":"質問・要望","question":"そうしたきちんとした専門家のアドバイスを受けるべきだと思いますけれども、どういう予定になっているのか、お伺いしたいと思います。そこで、補助２９号線に関しては、区長はどのようにお考えなのか、そのご見解をお伺いしたいと思います。","respondent":"中谷まちづくり事業部長、新美保健高齢事業部長、小沼福祉事業部長、指田教育次長、中尾根企画部長","answer":"平成１４年度につきましては、平成１５年度に具体的なプランを作成することを予定しておりまして、検討組織につきましては。あるいは… ２点目の暮らしの福祉インフラ整備検討経費についてのご質問にお答えいたします。したがって、民家の活用等につきましても、今… 順序は変わりますけれども、ファミリーサポートのほうからまいりますと、先般の２回の研修で、それぞれ別々に研修をしています。… 今後も、こうした考えに基づきながら就学に当たっていきたいと思ってあります。そのお子さんの一人ひとりの考え…","id":"exchange-086"},{"speaker":"船波委員","kind":"質問","question":"この景観ガイドプランをつくるときを一つの例として、ぜひ、そういったやり方を取り入れてほしいと思いますので、よろしくお願いします。高齢者や障害の当事者の方々や、小さな規模での福祉施設を運営しているようなＮＰＯなどからも十分声を聞いてほしいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-087"},{"speaker":"高星委員","kind":"質問・要望","question":"そんなこともあるものですから、ちょっとお聞きしたいと思います。西五反田三丁目１の方々、放射２号線に面した方々、ちょっとお聞かせほしいと求めました。","respondent":"岩野まちづくり事業部次長","answer":"業務経営の用途変更というような形で、現在、社内での検討を開始しているといったように聞いてあります。積極的な形で建て替えの時期とか、そういったようなものについて、個人の方々にアプローチしているような状況です。","id":"exchange-088"},{"speaker":"高星委員","kind":"質問・要望","question":"「この部分はどうするんですか、障害を持った方がいっぱい来るんじゃないですか、考え方をお聞かせほしいと求めました。場合によっては１２ｍぐらいの道路があるんですけど、ここにアクセスすべきだと、私は絶対にそう思います。","respondent":"岩野まちづくり事業部次長","answer":"東急のほうは、まだ利用計画そのものは定まっていないんですが、東急のほうで何らかの形で利用したいといったような回答を受けてあります。中央にある１２ｍの通りに直接道路をぶつけるような形というのは…","id":"exchange-089"},{"speaker":"高星委員","kind":"提案","question":"次に、教育の問題についてお伺いします。評価はしたけれども、ではどこまでおつき合いできるんですか、どこまで一緒にやってくれるんですかというようなことが明確になっていないとの意見を述べました。","respondent":"若月教育長","answer":"プラン２１の進め方ということでありますけれども、先生たちはもっとこうしなきゃいけないと、いろいろなことが言われてきました。もとより、これは単なる小手先の変更ではなく、改革であります。","id":"exchange-090"},{"speaker":"高星委員","kind":"質問・要望","question":"小中一貫校についてお伺いしたいと思います。なぜ第二日野小学校ということにこだわるのか、お聞かせいただきたい。","respondent":"指田教育次長","answer":"小中一貫校の開設場所の予定としまして、今、第二日野小学校の跡地ということで考えているわけです。できれば地域性に合わせて土地を高度利用させながら、２１世紀の教育都市品川区のシンボル的存在としての新しい学校、決めた次第です。","id":"exchange-091"},{"speaker":"高星委員","kind":"質問・要望","question":"差し支えない程度に、どのぐらい考えているのか、ちょっとお聞かせいただきたい。特に、これは総合体育館の関係があります。","respondent":"岩野まちづくり事業部次長","answer":"これまで８０年間にわたって大崎の地で工場を操業してきたということで、私どものほうへ一定の土地が譲渡されるというようなことが一つあります。区のほうにご協力いただけるかどうかといったようなことで、今、三井不動産のほうで検討中です。","id":"exchange-092"},{"speaker":"高星委員","kind":"質問・要望","question":"土地の問題ですから、今のところまだ整理しているという段階だと思います。教育委員会に要望書が出されたと聞きますが、どういうふうに思ったか、ちょっとお聞かせほしいと求めました。","respondent":"指田教育次長","answer":"そういう中において、２月９日にＰＴＡの役員に説明会を行いまして、その後、３月１９日に、今お話がございました要望書をいただいてあります。考え方、準備委員会を設けて検討してまいりますけれども…","id":"exchange-093"},{"speaker":"高星委員","kind":"提案","question":"時間がないので、ものすごく飛ばしちゃいますけれども、お願いというか、提案を一つしたいんです。地域の関係というのは、そういうことを言うんじゃないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-094"},{"speaker":"藤原委員","kind":"質問","question":"今後の第三次長期基本計画を進めていく上で、事業部制をどのように機能させ、そのメリットを発揮させようと考えているのかお伺いします。お伺いしますし、国や都に依存しない自前の政策立案の力をつけることが大切だと思いますが、いかがか尋ねました。","respondent":"中尾根企画部長","answer":"新規事業５０本の中で、ご質問がありましたけれども、環境に対しての施策をどうしていくのかというとらえ方で進めることができることになりました。したがいまして、今後につきましては、こういったよい結果を評価していく積極的なプラス思考の組織に育て上げ…","id":"exchange-095"},{"speaker":"藤原委員","kind":"質問","question":"しかし、特に都区制度改革によって新たに区が行うことになった清掃の分野では、とりわけ、区独自の政策能力が問われていると思います。この分野での、第三次長期基本計画のもとで、今後の施策のあり方、基本姿勢や考え方をお伺いしたいです。","respondent":"野本環境清掃事業部長","answer":"商店街の活性化というように、各部門を横断的にリンクをして立ち上げていかないと、なかなかこれはできないだろうと思います。住民ニーズを的確につかんでいく、こういうような訓練が、これからますます大事になるのかなと考えております。","id":"exchange-096"},{"speaker":"藤原委員","kind":"質問","question":"たしか、今、事務局の方が５人だと思いますが、区の規模からして、５人で対応しているのは大丈夫なんでしょうか。それと、たしか３月６日に監査報告が出されたと思いますが、今年の監査の特徴があったら教えていただけますか。","respondent":"南監査委員事務局長","answer":"いろいろ研修や情報収集に努めているわけですが、私以下４人職員はすべて係長級で、少数精鋭で対応していると考えています。国の会計検査院が１,２５０人、東京都１００人という態勢から比べますと小さいですが、そう目立って少ないとも考えてございません。","id":"exchange-097"},{"speaker":"藤原委員","kind":"質問・要望","question":"今年、初めてだと思うんですけれども、東京都が、行政評価の手法を使って監査をしたと伺っているんです。これについて、もしわかることがあれば、ご説明していただきたいのと、将来、品川区として導入していく予定はあるんか尋ねました。","respondent":"南監査委員事務局長","answer":"東京都が、昨年１２月、東京都の監査委員の行政監査の中の一つの試みとして、事業評価手法による監査結果というのを発表いたしました。大いに参考にしていきたいと考えていますが、事務事業評価を実施し、報告をするという流れになろうかと考えています。","id":"exchange-098"},{"speaker":"藤原委員","kind":"質問・要望","question":"続きまして、区役所の職員のあり方について、お伺いさせてほしいと求めました。過去５年間で、退職者数から採用者数を引いた人数、実際に減った職員の数は何人で、これは財源的には、どのような効果があったのか尋ねました。","respondent":"本間総務部長","answer":"２点目の、今後１０年間の職員数の変化のご質問ですが、今後１０年間で、職員の約３４％、１,１００人程度が定年退職をする予定です。５２歳から５４歳の団塊の世代が退職をいたしますと、業務委託など…","id":"exchange-099"},{"speaker":"藤原委員","kind":"質問","question":"これは、研修で、このような職員に対して対応ができるものなのでしょうか。普通の民間のサラリーマンというのは、利益追求のために働くわけですから、会社自体がそうですから、危機感というのはものすごくあると思います。","respondent":"本間総務部長","answer":"平成１４年度の研修におきましては、みずから考え、実施をしていく研修プランニング制度を重点項目として実施をしてまいります。２点目の、こういう研修を受けても効果があまり上がらない職員に対する対応ですが、ご説明をした研修プランニング制度を機能させるともに。","id":"exchange-100"},{"speaker":"藤原委員","kind":"確認","question":"次に、商店街活性化の今後についてお伺いします。その基本的スタンスを再確認する意味で、商店街の現状や、実情に関する基本知識を含めて、質問します。","respondent":"小栗区民生活事業部長","answer":"通称商店街が商店会と称すると、公式には、そういうことになってあります。法人化された商店街が３４、法人化されていない商店会が７１ございまして、区内には総計で１０５の商店街組織があります。","id":"exchange-101"},{"speaker":"藤原委員","kind":"質問","question":"そして、法人化された商店街は増える傾向にあるのか、減る傾向にあるのか、お知らせください。商店街が法人化されていないことによって、補助金を受ける資格とか、補助金の額に影響があるかについても、あわせて説明を求めました。","respondent":"小栗区民生活事業部長","answer":"中には、振興組合を解散することについてどうなんだろうかというような相談も承っているところです。法人のみじゃなくて、事業の執行内容を見て行っておりますので、交付金等の補助についての違いはございません。","id":"exchange-102"},{"speaker":"藤原委員","kind":"質問","question":"最近、商店街で合併とか、組織自体の解散という話はあるんでしょうか。あるとすれば、行政として、どのような対応をしていくのか、あわせてお伺いいたします。","respondent":"小栗区民生活事業部長","answer":"商店街が法人格を持つことによって、商店街の組織の安定化だとか、継続して事業を行うというようなことがあります。個々の事情に応じまして、適切な対応に努めてまいりいたと考えているところです。","id":"exchange-103"},{"speaker":"藤原委員","kind":"質問・要望","question":"最後に、品川区内の商店街で、店舗数によって大規模、中規模、小規模という区分けをすると、それぞれどのぐらいの割合になるんでしょうか。いつも私も質問していますが、その辺も含めて、ご答弁いただけますか。","respondent":"小栗区民生活事業部長","answer":"商店街の規模からご説明申し上げます。個性と活力を持った特色ある活動に取り組めるように、我々のほうといたしましても、支援してまいりたいと考えているところです。","id":"exchange-104"},{"speaker":"藤原委員","kind":"質問・要望","question":"私たち少数会派の要望とか、ぜひお答えください」という質問を、当時させていただきました。このときは、会派というふうに伺ったんですけれども、今回は、議員と区という観点から、最後に、区長からご答弁をほしいと求めました。","respondent":"高橋区長","answer":"平等にすべて聞いていくのが、私、区長の責務だと考えています。積極的なご意見をいただけるよう、ご要望申し上げまして、お答えにします。","id":"exchange-105"}]},{"id":"topic-02","title":"ます。 これをもって、総括質疑を終了いたします。 以上で、平成１４年度品川区各会計予算についての質疑は、すべて終了いたしました。 次に、第９号議案…","agenda":"ます。 これをもって、総括質疑を終了いたします。 以上で、平成１４年度品川区各会計予算についての質疑は、すべて終了いたしました。 次に、第９号議案…","exchanges":[{"speaker":"築舘委員","kind":"提案","question":"収入に応じての適切な受益者負担を求めており、与党会派の提案で、低所得者に対しての介護保険料減免が行われました。予算の執行に当たり、十分に留意されることを要望し、議題に供されました各会計予算に賛成いたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-106"},{"speaker":"堺委員","kind":"提案","question":"我が党の提案によって創設された地球環境リサイクル基金を環境施策の充実のため１０億円余とするほか、さらに、高く評価するものであります。提案された第１号議案の財源の根拠とはいえ、基金の目的からも、積立金の減額を保険料減額の原資に充てることは容認できませんとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-107"},{"speaker":"沢田委員","kind":"提案","question":"９年制の一貫校をつくれば、中学校になって一貫校に原則として入れないわけですから、第四日野小学校の過疎化をもたらす。我が党が本議会に提案した第９号議案、予算修正案は、区民の期待にこたえて提案したものだと自負いたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-108"},{"speaker":"本田委員","kind":"質問・要望","question":"地方自治の本旨、特に住民への奉仕という立場を研鑽していただきたいと、強く要望するものであります。平成１５年度に行われる３年目の事業見直しに向けて、利用料等を適切に検証し、制度の一層の充実を図るよう要望いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-109"},{"speaker":"本間委員","kind":"質問・要望","question":"平成１４年度品川区一般会計予算、幾つかの意見および要望を述べ、原案のとおり賛成いたします。これまで、私たちの会派から、本会議および予算特別委員会などを通じ、さまざまな角度からの要望や意見を述べてまいりました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-110"},{"speaker":"田中委員","kind":"意見","question":"法による制度開始５年後の見直し、所要の措置を講ずるべきであり、現時点での修正は行うべきではないと考えております。以上により、平成１４年度品川区一般会計予算案および各特別会計予算案に賛成し、修正案に反対することを表明し、会派最後の発言を終わりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-111"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/799186?Template=document&Id=798#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":108757,"voices":249}},{"id":"h14-20020412-7","meetingId":"h14-cm04","date":"2002年4月12日","dateIso":"2002-04-12","committee":"厚生委員会","time":"午後１時０８分～午後５時１２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を81件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"嶋委員","kind":"質問・要望","question":"５月９日開所式ということで、定員が今２０名ということなんですが、人数的にどれぐらいの方が今予定されていらっしゃるんでしょうか。一番遠いところからいらっしゃる方は、どこら辺からいらっしゃるのか、もしわかっていれば教えほしいと求めました。","respondent":"日下部障害者福祉課長","answer":"それから、来年になりますと養護学校の卒業生で通所の見込みの方が１０名以上今のところ手が挙がっておりますので、３０名に定員を拡大するです。それから、その実際一番遠い方なんですが、八潮の方が中心なんですけども、遠い方では…","id":"exchange-001"},{"speaker":"嶋委員","kind":"質問","question":"来年から通所に手を挙げている方が１０名いらっしゃると思うんですが、登録制になっていらっしゃるのか、定員になるための募集とか。それと、今２０名定員ぴったりということなんですが、年齢的なものがわかったら教えていただけますか。","respondent":"日下部障害者福祉課長","answer":"それから、年齢につきましては、これは養護学校を卒業される方は１８歳ですね。平均年齢は出ておりませんけれども、例えば高齢の方ですと５０歳代の方が２人ぐらいいらっしゃるということで、かなり年齢的にはばらつきがあります。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"障害の程度というのはどのくらいまでというふうなのがあるのかどうかということが一つと、職員体制がどういう状況になっているのかということと、そういうふうなのがどれぐらいになっているのかについて説明を求めました。","respondent":"日下部障害者福祉課長","answer":"大体２度から３度、全体で知的障害というのは４区分に分かれておりますけれども、大体２度から３度の方が中心になってまいります。国のほうの措置の基準がありますので、これに基づいて経費がそれぞれ充てられると、そのような状況です。","id":"exchange-003"},{"speaker":"鶴副委員長","kind":"質問","question":"これは何で更生施設というんですか。どうして更生施設というんですか、法律に基づいているとは言いますけども。","respondent":"日下部障害者福祉課長","answer":"つまり、いろいろ知的障害を持っていますと、日常の例えば食べることから排泄から、なかなか思うに任せないという状況があります。あるいは指導を通してできるだけ自立して日常の生活を行えるようにと、そういう意味合いで更生施設ということでの位置づけがされているところです。","id":"exchange-004"},{"speaker":"鶴副委員長","kind":"質問","question":"もうそろそろこの法律の文句を変えたらどうですかとか、そういう積極的な働きかけというのがとっても大事じゃないかというふうに思うんですね。どうしてもっといい表現が、みんなの英知を絞ったら出てこないわけがないというふうに思うんですが、所管の課長はどう思いますか。","respondent":"日下部障害者福祉課長","answer":"私も昨年４月に障害者福祉課長になりまして、施設の名称として出てまいりますので、なかなか理解するのに時間がかかりました。その辺の今のご指摘については今後私どもとしましてもしっかり受けとめて対応してまいりたい、このように考えております。","id":"exchange-005"},{"speaker":"鶴副委員長","kind":"質問","question":"生活保護となると、何となく国のお世話になるんだからということで、一歩しり込みしながらでも行かざるを得ないというような面もあるじゃないですか。あなたたちは、やっぱり一つ一つ変えていく努力というのがお互いに必要じゃないかというふうに思って、あえてお伺いをさせていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"鶴副委員長","kind":"意見","question":"どういう措置をされているのかな。現況ですね、別に一つのところに閉じ込めるわけじゃありませんからあれですが、ちょっと説明していただけませんかとの意見を述べました。","respondent":"辻田児童課長","answer":"中延は施設面でいろいろな対応をしています。４１平米の育成室でございましたけど、６４平米に拡幅して対応している、それに合わせてロッカー等の整備もしたというような形です。","id":"exchange-007"},{"speaker":"鶴副委員長","kind":"質問","question":"でも、数字だけ見ている人は、３４名のところに２０名もオーバーしていて大変なことじゃないかなんて見る人もいるじゃないですか。定員の枠の見直し、どのぐらいの施設規模かわかりませんが、この定員の考え方ですね。","respondent":"辻田児童課長","answer":"ここの部分につきまして、現員とかなり合わないという状況も出ている中で、いわゆる運用面として弾力性を持って実施しているです。そのたびに変更していかなければならないということもありますので、そういう状況です。","id":"exchange-008"},{"speaker":"鶴副委員長","kind":"質問","question":"そういうことだというふうに私は思っているわけですよ、創意工夫して、それなりの対応をしているということですから。そこあたりは心配ないわけですね。","respondent":"辻田児童課長","answer":"前児童課長もそのたびごとにお答えしておりますけど、いろんな工夫をしながら対応しているという状況なので、いわゆる困っている状況というのは現在のところないというふうに考えております。","id":"exchange-009"},{"speaker":"須藤委員","kind":"質問","question":"６時なら６時ぐらいまでですか、お預かりをするという形になっていると思うけど、途中でおけいこごとに行きたいと。そういう場合も学童としては引き受けてくれるでしょうというような話を街の人にしたんだけども、そういうところはどうなんか尋ねました。","respondent":"辻田児童課長","answer":"１点目ですが、少なくなったところにつきましては、ついていた非常勤を多くなったところに異動させるというような形での対応が当然なされております。かなり抑えた形でやらざるを得ない場合が出てくるんではないかということで、お答えになっているかどうか…","id":"exchange-010"},{"speaker":"須藤委員","kind":"質問","question":"ですから、そのおけいこのときのお話をきちんと家族の人としてあれば、この時間帯はおけいこに行っています。例えば４時なら４時、５時なら５時にまた学童に入りますということができていれば、いかがか尋ねました。","respondent":"小沼福祉事業部長","answer":"そういうものの中での対応でまず考えていくというのが基本的な線ですけれども、もし、そのお子さんがどこも行くところがないと。対応というのは、つまりお預かりするということ、これはあり得ることだと思います。","id":"exchange-011"},{"speaker":"須藤委員","kind":"質問・要望","question":"週に１回とか２回、それだったら、そういう状況もかんがみて受け入れてあげるような態勢をとっていただきたい。要望だけで終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これからの学童保育クラブの方向性について確認といいましょうか、それからこの表で見てもマイナス２１人のところもあって、プラスのところもある。これは部長でしょうかね、答弁いただければありがたいんですが、。","respondent":"小沼福祉事業部長","answer":"児童課が当然対応しなきゃ、区としてどういう形で今後整理していくのかというのは、今後大きな投資的な形で出さなくちゃいけないと考えております。教育委員会とのそごがないような形で、区としてしかるべきときにはきちっとしたものを出してまいりたいと…","id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問・要望","question":"すまいるスクールと全く同じ対象の児童なわけですね、１、２、３年生。２、むしろ答えられないかもしれないところの検討というんでしょうか、考え方がもしありましたら教えていただきたいんですが。","respondent":"辻田児童課長","answer":"現在すまいるスクールのほうの状況が出されまして、それで、今後それによりましてきちっとした形で報告が出されるというような形です。そこら辺を十分精査した形で今後の大きな課題として早急に検討していきたいというぐあいに考えております。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それに対しての職員体制がどうなっているかを一つ教えてほしいと求めました。とりあえずお願いします。","respondent":"辻田児童課長","answer":"それから指導員の定数ですけど、平成１３年度は定数１１３人に対して、１２３名です。平成１４年、１１３名のところ、１２６名という状況になっております。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１１名に対しての職員の体制ということについてちょっと教えていただきたかったので、その点についてひとつお願いしたいと思います。西中延も１４８％ということで、どこまでこの中延なんかで言えば１５９％ということになっていますけれども、聞かせてほしいと求めました。","respondent":"辻田児童課長","answer":"その中で、当然第１希望、第２希望等あるわけですけど、その辺で調整しながら、その館の能力を見ながら調整していくということは当然行われます。当然どこまでも限度なしでオーバーさせるということはございません。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"新たな学童をつくってほしいというふうな要望も地域の中では出されているんですけども、そういう状況じゃないという事態があると思うんですね。それに対して、区としてはどういうふうに考えているかということをお聞きしたいんですが。","respondent":"辻田児童課長","answer":"例えば、昨年は西中延につきましては４９名でございました。約１０名ばかり増えているわけですけど、全体のバランス等も崩してまいりますので、現在のところは考えておりません。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"すまいるスクールとは基本的に違う性質の部分がありますので、そこら辺のところの対応というのはきちんとしていただきますように、要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"船波委員","kind":"質問","question":"４年生以上の延長児を受け入れていることについて、この子どもたちは障害があることなどから、適切な保護が受けられないでいるから延長して受け入れているというようなご説明だったと思いますけれども、障害があることなどで適切な保護が受けられないでいると判断するその基準は何なんか尋ねました。","respondent":"辻田児童課長","answer":"今ちょっと私まだ十分詳しくはないんですけど、いわゆる一律的に何かをぱっと横引きで区切るというような形はしていない。実際を見て、そしてお預かりできるかどうか、そういうことを判断しながら実施しているという状況です。","id":"exchange-019"},{"speaker":"船波委員","kind":"質問","question":"例えば保護者の側ではいやいやまだこの子には延長が必要だとか、延長して預かってほしいという思いを持つケースもあると思うんですよね。ただ単に個別の状況を見て判断するという場合には、そういったことについては、どうやって対応していくんか尋ねました。","respondent":"辻田児童課長","answer":"保護者や児童と面談を実施して、そして区の中にある障害児等の育成審査会、こちらのほうで最終的に判断することになっております。そういうような中で、最終的になるべく納得いくような形でのお話をさせていただいている、そういう状況です。","id":"exchange-020"},{"speaker":"船波委員","kind":"質問","question":"再び最初の結論にはちょっと不満なので再び申請をしたような場合の判断をするときの体制というか仕組みはどうなっているんでしょうか。私の印象で言うと、同じような部署の中で行われているような気がしてしまうんですけど、その辺の体制はそれぞれどうなっているんか尋ねました。","respondent":"辻田児童課長、小沼福祉事業部長","answer":"話し合いをしながら、その後の対応をお話ししながらやっているという状況であって、その辺では同じところが審査するということは一つの方法かなと。区の中で行われているものなので、そういうようなシステムはないわけなんで… あるいは社会性とのかかわりの問題と、そういう物差しをそれぞれの職員の中で論議し、討議します。異議申し立てに対して回答を再度すると、こういう手続のやりとりで最終的に学年延長を認めるとか…","id":"exchange-021"},{"speaker":"船波委員","kind":"質問","question":"これに関して、何か第三者的な新たな視点で判断をするような仕組みにできないのかどうか、そういうことをお伺いしたいと思います。区の側が余りにも強く言うことが適切なのかどうかということに私は疑問を持つんですけれども、そういうことについてはどうお考えなんか尋ねました。","respondent":"小沼福祉事業部長","answer":"後半のほうの問題から入っていきますと、方針決定云々というのは、私どものほうで方針決定について決めると、こういうことはございません。原告の方の救済関係、親御さんのほうの救済処分というふうな手続あるいは段取りになっていると、こういうことです。","id":"exchange-022"},{"speaker":"船波委員","kind":"確認","question":"一つだけ確認ですけど、特別に看護婦さんをつけたりというような状況がない場合は、家庭の方針を尊重するということか尋ねました。","respondent":"小沼福祉事業部長","answer":"自分の家庭の方針あるいは自分の方針がこうだから、従うべきではないのかというのは、それは決定にはならないと思います。私どもとして判断していく、あるいは決めていくと、こういうことでご理解いただきたいと思います。","id":"exchange-023"},{"speaker":"船波委員","kind":"意見","question":"子どもの福祉のために判断をするということですけれども、それではこの子にとってこういう場で過ごしたほうがいいという親の判断より、区のほうで判断したものでいくということなわけですねとの意見を述べました。","respondent":"小沼福祉事業部長","answer":"学年延長するほうがよろしいのか、あるいはもう少し集団の動きの大きいところがいいのか、スローのところがいいのかと。６年生になったとき、基本的な考え方としてきてありますから、結果においてですよ。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"親もやっぱり我が子ですから、かけがえのない我が子ですから、そういうふうにしてほしいというのが親の要望だと思うんですよね。今回は希望者は何名いたところが１１名になったのか、ちょっとその数について、改めてお聞かせいただきたいんですが。","respondent":"辻田児童課長","answer":"２５名から１１名ということで、１４名の方が延長しなかったわけですけど、私どものほう十分対応しております。１件につきましては、到底対応が困難であるという最終的な苦しい判断をしながら、そしてお断りした。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回４名の方がそういうふうに区のほうに対していろいろと要望されていったというふうなことがあって対応されたということがありますけれども、そこら辺のところまできちんと対応していくというふうなところでの対応が求められていると思いますので、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"伊藤委員","kind":"質問","question":"ＩＳＯのことをお伺いいたします。ここに書いてある０歳から幼児までの基本保育から、どういうふうに内容がこれによって認定されたのかということ、その三つを説明を求めました。","respondent":"金子保育課長","answer":"更新のタイミングにおきまして、この２０００年版への切りかえということを考えていく予定です。この保育園での、保護者との重大なかかわりということで認識しておりますので、そういったことを基本マニュアルのほうには載せているところです。","id":"exchange-027"},{"speaker":"伊藤委員","kind":"質問・要望","question":"一つは、これからの展開をどうするかということをお伺いした中で、いろんな意味でＰＲになるんじゃないですか。だから、要するに国際的な機関が認定したということですから、もう少し保育園ＰＴＡのことについて教えていただければと思うんですが。","respondent":"金子保育課長","answer":"販売するという予定でおりますけれども、私どものＰＲ、あるいは情報提供としても非常に有効な手段になるのかなというふうに考えているところです。マニュアルと実際の行動というのが記録を通して確認できるように審査してきたというふうなことで今回の登録審査に通ったというふ…","id":"exchange-028"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これをどうしてもっと進めていこうとしないのかなと素直に思いますので、ちょっとしつこいようですけど、その確認答弁をいただきたいと考えています。こういうやり方もありますという具体になっていくわけですから、あわせて答弁をいただければ、再度お願いいたします。","respondent":"金子保育課長","answer":"あくまでもＩＳＯの９００１の審査登録につきましては、東五反田保育園だけでやるつもりです。ですが、これの手法というものを同じような形でほかの３６園全園が取り組んでいこうというふうに考えているところですので、その意味では。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ＩＳＯのほうが先に論議になっているのでＩＳＯのほうをお聞きしたいんですけど、冊子というのは具体的にはどういう中身になるんでしょうか。その冊子の中身についてお聞かせいただきたいのと、あと、それが父母に対してはどのように開示されていくのかについて説明を求めました。","respondent":"金子保育課長","answer":"大体全体で５００ページ程度のものがありますので、これを両面印刷にして圧縮するというふうに考えているところです。それとの関係で遜色のないような値段にはしていきたいと思いますけれども、販売するという形で情報を公開していくというふうに考えているところです。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"じゃあ、冊子はマニュアルそのものということでよろしいんか尋ねました。","respondent":"金子保育課長","answer":"失礼しました。先ほど申し上げましたとおり、基本マニュアルと、それに付属しますさまざまな手順書というものです。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そうすると、こういう写真とかなんかももちろん載っているんですよね。この写真、そういうところでは、そこいらのところは父母の皆さんは了承されているということの上でされるのかどうかについて説明を求めました。","respondent":"金子保育課長","answer":"私どもは従前から外部に対して提供する写真等につきましては、すべて保護者の了解を確実にとるようにしております。今日お配りしたところにも写真がありますが、これについても公開することでご了解がとれているものです。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"更新というのは３年ごとですか、実際にそのマニュアルどおりに運営がされているかどうかという証明をずっとしていくということになりますよね。報告書の作成とか、そこら辺のところはどういう形でやられていくのか、そういうふうなところもどう考えられているのかについて説明を求めました。","respondent":"金子保育課長","answer":"当然販売する以外にも委員の皆様にお配りする、あるいは特別区の自治体等に送る分等々もありますので、全体として1,０００部ほど印刷する予定です。私どもとしましては、当面この継続審査ということにはきちっと合格するように取り組んでいくつもりですので、当面ですけれども。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"昨年どおり１名配置ということなんですが、そうすると、これをこれと同じような形でほかの園にもＩＳＯは取得しないまでも、同じようにマニュアルづくりを今後ずっとやっていくというふうなことだと思うんですけれども、それに対しての体制というのはどう考えられているんか尋ねました。","respondent":"金子保育課長","answer":"継続していくことも初めてのことですので、これにつきまして、東五反田保育園には当面１名置くという考えで置いているわけです。ですので、全体の作業というのはもちろん全員で取り組まなければならないものですので、この分の人員配置ということは一切考えておりません。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"さらに忙しくなるという状況をつくらないようにということでお願いしたいと思うんですが、そのことを一つお聞きしたいと思います。前のときもお聞きしたんですけれども、今後どれくらい維持するにもかかっていくのかということについて、説明を求めました。","respondent":"金子保育課長","answer":"それからもう一点は、実際にかかった経費ですけれども、平成１３年度分でこの審査をお願いした費用で、２０６万2,２００円ほどかかっております。登録審査の継続分の予算につきましては、今年度で３５万円の予算を計上しています。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この予算についてなんですが、審査で２０６万幾らということなんですけれども、そのほかにはかかってはいないんでしょうか。コンサルタントとか、そういうふうなのはなかったでしたか尋ねました。","respondent":"金子保育課長","answer":"コンサルティングの委託料としましては、２１０万円を計上しておりました。ですので、合計すると４１６万円余というふうになります。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今年度の予算というのは３４万円でしたでしょうか。それだけで、これから先というのはこの費用だけで済むということでいいんか尋ねました。","respondent":"金子保育課長","answer":"継続審査につきましては、３５万円というふうに先ほど申し上げたとおりですが、それは別です。今後ずっとこれを継続していくかということですけれども、そういう意味で、当面これについては継続していくというふうに考えております。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そして、ちょっとお聞かせいただきたいんですが、締め切りのときの入園申請者数というのは、トータルでどれぐらいだったのか。４、５歳、その人数について説明を求めました。","respondent":"金子保育課長","answer":"比較のためにもう一つ数字を申し上げますと、全体では1,２１７名、区民外の方も含めて1,２１７名の申し込みがありました。これは昨年と比較しますと、昨年が1,０８２人でしたので１３５人、約１2.５％の増というふうになってあります。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"すみません。入園できた方の０歳児とか１歳児がすごく多かったと聞いたんですけど、０、１、２、３、４、５歳の人数を教えていただきたいんですが。","respondent":"金子保育課長","answer":"失礼しました。３歳が１１３人、４歳が３３人、５歳が１４人というふうになってあります。","id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"待機児が１８８名と先ほどお聞きしたんですけど、大崎、ここら辺の保育士の体制というのはどういうふうになっているのか。それからあと、全体の保育士の定数と現在の保育士の人数について説明を求めました。","respondent":"金子保育課長","answer":"３歳未満児の数が多いというふうにご指摘いただきました園ですけれども、大崎と東五反田、ご案内のとおり１０時までの夜間保育を実施している園です。園長が３７人おりますが、これを除きますと職員の定数は５３５人ということで、昨年と今年とは変更ございません。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"うち入れた方が８９８人という人数だったようにお聞きしたように思うんですが、その待機児の１８８人と２３２人、この差がちょっとよくわからないんですが。","respondent":"金子保育課長","answer":"ちょっと説明が悪うございました。転園の中で実際には転園できなかったという方が４７名おりますので、その分を引くと数字が合ってくるというふうに思います。","id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"わかりました。かなり今少子化と言われながらも、そういうことも含めて待機児解消について説明を求めました。","respondent":"金子保育課長","answer":"先ほども説明しましたとおり、１、２歳の部分で２６人の新しく定員増になっている部分があります。幼保一元化の事業として二葉幼稚園内に９月に保育園の部分もオープンする予定にしておりまして、こちらのほうは４３名ということで、五反田地区。","id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、ニュースでもかなり保育園の虐待死の問題が取り上げられていますけれども、ほんとうに親が安心できる保育園の整備にぜひ今後とも取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"須藤委員","kind":"質問・要望","question":"八潮は別として、公立のほうは逆に在籍が非常に少ないというような状況をかんがみて、これについては将来的には何か考えがあるのかどうかということ。保育園の１日のところで、こういう言葉があるのかどうか、ちょっと聞かせていただきたいと思うんですけども。","respondent":"金子保育課長","answer":"八潮についての考え方ですけれども、ご指摘のとおり八潮中央につきましては、１０時までやっているということもありまして、非常に希望が多い。私ども保育園の現場では、この辺の、ふとんに入って寝る場合については「入眠」という用語を確かに使っております。","id":"exchange-044"},{"speaker":"須藤委員","kind":"質問","question":"それからもう一つの「入眠」というほうは、ちょっとこだわるんだけど、どうなんですかね。いろんな人が見る場合には、そこの場所で使っている言葉だけでいいのかなという感じがするので、その辺はいかがか尋ねました。","respondent":"金子保育課長","answer":"先ほどちょっと説明がわかりにくかっただろうと思いますが、二葉については、第１希望で希望していらっしゃる方というのは現在のところいない。先ほどの「入眠」の言葉ですけれども、言葉の使い方については、また再検討しながら考えていきたいと考えています。","id":"exchange-045"},{"speaker":"鶴副委員長","kind":"質問","question":"保育基本のマニュアルに関して数点お伺いしたいんですが、これは要するにあくまでも基本をマニュアル化した。この点、どうか尋ねました。","respondent":"金子保育課長","answer":"委員ご指摘のとおりのところが基本であるというふうに思っております。書き記す際には、日ごろの労働の成果の質を上げるというふうに考えておりますので、私どももしっかり説明をしていきたいというふうに考えております。","id":"exchange-046"},{"speaker":"鶴副委員長","kind":"質問","question":"先ほどのご答弁による説明によりますと、この冊子は５００ページ、いわゆる裏表して２５０ページぐらいになるのかなと。相当の冊子になるわけですが、ところで、これは品川区のパソコンを開いたら、このマニュアルはパーッと見れるのか尋ねました。","respondent":"金子保育課長","answer":"現在のところ、このマニュアルそのものをインターネット等々で公開するということは考えておりませんけれども、こういったものを私どもが取得して、大まかな部分、概要については明らかにしていきたいというふうに考えております。","id":"exchange-047"},{"speaker":"鶴副委員長","kind":"質問","question":"どういうふうに基本的な考え方、基本的な戦略というのは難しい言葉ですけど、どうなっているんでしょうかね。この事業については詳細にどこまでお知らせしていこうとかという打合せというか、連携というのはどういうふうになされているんか尋ねました。","respondent":"金子保育課長","answer":"購買する方が多ければ予算の範囲内で増刷することも考えておりますが、この辺については考えていきたいというふうには思っております。著作権についてはきちっとした形にして対応していきたいと考えていますので、今のところ、その点を基本に考えて対応していきたいと考えていま…","id":"exchange-048"},{"speaker":"嶋委員","kind":"質問","question":"ほんとうにすばらしいのができて、安心してほんとうに品川に住み続けていただけるという大前進だと思って大変うれしく思っております。どのように利用される方にお知らせとか、ご相談に乗る体制を今整えられていらっしゃるのか、お聞きをしたいと思います。","respondent":"中川原福祉事業部副参事","answer":"広報等はちょっと考えてございませんが、ただし、５月中旬にはプレス発表はする予定です。在宅介護支援センターとか、民生委員の方とか、日々そういった情報を集めてこちらにつないでくださる方には丁寧に説明してまいりたいと考えています。","id":"exchange-049"},{"speaker":"嶋委員","kind":"質問","question":"５月中旬プレス発表ということなので、そういう方たち、変えていく方向になっていくと思うんですね。いろんな事故絡みになっていく部分もあるかと思いますが、そこら辺はちょっとどのようにお考えか、お聞きをしたいと思います。","respondent":"中川原福祉事業部副参事","answer":"在宅介護支援センター、また、そこで私どもがケース会議を今度事務局として主催しましてどうするかということを考えます。すぐにはちょっとできない状況ですので、そのケースの状況を分析しつつ、そういったチームで今後のことを考えていきたいというふうに考えております。","id":"exchange-050"},{"speaker":"嶋委員","kind":"質問","question":"ちょっと私も前にお聞きしたことがあるんですが、施設に入っている方でも、こういう形をとっている方が何人かいらっしゃるとお聞きしたんですが、ちょっと施設のほうのことでお聞きをしたいと思います。","respondent":"中川原福祉事業部副参事","answer":"調査をいたしまして、今特養で困っていらっしゃる、ここに該当しそうなケースについては情報を集めております。順次計画的にその方たちに制度をご活用いただくような形で今年度は進めていく予定です。","id":"exchange-051"},{"speaker":"伊藤委員","kind":"質問・要望","question":"いわゆる利用料はどこにかかってくるのかということを素直にお聞かせいただきたいのと、どういう基準で、その部分のご説明をお願いいたします。","respondent":"中川原福祉事業部副参事","answer":"定期訪問のところは、大体そういった１回何時間ほどかかるという標準的なものを想定しまして設定しておりますので、それを標準に考えしています。そのほか、やはり実費ということになってまいりますので、そこら辺を基準としまして考えていくです。","id":"exchange-052"},{"speaker":"伊藤委員","kind":"質問","question":"単純に生活支援の方の１時間1,０００円のことで済む場合もあれば、場合によってはそういう弁護士、司法書士、専門的なところも来るでしょうから。その間の例えばかかる費用の算定というのはどういうふうにしていくんでしょうかね。","respondent":"中川原福祉事業部副参事","answer":"それが１年ですと１２カ月分になりますので、そういったお見積もりといいますか、支援プランにはそういった料金も含みまして計算をします。本人に意思能力がありませんので、それをご本人からいただけるというような、そういった仕組みになっております。","id":"exchange-053"},{"speaker":"伊藤委員","kind":"質問","question":"そうすると、例えばどう質問したらいいんでしょうか。利用料を先に払って、それで、手前に亡くなった場合の精算をして、そのお金はどうなっていくんでしょうかということ。","respondent":"中川原福祉事業部副参事","answer":"この料金の支払いですが、月払いになりまして、翌月に前月の分をいただくような形で運営をしてまいります。逆にこういった方たちの参加が必要な方というのは、そういった層になりますので、後ほど回収ができるのではないかというふうに考えております。","id":"exchange-054"},{"speaker":"伊藤委員","kind":"質問・要望","question":"先ほども質問しましたように、多分いろんなケースがあって、いろんな個々の事情が相当入ってくる話だと思うんですね。でも、始めていくわけですから、権利がそれぞれ守られる仕組みづくりをぜひつくっていただきたいというふうに要望しておきますので。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"鶴副委員長","kind":"質問","question":"ちょっと教えてほしいんですが、この財産保全を基本内容とするという、要するに幅広い支援の内容として、定期訪問とともに財産保全を基本内容とする。この財産保全という意味は、どういう範疇を言うのか尋ねました。","respondent":"中川原福祉事業部副参事","answer":"財産保全サービスにつきましては、通帳を何十冊も持っていらっしゃって、わからなくなっちゃうという方が結構多いんですね。そういったお入り用なときは、こちらから持って伺うという、そういったものがこの財産保全サービスというような内容です。","id":"exchange-056"},{"speaker":"鶴副委員長","kind":"質問","question":"それで、その点は後でちょっとお伺いしますが、この支払い猶予だとか立替払い制度をつくると。スタートに当たって。","respondent":"中川原福祉事業部副参事","answer":"これは取り崩し型で充当してまいりますので、また積み増しといいますか、またいただく額を増やしていくこともあろうかと思います。とりあえずは1,０００万円からスタートです。","id":"exchange-057"},{"speaker":"鶴副委員長","kind":"質問","question":"あるいは公表してはならないみたいなペナルティー、それを犯した場合はペナルティーとかあるじゃないですか。このここで言うところの後見人制度に係わる人たちの身分というか、これはどういうことになるわけか尋ねました。","respondent":"中川原福祉事業部副参事","answer":"それについてはここにありますように、そこには守秘義務を課して、そこら辺については十分配慮してまいりたいと思っています。それは品川区のほうと連携してできることを分担するということで、そこら辺も配慮しながら進めていきたいというふうに考えております。","id":"exchange-058"},{"speaker":"鶴副委員長","kind":"質問","question":"はっきりした、どういう関係の条例とか法律が適用されるのかわかりませんけれども、現行の法律で対処できるようになっているのか否か。こういう場合は、こういう法律が適用されてペナルティーを受けることになりますとか、そういうところはどうなっているんか尋ねました。","respondent":"中川原福祉事業部副参事","answer":"福祉サービス利用援助事業で契約を結びますと、契約内容の中にそういったことを盛り込んで規制をしていくということになります。もう一点、適正な運用がなされているかということもチェックをしていただくという、そういった仕組みも設けて運営していく予定です。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今年の５月末から施設のほうでスタートさせていくということですけれども、そしてまた、最終的には在宅も含めてどれぐらいの見込みを考えているのか。どういう資格、どういう方がされて、その体制についてちょっと説明を求めました。","respondent":"中川原福祉事業部副参事","answer":"このスタッフの体制ですが、まず、社会福祉協議会のコーディネーターは現在５人を予定しております。生活支援員ですが、これは民生委員のＯＢとか、高齢者クラブの方とか、また、そういった方たちを予定しております。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これはだれがどういう形で判断するのかということと、ここのところで区長申し立て経費に７５万円というふうになっているんですが、この区長申し立てのところでどういうふうに費用がかかってくるのかについて教えてほしいと求めました。","respondent":"中川原福祉事業部副参事","answer":"こういったケースが出てまいりますと、どういった状況にあられるのかというのを検討しまして、区長申し立ての手続が進むことになります。そういった手続にのっとって運営するための、一たん回収を見込むんですが、一時的に立てかえる費用として予算化がされております。","id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"じゃあ本人のほうから戻ってくるということなんですけど、その費用は大体どのぐらいかかるのか、説明を求めました。","respondent":"中川原福祉事業部副参事","answer":"精神科医の方にお願いして鑑定をしていただく費用が大体１０万円程度、協力していただくお医者様にお願いしています。それにつきましては、収入印紙とか郵便切手等々がございまして、１万円程度のそういった経費がかかります。","id":"exchange-062"},{"speaker":"嶋委員","kind":"質問","question":"今現在でも、５５歳から６４歳までの方の大変就職先がないということで、私どもにも大変相談が多いところです。ハローワークに行かなくても、ここでそれだけの情報が得られていくのか、ちょっとまずお聞きをしたいと思います。","respondent":"蓼沼高齢事業課長","answer":"ただいまのご質問の件ですけれども、おっしゃいますとおり、ハローワークに行かなくても、ここの新しい新・シルバー人材センターにおいて相談窓口において情報が得られるという形になります。","id":"exchange-063"},{"speaker":"嶋委員","kind":"質問","question":"品川じゃなくて城南地域ですか、先日私も相談を受けた方に識字力のない方の相談があって、大変苦労いたしました。紹介というのも、どのようにこれからされていらっしゃるのか、それもちょっとお聞きをしたいと思います。","respondent":"蓼沼高齢事業課長","answer":"この人材を中心に開拓を進めてまいりますけれども、一つにはやはりＰＲを進めていく、そのような形で求人情報について開拓をしていく予定です。カウンセリングを綿密に行いまして、それから意識の開拓等も進めてまいる予定ですけれども…","id":"exchange-064"},{"speaker":"嶋委員","kind":"質問・要望","question":"住所とか電話番号とか、あっ、住所も細かくあまりなかったんですね。もしできるようでしたら、そこら辺まで要望したいと思うんですが、ちょっと意見をお聞きしたいと思います。","respondent":"蓼沼高齢事業課長","answer":"求人側の情報につきましては、やはり求人票をもとにシステムとしてデータベースの中に落とし込んでいきますけれども、そのときに、そうしたような交通アクセスの関係等についてきめ細かな情報がなるべく入れられるように努力してまいりたいと思います。","id":"exchange-065"},{"speaker":"嶋委員","kind":"質問","question":"事実かどうかちょっとわからなかったんですが、そこら辺の情報が今までシルバー人材センターのほうにはあったのかどうかと、ちょっとお聞きをしたいと思います。","respondent":"蓼沼高齢事業課長","answer":"こちらのほうもそういった形で事業を進めてまいるつもりでおりますので、適切公正な仕事の配分等については、やはり強力に進めてまいりたいと思います。","id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"事業所3,５００というふうにここに書いていますけども、カウンセラーということで書かれているんですが、この体制が具体的にどうなっているのかについて説明を求めました。","respondent":"蓼沼高齢事業課長","answer":"基本的には体制といたしましては、開拓員という人材を配置いたしまして、全体としてはシルバー人材センター４名の職員体制で運営をしてまいります。配布ですとか、広報ですとか、そういった形で求人求職が適切に要望に合うようなものがそろうような形で進めてまいりたいと思いま…","id":"exchange-067"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ仕事確保のところでご努力いただきたいというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"伊藤委員","kind":"質問・要望","question":"簡単に二つお伺いいたします。要は求人開拓の方がどれだけの仕事を見つけてくるかにかかっているわけですから、それから、これも具体的に考えていきますと。","respondent":"蓼沼高齢事業課長、新美保健高齢事業部長","answer":"これはシルバー人材センターではなくて、すみません、これはシルバー人材センターの会員の方の紹介を受けまして雇用するものです。あるいは職業紹介をやっているという、具体的にそれぞれ個人個人に必要な能力について検討し… 若干補足的にご説明をしますが、その方のお二人体制でこれから９月に向け、やっていこうということです。マナー講習までは必須でやる予定ですが…","id":"exchange-069"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ほかの委員も言っておりましたけど、ここのポイントはまさに企業側、要するに求人開拓をどうしていくかにかかっていると思います。でも、お二人で足りるのかなという気もするし、そこの強化を十分に費用対効果の面も考えながら進めていっていただきますように要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"},{"speaker":"須藤委員","kind":"質問","question":"どうしてもそういう傾向があるんだというようなお話もちらっと聞いたことがあるんだけども、そしてまた、その辺はいかがなものなんでしょうか。今言ったように５回来たのが３回になっちゃう、２回になっちゃうというような話をちらっと聞いたんだけど、その辺はいかがか尋ねました。","respondent":"蓼沼高齢事業課長、林（和）委員長","answer":"今手元に事業費とその仕事の件数のデータが出てまいりませんけれども、また、今回の事業もそういった形で位置づけをして進めてまいりたいと思います。 ほかにございませんか。ないようですので、６番目の「高齢者就業総合相談窓口」のプレオープンについての報告を終わります。 私どものほうでこの中身について検討を進めてまいりました結果、今回、４月１０日から本格実施のスタートという運びとなりました。雑駁ですけれども…","id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ケアマネジメントコースのほうで、品川区内のケアマネージャーとして区内に働いている方というのは何人ぐらいいるのか一つ教えていただきたいのと。こういう中身も入れてほしいとかというのがケアマネージャーの方は、そういう要望というのは聞いていただけるような場面というのはあるのかどうか。","respondent":"諸岡保健高齢事業部副参事","answer":"それから、春学期、秋学期ですが、先ほどは申し遅れましたが、それぞれ修了証ということで、学期ごとに修了証を発行する予定です。さらにコース終了時にも修了証を発行する予定でありまして、半期だけでも一定の成果を得られるようなカリキュラム編成をしております。","id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ケア協議会で２０名で１００名ということだったんですが、この１００名の方だけが対象ということではないんですよね。働いているケアマネージャーの方が何人ぐらいいるのかというのがわかったら教えていただきたいのと、それと。","respondent":"早津高齢福祉課長、諸岡保健高齢事業部副参事","answer":"支援センター等に限ったわけではございません。人数についてはちょっと私どもでは把握できておりません。 実際に各コースで指導に当たっていただく先生方と私どもとで話し合いまして、それから対象者へのアンケート等に基づく受講生の要望等も踏まえまして、カリキュラムの検討を行いまして決定をしているものです。","id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう中身でやっているというふうなことをお聞きしたんですが、そこに出られた方の要望も聞きながら中身を決めているようなんですが。１０回なので、１回当たりにすると2,０００円ぐらいになると思うんですが、いかがか尋ねました。","respondent":"諸岡保健高齢事業部副参事","answer":"今年度、立ち上げで、初年度ですので、経費的な面で概算でしか出ない部分もあります。１年間を通してやってみまして、その成果を踏まえまして受講料設定につきましては、また来期等に検討してまいりたいというふうに思ってあります。","id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ区の補助とかも含めてご検討ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"},{"speaker":"須藤委員","kind":"意見","question":"この費用で１回2,０００円といったら、むしろこれだけ研修するから、そういうような連携をつくることは考えなかったのかどうか。年間どの程度の区の補助というか、そういうものが必要になっているのかどうか、その点をお聞かせ願いたいと思いますとの意見を述べました。","respondent":"諸岡保健高齢事業部副参事","answer":"残りが受講料で賄うというようなほぼ1,０００万円規模でこの事業につきましては予定をしています。それぞれの法人のお考え、事業所あるいは法人で持ちますというようなことで、ほとんどが個人負担というのはないというのが状況です。","id":"exchange-076"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"すみません。今６００万円の補助金の中で、全部が区の持ち出しではないということなんですが、ここのちょっと内訳がわかったら教えていただきたいんですが。","respondent":"早津高齢福祉課長","answer":"確定しているわけではございませんが、国が２分の１、都が４分の１という補助です。","id":"exchange-077"},{"speaker":"鶴副委員長","kind":"質問","question":"それはそれとして、ところで、この品川福祉カレッジの位置づけというのは、要するに介護福祉専門学校の付属校ですか、それとも併設校なんですか。品川介護福祉カレッジ、単独校なのか、あるいは介護福祉専門学校の付属の学校なのか。","respondent":"諸岡保健高齢事業部副参事","answer":"大変難しいところですが、基本的には品川福祉カレッジは単独で学長もやっていただいておりますので、付属とかそういう関係ではなく、単独です。ただ、品川介護福祉専門学校と連携を図り、機能やネットワークの設備を利用する協力関係にあるということで理解をしております。","id":"exchange-078"},{"speaker":"鶴副委員長","kind":"意見","question":"そうすると、品川福祉カレッジというのは、各種学校なのか、ただ単なるカレッジ、カレッジというしかないんですけども、どういう位置づけなのかな。だから、どういうふうにして分類しておけばいいのかなというふうに思うんですがとの意見を述べました。","respondent":"諸岡保健高齢事業部副参事","answer":"法的に基づく学校とは全く異なりまして、研修を１年間通して体系的に行っていくというような意味で、一つの愛称的にカレッジと呼んでいるものです。したがいまして、シルバー大学とかというようなこともありますが…","id":"exchange-079"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"来年度から郵送方式ということでご報告いただいたんですけど、これは郵送というのはどういう形でというか、希望者だけというふうになるのか、とりあえず全員に郵送ということになるのか、来年度ということなので、これからいろいろ検討するのかもわからないんですがとの意見を述べました。","respondent":"日下部障害者福祉課長","answer":"その辺につきましては、具体的にこれから検討を進めてまいります。ほかの状況を見ましても、いろいろな形を取り入れてやっておりますので、品川区として一番いい方法はどれかということで検討を進めてまいります。","id":"exchange-080"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このことについてはかなり要望も出されていて、私も質問させていただいたんですが、ぜひ期待しているところですので、よろしくお願いいたします。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-081"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/534819?Template=document&Id=3014#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":70385,"voices":217}},{"id":"h14-20020415-6","meetingId":"h14-cm04","date":"2002年4月15日","dateIso":"2002-04-15","committee":"区民委員会","time":"午後１時１６分～午後４時１３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"原委員","kind":"質問","question":"１回各会派に持ち帰らせていただいて、その中で議論をしたらどうだろうかと思うんですが、いかがでしょう。ですから、そういう意味も含めて、どうだろうかなと思うんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"本田委員","kind":"質問","question":"料金については安いほうがいいわけですから。一度自分が今言ったような形をちょっと出してもらって、議論をしやすくしたほうがいいんではないかなと思うんですが、進め方としてどうか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"菊地委員","kind":"意見","question":"委託の問題にしても、ある程度の線、ある程度の考え方として示していただくほうが論議としてはしやすいのかなというふうに思いますけれども。意見だけですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"堺委員","kind":"質問","question":"私も今、本田、原委員も初めにもおっしゃっていたように、そういう取り扱いでいいんじゃないですかね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"金高委員","kind":"質問","question":"やはりこれだけのボリュームですから、我々も会派に戻っていろいろちょっと整理しながら意見を集約していきたいと思います。これだけの資料ですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"石田副委員長","kind":"質問・要望","question":"今４月２６日に入札で着工していくという形で、そこら辺の流れというのかな、それをもう一度ちょっと整理して教えていただきたいんですね。早いほうから順番に。","respondent":"宮地区民課長","answer":"それから今度は炉の試運転とか中の準備がありますので、最初お話ししたとおり、平成１６年４月が一番、今のところ予定としてはオープンにしています。４月が３月へ、今度は平成１５年度中のオープンになりますので…","id":"exchange-006"},{"speaker":"石田副委員長","kind":"確認","question":"ちょっと確認だけだけれども、５月８日ごろまでに、決まっているようなことが幾つかもうある程度方向性がありますよね。それというのはある程度資料というのは出てくると考えていいということなんか尋ねました。","respondent":"宮地区民課長","answer":"私どものほうでちょっとワーキングの中でやった、そのくらいの資料でよろしければ、また議論の参考にもなろうかと思いますので、この委員会終了後、お出しします。","id":"exchange-007"},{"speaker":"原委員","kind":"確認","question":"そうすると、今のお話ですけれども、この次の委員会ではなくて、今のお話だと時間的にこの委員会の後に、すぐ出せるということですか。それを基本にして、我々はまた会派で議論ができるということなのかどうか、そこだけ確認したい。","respondent":"宮地区民課長","answer":"今の段階で整理はそんなにされていないんですけれども、こういう考え方もあるというふうな段階のもので、もし参考になるようでしたら、お出しすることはできます。","id":"exchange-008"},{"speaker":"金高委員","kind":"意見","question":"今のお話ですと、８日までという話ですけれども、できたら一定の日づけまでに切ってもらったほうが、この資料と一緒に持ち帰って会派と話ができますので、今の委員長のお話ですと８日までということでとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"石田副委員長","kind":"質問","question":"例えば今そこからもお話があったように、そういう、何か前回の区民委員会ではみしま聖苑か何かを見に行っているそうなんですね。これは委員会に諮って皆さんにお聞きをしたほうがいいんじゃないのかというような話が出たということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"原委員","kind":"意見","question":"５月８日にはまずできないと思うし。そこのところだけだと思うんですがとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"菊地委員","kind":"意見","question":"ここに示してくださったものだけが全部じゃないと思うんですけれども、きっと。近いところで、そうしたところもちょっと考慮に入れて考えれればなというふうに思いますけれどもとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"原委員","kind":"質問","question":"とにかく皆さんから意見を伺わせていただいて、日程的にとれればということで。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"本田委員","kind":"質問","question":"８日にまとめるということですから、絶対行かないよとか、そういうのではありませんので。その前に日程が組めるかどうかでしょうね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"本田委員","kind":"意見","question":"所管外になってしまうんですけれども、この立坑の役割と、なぜここに場所を選んだのか。もしわかればとの意見を述べました。","respondent":"宮地区民課長","answer":"立坑の役割ですが、その水質改善を進めるための工事ですが、シールド工法でずっとトンネルをちょうど原っぱ公園のほうまで掘っていくことになります。従来今ある立会川には雨水、きれいな水しか流さないようにするということで…","id":"exchange-015"},{"speaker":"本田委員","kind":"質問・要望","question":"今の問題が解決するというふうに本当に付近住民の念願していることですから、早くこれはつくってほしいという要望が一方ではあるわけですね。立坑というのは１カ所だけになるんか尋ねました。","respondent":"金井環境課長","answer":"ポンプ場を下流のほうに確かつくる予定になっておりますので、海辺のほうにですね。交通量がかなりあるわ、こんな現状になっていたということで、多分そういうことだというふうに記憶しております。","id":"exchange-016"},{"speaker":"本田委員","kind":"質問・要望","question":"ですから、その辺の対策を十分に立てていただきたい。そういうことで近隣住民への説明をきちっとやって、万全な対策を講じていただきたいということを要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"原委員","kind":"質問・要望","question":"ちょっと２点ばかり確認をさせていただきたいんですけれども、それは半月に限定されているものなのかどうかちょっとお聞きしたいんですが。どうなんか尋ねました。","respondent":"宮地区民課長","answer":"それから、葬儀社の対応ですけれども、品川支部のほうの方には近々委員会の報告が終わりましてからということでご連絡をする予定です。それから、館のほうにもポスター、それから広報にも載せる予定で考えております。","id":"exchange-018"},{"speaker":"原委員","kind":"意見","question":"そうすると、この閉館中の葬儀については、おのおのの町会でやってもらえるのか、あるいはどこか応援を立てないとという話になると思うんですが、その辺はどうしますかとの意見を述べました。","respondent":"宮地区民課長","answer":"これから町会、地域センターを通じていろいろとお話しする機会があろうかと思いますので、日にちが確定次第、何らかの形で区民の皆様にもお知らせできるように考えていきたいと思います。","id":"exchange-019"},{"speaker":"原委員","kind":"確認","question":"そのスタート時点はそのまま固定で、ずっと例えば７年なら７年、５年なら５年を加味していくわけですよね。そうすると、その間に下がったり上がったりするものについては一切影響なくやっていけるということなのか、ちょっと確認を。","respondent":"市川産業振興課長","answer":"急に一気に０.５％も上がるとかまずございませんので、そんなような状況ですので、財政的にも大体当初予算の見込みの中で処置、対応してきている。ただ、ご案内のとおり、年度当初で年末の緊急資金などを実施いたしますと多少不足が出てくる場合もございまして。","id":"exchange-020"},{"speaker":"原委員","kind":"質問・要望","question":"各企業にすると、非常に今の経済状況が厳しい中で、できるだけ低いところで抑えてほしいなと。区の利子補給もそういう中で一応行われているわけですから、それをうまくかみ合わせて、その中で対応していただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"菊地委員","kind":"意見","question":"１点だけ。今回全体的に０.３％、結局は区がこの０.３％について区で利子補給をしていくかどうかということに集中しちゃうのかもしれませんけれどもとの意見を述べました。","respondent":"市川産業振興課長","answer":"この経過の中で私ども検討したことが二、一つは、今までどちらかというと下げ基調でずっとこの５年ぐらい来てあります。その分を利子補給という考え方をとらせていただければ、本来の利子補給の半分、これが実質とれたんじゃないかというような一応検討の経過があります。","id":"exchange-022"},{"speaker":"本田委員","kind":"質問・要望","question":"昭和６２年というとバブルの最盛期に７億円で買って、区有地をこういう形で開発に使う、あれは所管はどこになっていくんですか。この事業そのものは今の状況に合った形で積極的に進めていっていただきたいと思うんですけれども、この財産変換についてはどこでやるんか尋ねました。","respondent":"市川産業振興課長","answer":"再開発というか、出資によって事業者の共同出資ということで進める事業ということで、いわば等価交換というような方式になるものです。したがいまして、今委員の言われた財産処分ということで、総務委員会に諮るということは現在のところ考えてございません。","id":"exchange-023"},{"speaker":"本田委員","kind":"質問","question":"この辺はどこでその辺の評価判断はするんですか。所管だけでやっているわけか尋ねました。","respondent":"市川産業振興課長","answer":"区としていかに有効な床面積をいわばこの事業の中でとれるかということで、昨年来管財部門とそれから都市計画課が窓口になって開発事業者のほうと協議を進めてきてあります。","id":"exchange-024"},{"speaker":"本田委員","kind":"質問・要望","question":"要望だけ言っておきますけれども、今回この事業を興していくということですから、することによって。この事業がそういう意味で、その辺のところは十分気をつけてと言ったら変ですけれども、配慮して進めていただきたいというふうに要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"原委員","kind":"質問","question":"この独立支援事業なんですけれども、これは第２の創業ということですよね。あるいはこの会社のこの分社化は適切なのかどうなのかという情報がいろいろ出てくると思うんだけれども、その辺はどう整理をされていくわけか尋ねました。","respondent":"市川産業振興課長","answer":"この事業のプランニングをしたときの一つの想定したこととして、東京商工会議所との提携事業として実施をしたいという思いがあります。その辺は今後検討させていただきたいと思いますが、優良な入居テナントの選考ということで最善を尽くすような方法を検討していきたいと思いま…","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問・要望","question":"これを教えていただきたいのが１点と、原委員からも出たんですけれども、実際にこのビルができました。もう１点は、いい会社をより一層伸ばしていこうとする事業なのか、この３点について説明を求めました。","respondent":"市川産業振興課長","answer":"それと、やはり新しいマーケットに敏感に対応している企業であること、これもやはり大きな選択肢になります。新しい品川の産業を象徴するような企業にも入っていただきたい、そういうようなこの事業の目的があります。","id":"exchange-027"},{"speaker":"金高委員","kind":"質問・要望","question":"課長の説明で、新しいタイプの製造業の進出ということが最後にありましたけれども、具体的にどういう。ＩＴなんかもそうですけれども、その辺をもうちょっと具体的に新しいタイプの製造業というのを教えてほしいと求めました。","respondent":"市川産業振興課長","answer":"例えばこのすぐそばにある大井町にある会社ですが、セラミックの人工の人間の歯、これをつくっている会社の事務所があります。部品の説明をされたとき、製品の説明をされたときにすぐ理解できるような、こういった状況だと考えています。","id":"exchange-028"},{"speaker":"石田副委員長","kind":"確認","question":"ちょっと確認だけしたいんですけれども、今等価交換方式でやっていかれるということで、１０月ごろ着工されていくという話がありました。建築費が約３０億かかって、またあとはビルの管理から含めてすべて森ビルで業者選定から行っていくという理解でいいのかという確認をまず。","respondent":"市川産業振興課長","answer":"今後のこの事業の効果的な進め方というか、効率などを考えた場合に、森ビルサイドで持っているノウハウを活用してこの事業を進めていくということで動いてきてあります。","id":"exchange-029"},{"speaker":"石田副委員長","kind":"確認","question":"もう１点だけ確認しますが、基本的に使えるところは５４０平米なわけですけれども、それを区民の今こういった創業支援という形でお貸しをしていく。それについての話し合いもある程度今詰めているけれども、その中から使用料とかそういうものを決定していくという考え方でいいのかどうか。","respondent":"市川産業振興課長","answer":"特に今ご指摘のあったランニングコスト、新しい建物の場合、そこが結構重たくなります。本体の家賃部分なのか、その辺は今後の大きな検討課題の一つだということで、私どもは認識しております。","id":"exchange-030"},{"speaker":"石田副委員長","kind":"質問・要望","question":"どうしてもそっちのサイドの話になりやすいんだろうなと、それにそぐわないところはやめてほしいというのは必ず出てくる話があると思うんですよね。それこそ建築が１０月から始まるんであれば、ある程度そこら辺までは決着をつけておかないと、そこら辺のところはどうお考えなのか。","respondent":"市川産業振興課長","answer":"もう１点のテナントの、ただ、西大井のベンチャー創業支援に比較いたしますと。ただ、これも入居者あっての使用料の設定というか、賃料の設定ですので、この辺は実情の把握に努めてまいりたいと思います。","id":"exchange-031"},{"speaker":"本田委員","kind":"質問","question":"そういう省エネモニタリングシステムみたいなものを、この役所が取り付けて、すぐ見れば今どういう状況かわかるというようなことはどうなんですか。そういうシステムの開発が今進んでいるということですので、何かそういうようなこともやってみたらどうかなと思うんですけれども、どうか尋ねました。","respondent":"宍戸ＩＳＯ担当課長","answer":"自分たちの取り組みがどういうふうに数値的にあらわれているかというのを、コピーの使用量、自動車の使用量等についてはやっているところです。今年度環境基本計画、行動計画を策定するということになってありますので…","id":"exchange-032"},{"speaker":"本田委員","kind":"質問","question":"検討するということですから、そういう視覚に訴えるやり方、かといって全職員がいつもそこに目が行っているというふうな形。それをつけるのにまた金がかかるというようなことがあるのかもしれませんけれども、検討してみたらどうかなというふうに思うんですがね。","respondent":"金井環境課長","answer":"各家庭でＣＯ2の排出が、あなたの家庭の中でどのくらい排出していますよというものをつけようというような、国のそういう計画もあるようです。そういう意味では、私どもそういうものがあれば、十分参考にさせていただきたいというふうに思います。","id":"exchange-033"},{"speaker":"本田委員","kind":"質問・要望","question":"ぜひお願いしたいと思います。ほかのメーカーもいろいろと研究しているというふうに聞いておりますので、そういうこともぜひ取り入れたらいかがかと要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"原委員","kind":"質問","question":"第１段階は３％、あるいは第２段階は６％とかということで、環境マネジメント。第１段階で目標とするもの、第２段階で取り組みとするものという形で分けてあるんだけれども、これだけになりますよという形になるんか尋ねました。","respondent":"宍戸ＩＳＯ担当課長","answer":"それから都市ガスの削減の寄与率が３割というのが、区役所と普通の庁舎の実態から言うとそういうふうな計算になるです。両方とも温室効果ガスの削減目標が３％、６％というふうになっていますけれども、電気とガスがほとんどであるというふうなことが実情です。","id":"exchange-035"},{"speaker":"原委員","kind":"質問","question":"６％以上削減されるんだというもとでこれを出されてきているわけなんでしょうか。そこのところの関連と言ったらいいのかな、うまい表現がないですけれども。","respondent":"宍戸ＩＳＯ担当課長","answer":"この３％もそうなんですけれども、６％という数値につきましては、ただ国が６％という数字を掲げているので６％にしたというわけではございません。平成１８年度に向けて、どのぐらい削減できるだろうかというのをある程度計算して積み上げた数値です。","id":"exchange-036"},{"speaker":"原委員","kind":"質問","question":"それは積み上げてから６％以上になるよというような話なんですか。それともこれは最低限やるべきことで、もっともっといろいろなことがあるのよということになるのか尋ねました。","respondent":"宍戸ＩＳＯ担当課長","answer":"そういう意味では、かなり控え目な数字というか、かなりこれならできるんじゃないかというふうな形で６％という数値を出しているです。背伸びしないと６％にならないよという数値ではなくて、６％というのはある程度クリアできるんじゃないかという積み上げを本当にした数値です。","id":"exchange-037"},{"speaker":"原委員","kind":"意見","question":"その取り組みと、その積み上げが６％だというような説明はわかったんですけれども、その取り組みはもっといろいろな方法がありますよね。その取り組みがいろいろもっとほかの対応、要するにほかの方法もあるのかなという部分を含めてお話を聞いているだけなんですがとの意見を述べました。","respondent":"金井環境課長","answer":"それで、こちらの５ページ、６ページに今、原委員がおっしゃったように、いろいろ取り組み方があります。こういったものを続けていくと、この６％以上のものが計画実現可能であるという状況にあるということでご理解をいただきたいと思います。","id":"exchange-038"},{"speaker":"石田副委員長","kind":"質問","question":"平成１５年度で６％以上削減できたというときは、この計画を平成１２年度でこれを９％にするのか１０％にするのか、１２年度比で。そこら辺の計画の変更というか、これは５年のスパンだけれども、その計画変更というのは随時行っていくという考えでいいわけか尋ねました。","respondent":"宍戸ＩＳＯ担当課長","answer":"それが継続的改善という部分です。計画を立てて、ＩＳＯの仕組みの中で回していくというふうなことを考えると、上方修正も大いにあり得るというふうな内容です。","id":"exchange-039"},{"speaker":"石田副委員長","kind":"質問","question":"たまたま同じになったのかどうかわかりませんけれども、６％というのが、新聞とか雑誌とかにも載っています。もっとこういうふうに、もっとぽんと自治体としてやるというお考えとか計画とかいうのがあるのかどうかというところをお聞きしたいんです。","respondent":"宍戸ＩＳＯ担当課長","answer":"やりながらそういうふうな方策が見えてきた場合には、そもそものＩＳＯの数値を定めるときにそういうふうな話で３％にしたといういきさつがあります。ある程度かたい線ということで６％にしたわけですけれども、いろいろな考え方、今後検討を加えていきたいと思います。","id":"exchange-040"},{"speaker":"原委員","kind":"質問","question":"その辺をちょっと。それからもう一つ、保養所は行政のほうに報告義務はどの辺まであるんか尋ねました。","respondent":"宮地区民課長","answer":"本日の文教委員会で、やはりヴィムからミートランドという株式会社に、宇都宮の会社だそうですけれども変更になっております。選定方法も含めて見直すことという指示も出ていますので、今回その他ですけれども、ご報告させていただいたものです。","id":"exchange-041"},{"speaker":"原委員","kind":"質問","question":"朝６時半にすごい音で起こされまして、対処は非常によかったです。ある意味では人命にかかわる問題が出てくる可能性も出てくるわけで、そこのところの対応なんですが、どうなんか尋ねました。","respondent":"宮地区民課長","answer":"煙感知器で、すぐ消防自動車が１台駆けつけたということなんですが、対応としてはよかったというふうに私も思っております。あまりこんなことがあってはいけないんですけれども、きちっとその対応を含めまして、ちょっと検討させていただきたいと思います。","id":"exchange-042"},{"speaker":"菊地委員","kind":"質問","question":"ちょっと一つだけお聞きしたいんですが、先日ちょっと品川健康センター、あそこもちょっと管理業者が変わりましたよね。例えば新しい業者にそういう方々を雇ってもらうような話をしたりというのは実際にできるのかどうか、ちょっとそこら辺をお聞きしたいんです。","respondent":"宮地区民課長","answer":"新しい業者にその条件をつけるようなことはできませんが、あくまでも会社同士の問題ですので、結果はよかったですが。支配人の方は、そこでの支配人ではなくて、会社としてどこかで使わせていただくということだそうです。","id":"exchange-043"},{"speaker":"菊地委員","kind":"意見","question":"さっき言ったように、業者に対してそういう条件をつけるわけにいかないという話ももちろんそうだと思うんですけれども、そういう話もある程度次の業者にできるような形というのもまたちょっと考えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"原委員","kind":"確認","question":"一つだけ確認したいんですけれども、ここの三つのところで区の職員は何人いますか。いませんか。","respondent":"宮地区民課長","answer":"品川荘だけあと３人区の職員がおります。光林荘も３人です。","id":"exchange-045"},{"speaker":"石田副委員長","kind":"質問","question":"一つだけいいですか。これは項目がずっと出てきているんですけれども、これ以外の項目自体というのはなかったのかな。","respondent":"宮地区民課長","answer":"交通アクセスが加わったことと、もしお気づきの点がありましたら、また出していただければと思います。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/345074?Template=document&Id=2322#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":47040,"voices":155}},{"id":"h14-20020415-8","meetingId":"h14-cm04","date":"2002年4月15日","dateIso":"2002-04-15","committee":"建設委員会","time":"午後１時１６分～午後２時３５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"上山委員","kind":"質問・要望","question":"これは後で伺いますけれども、区のほうに何か要望みたいなことを出されていることがあれば、教えていただけませんか。","respondent":"中島街路事業担当課長","answer":"第１回の協議会につきましては、４月１１日、木曜日に開催してございまして、そのときには、区民の皆さんの参加をいただいたと聞いております。区民の方々も含めまして、７３名が参加されたと聞いてあります。","id":"exchange-001"},{"speaker":"上山委員","kind":"質問","question":"そういう援助というんですか、そういうものなどがあるかと思うんですけれども、何か区のほうとしてできるようなことは考えていらっしゃいますか。あるいは、何かできるのか、できないのか、そこら辺はどうなんか尋ねました。","respondent":"中島街路事業担当課長","answer":"地域住民等で設置されたまちづくり協議会の団体」という規定がございまして、私どもとすれば、この項目に適用できるのではないかなと思ってあります。私のほうでは、多分、要綱整備がされれば、要綱に基づきまして補助金等の手当…","id":"exchange-002"},{"speaker":"上山委員","kind":"質問・要望","question":"ぜひ中身を精査していただいて、適用が可能であれば、援助などもしていただければと思うのが１点と。これは要望にいたしますけれども、これは要望にとどめておきます、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"面的な整備というんでしょうか、一体的な整備というんですか、動きというのはあるんですかということが一つ。ある程度大づかみでも、実際に買収した場合の費用の財源構成はどうなっているのか、わかったら教えていただけますか。","respondent":"中島街路事業担当課長","answer":"再開発の説明が一区切りついてありますので、あるいは説明等をさせていただきながら、さらに賛同者を広げていきたいと考えています。私どもでご説明させていただいたときに、若干精査しまして、全体の事業費とすれば７３億８,５００万円です。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"私これを見てもよくわからないんですが、北というと区役所寄りかという気がするんですけれども、そこら辺も含めてお尋ねしたい。４分の１、４分の１なのか、わかれば説明を求めました。","respondent":"中島街路事業担当課長","answer":"実際に、再開発する地域は約２,８００m2のエリアを、現時点では考えてあります。約５割強が財調、残りの２割弱が都市計画交付金ということになっています。","id":"exchange-005"},{"speaker":"上山委員","kind":"質問","question":"年間、何回かあるかと思うんですけれども、昨年の５月ごろにもやったと思うんですけれども、大体、いつもこのぐらいだったんでしょうか。いろいろあってこうなったと思うんですけれども、それがいいとか悪いとか言うんではなくて、大体このぐらいの数だったんか尋ねました。","respondent":"田村住宅課長","answer":"平成１３年５月の実績で言いますと、大崎、八潮、東品川と南品川のスーパーリフォームを含めまして１４戸ということです。そういう意味では、今回は八潮団地６戸ということで、半分ぐらいです。","id":"exchange-006"},{"speaker":"上山委員","kind":"意見","question":"６戸ではあまりにも、この部分について、品川区が悪すぎるとは言いませんよ。全体で品川区がとるわけにもいかないと思いますけれども、何らかの形でないのかなと思います、感想だけとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"辻委員","kind":"質問","question":"若年ファミリー向け４５戸というのは、これは新築なのか、あき家なのか、どうなんか尋ねました。","respondent":"田村住宅課長","answer":"通常の都営住宅の申込み基準プラス、申込み者本人を含め、同居親族全員が４０歳未満であるというのが条件です。都全体では、都営住宅の入居者年齢が高齢化現象ですので、若年向けにも住宅を供給しようということで始めたものです。","id":"exchange-008"},{"speaker":"辻委員","kind":"意見","question":"これは登録制になっているんですが、この１年間で、全体的に入るのに待ったけどだめだったということがあると聞いている。ここのところの傾向としては、品川区は、都営住宅に当たった後にどうなっているのかはわからないだろうけど、要するにどういう状況なのかとの意見を述べました。","respondent":"田村住宅課長","answer":"使用承継の問題など、本来入るべき方々が入居できないという形で、都においても都営住宅の抜本的な改革に取り組んでおります。その中で、ほんとうに住宅に困窮している方がなるべく入れるよう考えておりますので、区としても、このような都の動きを注視してまいります。","id":"exchange-009"},{"speaker":"辻委員","kind":"質問","question":"登録というのは期限があるんですか。１年たつと、もう１回やらなくちゃいけなくなる。","respondent":"田村住宅課長","answer":"東京都のほうにも品川区の説明をしましたら、登録された方については、必ずあっ旋をするということです。あっ旋は必ずするものということで、期間は、一応設けておりません。","id":"exchange-010"},{"speaker":"辻委員","kind":"質問・要望","question":"どういう状況にあるのかということが、都にどうなんですかって聞いたって、ひとつよろしくお願いします。相談にのっていただくよう要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"沢田委員","kind":"質問","question":"都営住宅というのは総数で２,０００戸ぐらいですか、それぐらいの割合として、どういう基準でやっているのかというのがよくわからないんですよ。都がやることだから、よくわからないのかもしれないんですけれども、ちょっとわかったら教えてほしいんですけれども。","respondent":"田村住宅課長","answer":"７月に品川区の地元割合、あと１０月に新築、１２月にポイント方式とあります。このぐらいのあきが生じるだろうということであき家発生率を見込んで、あるいは１０月がどうなのか、一概には言えないと思います。","id":"exchange-012"},{"speaker":"沢田委員","kind":"質問","question":"ポイント方式は、ずれてやっていく、これは基本的にはあき家ですよね。そちら用に確保しちゃうんじゃないのかなという気がするんですけど、そういうことはあまり反映されないんですか、これは。","respondent":"田村住宅課長","answer":"知事が、あるいは首長が、その事業に対して必要な数を公募の例外にするというのは法律で決められております。正直言いましてわかりませんので、現実にどういう基準になっているのか、そこまでちょっと承知していないということです。","id":"exchange-013"},{"speaker":"築舘委員","kind":"質問","question":"それからまた逆に、お金が払えないというか、賃料を滞納して、強制執行していくような状況が含まれているのか。実際に、都のことだから詳しくはわからないと思いますが、それがわかれば説明を求めました。","respondent":"田村住宅課長","answer":"数字的にも、たしか過去１０年ぐらい載っていましたけれども、かなりの数です。先ほどもお話ししましたように、今後、都では都営住宅の抜本的見直しを進めていますので、さらに適正な管理を進めていくと考えております。","id":"exchange-014"},{"speaker":"築舘委員","kind":"質問","question":"その後のそういうことを住宅課でやっているんですか。調整的なことを主にやっている課というんですか、第三者がやっているのか、その辺の事情がわかれば説明を求めました。","respondent":"田村住宅課長、山室住宅指導担当部長","answer":"区内にある都営住宅の管理については、やはり都がやっております。区の場合には、もちろん都から移管を受けました区営住宅がありますので、東京都住宅局とは絶えず連携をとりながら、作業を進めているところです。 都営住宅の滞納、ないし高額所得者対応は、基本的には住宅供給公社のほうに事務を代行させているという状況です。区のほうで直接、都営住宅居住者の書類調査だとか、滞納処分者への取扱いを行うということは特段ございません。","id":"exchange-015"},{"speaker":"沢田委員","kind":"質問","question":"ちょっと制度全体のことだとかですが、利用件数がどれぐらいで、その中で、戸建て住宅と共同住宅の区分けみたいのがわかっていれば、ちょっと教えていただけますか。","respondent":"田村住宅課長","answer":"ここから少し下がりぎみで、平成１２年度につきましては７件、平成１３年度については３件ということで、融資実行件数が落ちております。１戸建てですと、ベランダのペンキ塗りの工事ということで、いろいろな工事が件数の中に出ているという状況です。","id":"exchange-016"},{"speaker":"沢田委員","kind":"質問・要望","question":"昔みたいな需要がなくなっているのかどうかよくわからないんですけれども、これはもうちょっと利用されるんじゃないかという感じがするんですけどね。廃止だなんていうことにならないように、所管として広げていくようによろしくお願いしたいと思います、要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"辻委員","kind":"質問","question":"大体、普通の家で、例えば太陽光発電を設置して、どのぐらいの総額になるんか尋ねました。","respondent":"田村住宅課長","answer":"いろいろな業者で出していますので、やはり３００万円ぐらいの金額になるかと思います。太陽光システムの設置だと、単価を見ていくと、下がり傾向にあるのかなという感じです。","id":"exchange-018"},{"speaker":"辻委員","kind":"質問","question":"この事業期間は平成１５年３月３１日と固定しているんですか。新規事業なんだけれども、どういう意味合いなんでしょうか、平成１５年３月３１日までに工事が完了するということは。","respondent":"田村住宅課長","answer":"要は、予算が年度ですので、助成金を出す場合には、あくまで年度で完了して、今年度の分として助成を出すということです。そのまま中抜けしないで、来年の４月から来年度予算で対応するということです。","id":"exchange-019"},{"speaker":"辻委員","kind":"質問","question":"どっちが得をするんですか。この辺はどうなんか尋ねました。","respondent":"田村住宅課長","answer":"熱温水器だけを設置したいということについては、５％もらえるようになりますので、そちらの選択ができるということです。そういう種分けで考えているところです。","id":"exchange-020"},{"speaker":"辻委員","kind":"質問","question":"これから、どちらの制度も利用できるその中でこういう形をとることで、より有利な形で太陽光を設置できるということがよいのではないでしょうか。屋上でですけど、少し間をあけて屋上のあいているところに置こうじゃないかといったときに、マンションの管理組合の申込みは大丈夫なんか尋ねました。","respondent":"田村住宅課長","answer":"あくまで個人が申込みになりますので、その証明さえ取れれば、考え方としてできることになります。実際に建物の屋上に置いて各戸が利用できるのが現実にあるのかどうか、ちょっと私のほうも、戸建てについてはあれなんですが。","id":"exchange-021"},{"speaker":"辻委員","kind":"質問","question":"事業評価はどうかというと、私は、そっちのほうがあると思う。実績が上がらないのだったら、そういう方法も考ていってもいいのではどうなんでしょうかということを言っているわけです。","respondent":"山室住宅指導担当部長","answer":"区民の皆様へのお知らせ等については、この仕組みをわかりやすくご理解いただけるように、住宅課のほうを指導していきたいと考えています。我々も大きな願いを持ってこれから進めていこうかということですので、ご支援いただくよう、よろしくお願いいたします。","id":"exchange-022"},{"speaker":"沢田委員","kind":"質問","question":"三、四例あるんじゃないですか。ちょっと、そこいらを説明していただけますか。","respondent":"田村住宅課長","answer":"国のほうは１０８万円ぐらい、１０倍しても１２０万円なんで、個人が設置した場合に１２０万円近く受けられるという制度です。","id":"exchange-023"},{"speaker":"沢田委員","kind":"質問","question":"３kwで１４０万円から３００万円ということだったんですが、これは１kw当たり１２万円ですから、３kwというと３６万円。それプラス、品川区の最高１５万円までということで、これはダブルでいいわけですね。","respondent":"田村住宅課長","answer":"そのとおりです。","id":"exchange-024"},{"speaker":"沢田委員","kind":"質問・要望","question":"例えば住民票が出されていれば、納税証明なんていうのは、内部で確認できますよね。それからもう１点、一覧でわかるようなものに統合していくことも必要なんじゃないかと思うんですけれども、いかがか尋ねました。","respondent":"田村住宅課長","answer":"もっと例えば雨水利用だとか、屋上緑化も含めて、区全体でいろいろな事業を考えているということです。あるいは環境に類するものでくくるのか、そこら辺も含めて、将来的には検討していかなきゃいけないと考えています。","id":"exchange-025"},{"speaker":"沢田委員","kind":"質問・要望","question":"今の手続の改善というのは、修築資金のほうも含めて、大いに利用が簡素で、簡単にできるようなものを工夫してほしいと求めました。ですから、ここへ行けば大丈夫だとかというような体制をしっかりして、それも含めて広報をしていただきたいなという要望を述べて終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"辻委員","kind":"確認","question":"建築確認だ何だというのは、どのぐらいの規模ですか。ただ畳の１畳か２畳ぐらいのは建築確認なんか要らない。","respondent":"田平建築課長","answer":"ある程度、一定規模以上になりますと、４００万円とか５００万円かかるということですと、それ相応の配管設備があります。メーカー側のほうでも、そういうものが、今、徹底されておりまして、そういうものを出しております。","id":"exchange-027"},{"speaker":"辻委員","kind":"確認","question":"温水器は最近やってますねときどき、屋根の上に乗って確認みたいな。事前に説明に来たときに、建築課のほうと事前協議をもっとやっていただいて、後になってだめだと言うことがないよう関連課と調整してください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"横山副委員長","kind":"質問","question":"やはりこれと同じようにヒヤリ地図というのがあるんだと思うんですけれども、警察署管内は、これ１通で間に合わせているんですか。状況的には、この４枚で済ませちゃうということか尋ねました。","respondent":"奈良交通安全担当課長","answer":"各年度で、各警察署管内１カ所ということで、それが１０年度分で４０カ所やって、トータルで品川区内のヒヤリ地図ができ上がるです。平成１３年度分で、これでお終りです。","id":"exchange-029"},{"speaker":"横山副委員長","kind":"質問","question":"そういったところに配られるということになると、一応は、ここに載ってないまちの方々にも配られるということですよね。現に事故がたくさんあるところはあるわけですから、年に何町会ですか、何かちょっと腑に落ちないような気がするんですけど。","respondent":"奈良交通安全担当課長","answer":"学校につきましては、これに該当する管内の小学校、あるいは保育園に配布するということでございまして、それで順次配布していくですので、よろしくお願いします。","id":"exchange-030"},{"speaker":"築舘委員","kind":"質問","question":"警察署管内でやっていても、これは品川区として責任を持ってやっているわけですから、それで対応されても困る。だから、そこの部分は、次の年度で予算をとってやりますというのならいいんですけれども、そこを聞きたい。","respondent":"岩田管理工事課長","answer":"区のほうで原因を究明して、ハード的な対策で対応できるようなものが何があるかということを、その都度検討していくわけです。これだけ４カ所、１０年間かけて、きちっきちっと地域をつぶしていこうということで考えております。","id":"exchange-031"},{"speaker":"上山委員","kind":"質問・要望","question":"ちょっと要望なんですけれども、１０年経って、また大分状況が変わっていくことも多いと思うんです。ちょっとそこで、考え方はどうなんか尋ねました。","respondent":"岩田管理工事課長","answer":"平成１３年度から初めて行ったやり方でして、地域の方に一堂に会していただいて、それぞれがシールをぺたぺたと通路に張っていくような作業なんです。毎年こういう紙ベースのやり方で１０年もかけてちんたらという感じはしますので、今後…","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/807981?Template=document&Id=3716#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":22133,"voices":99}},{"id":"h14-20020415-9","meetingId":"h14-cm04","date":"2002年4月15日","dateIso":"2002-04-15","committee":"文教委員会","time":"午後１時１５分～午後４時２９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を70件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"山路委員","kind":"質問・要望","question":"ＩＴ講習会に関しまして、一般質問とか予算・決算特別委員会でも質疑をさせていただいたんですけれども、もう１回確認をしたいんです。予算はもう使われたんですか、余っているということじゃないんですか、その辺について説明してほしいと求めました。","respondent":"上川内生涯学習課長","answer":"それに見合った数ということで品川区では約１万７８０人という数値を出しまして、それを目標に各所管でできるだけの講座回数をやってくださいと。余った分は生涯学習課で引き受けて、平成１３年度におきましては９,０９８名という数字になったわけですが…","id":"exchange-001"},{"speaker":"山路委員","kind":"質問","question":"そうなりますと、今年また新しくやるということですが、それは区独自に計画しているということか尋ねました。","respondent":"上川内生涯学習課長","answer":"契約落差とか、予定に足りなかったところ、それにつきましてはまた平成１４年度に申請をしてくださいということを呼びかけております。私どものほうとしましても、今申請をしています。","id":"exchange-002"},{"speaker":"山路委員","kind":"質問","question":"そうなりますと、平成１３年度の総括としまして、１人でも多くの人がパソコンを扱えないことがないようにという当初の目標は達成したとお考えか尋ねました。","respondent":"上川内生涯学習課長","answer":"ほぼ達成できたのではないかと、ただしまだ余裕があるということで、さらにスキルアップの意味もありまして申請しています。","id":"exchange-003"},{"speaker":"山路委員","kind":"意見","question":"学校施設を主に多く使っておりましたので、その中でＰＴＡの方に対する負担があまりにも重過ぎるということで、相当苦情もあったんです。今年は学校施設は使わないで、新たにクラスを変えてやるということですけれども、どういうことを考えていらっしゃるのかとの意見を述べました。","respondent":"上川内生涯学習課長","answer":"場所はきゅりあんを使って、ノートパソコンを備えつけてありますので、４００人を対象にきゅりあんでやる予定でおります。","id":"exchange-004"},{"speaker":"山路委員","kind":"提案","question":"具体的に上級クラスとか、あるいは相談窓口も増やしましたね。昨年提案したことがあるんですけれども、その辺のサポートはどのように体制を考えられているかとの意見を述べました。","respondent":"上川内生涯学習課長","answer":"国の補助金でやるＩＴ講習会は、初歩的な基礎編のものを対象とした補助事業でございまして、平成１３年度と同じような講習内容で実施する予定です。都道府県では６名の方が東京都に登録されたらしいんですが、これは１年限りの施策で、登録そのものが残っていないというお話です。","id":"exchange-005"},{"speaker":"山路委員","kind":"意見","question":"新しい方式としまして、文京区で登録で気軽にパソコン初心者のための無料練習場を開設するという情報は入っていますね。新聞にも載っておりましたので、そういう方向性のことは何か考えていらっしゃるのかとの意見を述べました。","respondent":"上川内生涯学習課長","answer":"１２時間程度で基礎編ということもありまして、生涯学習としてこれからご自身で主体的に自主的に学んでいくきっかけにさせていただきたい。今後平成１４年度に向けまして、わからない方は基礎編に入っていただくとか…","id":"exchange-006"},{"speaker":"山路委員","kind":"意見","question":"ここの陳情の出ているのは、初心者対象をサポートしてほしいということですよね。この辺も含めて、多角的に予算を請求してやるということでよろしいわけですねとの意見を述べました。","respondent":"上川内生涯学習課長","answer":"それはそれで、また再度やってまいります。全体で平成１４年度の各所管の予定を積み重ねますと、定員２,５８５名のパソコン講座が開かれる予定になってあります。","id":"exchange-007"},{"speaker":"山路委員","kind":"質問","question":"そこで、予算特別委員会でお聞きした時点で時間が来ましたので聞けなかったんですが、品川区に約１万人ぐらいいらっしゃいますね。その中で参加した方は、東京都で掌握しているということでしたけれども、品川区で大体数はつかんでいらっしゃいますね。","respondent":"上川内生涯学習課長","answer":"受付の段階で、年齢と人数は把握しているんですが、基本的に日本語でやるものなので、日本語が話せる外国籍を持っている方とか、そういう分類の数は把握しておりません。","id":"exchange-008"},{"speaker":"山路委員","kind":"質問","question":"１万人もいらっしゃるんですから、外国の人だけで１教室を設けられるのだったら設ける必要があるんじゃないでしょうか。東南アジアとかは日本より進んでいるじゃないか尋ねました。","respondent":"上川内生涯学習課長","answer":"外国人の方というのは、英語圏の方なのか中国語なのかいろいろあると思いますが、そういう情報は入っておりません。","id":"exchange-009"},{"speaker":"山路委員","kind":"意見","question":"外国人対象のＩＴ講習会も二、三十人ぐらいいらっしゃったら持つ必要があるんじゃないかと、こういうことをお願いしているわけなんですがとの意見を述べました。","respondent":"上川内生涯学習課長","answer":"講師を派遣してくださいとか、登録団体になって自主グループになったら、そういう制度はあります。日本の方と同じようにできると思いますが、ニーズというのは私のほうも具体的には伺っておりません。","id":"exchange-010"},{"speaker":"山路委員","kind":"提案","question":"いろんな形でやる必要がある一つとしてということで、全国の自治体はやっておりましたので、パソコンがやりずらいという方たちに非常に喜ばれているという資料を見まして、それで提案させていただきましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"意見","question":"この請願の趣旨というのは、レベルアップ講座ではないんですね。区として、助成の対象ということは考えていらっしゃるのかどうかとの意見を述べました。","respondent":"上川内生涯学習課長","answer":"初歩的なところの方々の質問にボランティアで対応するというのは、具体的に考えまして大変困難なものだと考えています。それから２４時間体制にならなければいけないとか、そういうふうに考えると、経費的にもレベル的にもかなり困難だと思います。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"レベルが上から下まで、専門家の方に質問しようとしたときに、やっぱりちょっと厳しいのかなと思いながらお聞きしました。その辺は結論的なことを先に聞いちゃったんですけれども、ちょっと中途半端になっちゃったんですけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"川西委員","kind":"意見","question":"頻繁に起こる疑問に対して、平成１４年度はレベルアップ体制ということで、さっきの説明のような一定程度の策を組んだということしかないわけです。そうすると、ちょっとこの請願の趣旨からすると違うような気がしますね、その辺をとの意見を述べました。","respondent":"上川内生涯学習課長","answer":"レベルアップ分もありますし、ほとんどの部分が基礎的な講座を各所管で再度平成１４年度はやっているんです。平成１３年度に基礎編に参加した方でも、もう一度基礎編に入って復習することはできますし、講座という形で行います。","id":"exchange-014"},{"speaker":"川西委員","kind":"質問","question":"９,８００万円の品川区の予算というのは、広報課でやっている予算も入っているでしょう、どんな割合なのか。ＰＴＡの皆さんがいらしっゃる、暑い最中に夏休み中でしたから、手当というのは全然出ないんか尋ねました。","respondent":"上川内生涯学習課長","answer":"そこで各所管の人たちが集中的に効率的に使っていくというふうに、平成１４年度は変えております。小中学校の５８校と５文化センター、全部で７４カ所、それぞれのところで委託料をお支払いしながらやっていたという数字です。","id":"exchange-015"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、平成１４年度というのは、きゅりあんと中小企業センターと心障会館、その辺に絞りましたね。学校施設の設備というのは、とりあえず一般は使わないというお考えか尋ねました。","respondent":"上川内生涯学習課長、指田教育次長","answer":"１年間の契約を全部の台数にしなければいけないので、やっぱり平成１３年度みたいに集中的に講座をやるわけではないので、所管でばらして効率よく二つぐらいの施設でまとめて講座をしていくという方向で考えました。 一般の方々が使う、アカデミーパックから外れますから、またライセンス料を１台について幾らというふうにお支払いしなければいけない。きゅりあんだとか中小企業センターで契約した分だけで動かしていこうと考えておりますので…","id":"exchange-016"},{"speaker":"桜井委員","kind":"質問","question":"その中で特に障害者の参加者がいたのかどうか、そして例えば障害者へのサポートというのは、何か具体的に考えられているのか。例えば、ここは教育委員会ですから福祉の分野とはちょっと違うかもしれないけれども、何か障害者のところで説明を求めました。","respondent":"上川内生涯学習課長","answer":"それから、パソコンの指導支援者講習会を定員２０名で行って、ボランティアを養成していくということ。それから、しなやかネットの会員を中心としまして月２回程度、１回に２人程度の個別対応のコースをやっていくというふうに聞いております。","id":"exchange-017"},{"speaker":"桜井委員","kind":"質問","question":"それから、心身障害者福祉会館でやるということは、所管的には福祉の所管で教育委員会と離れているということですか。そういう角度から、生涯学習的な発想で力を入れるとか、その辺はどうなんか尋ねました。","respondent":"上川内生涯学習課長","answer":"基本的にパソコンは画一的な機器になっていますから、障害者対応では心身障害者福祉会館のほうでは視覚障害者には特別の仕様になっているんです。時間も長くかかりますし、心身障害者福祉会館で…","id":"exchange-018"},{"speaker":"桜井委員","kind":"質問・要望","question":"心身障害者福祉会館の場合は、場所的には確かに制度として活用していく上でふさわしい施策だと思っています。実績を踏まえて生涯学習の分野でも、例えば文化センターという角度もぜひ広げていただきたいなと、これは要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"高星委員","kind":"質問・要望","question":"そこで考えてみたときに、私は紹介議員になっているんですけれども、こういう要望も出てきてしかりなんだろうなというふうに思います。区が直接業者と係わり合うというのは、きっかけをつくってしまったということから、できるだけ金のかからない体制を考えてできないんか尋ねました。","respondent":"上川内生涯学習課長","answer":"お客様窓口に電話してもなかなか通じないという声がいっぱいあるんですが、調べないで電話しちゃうから向こうもパンクしちゃうので、まずは調べる。その中で学び合うということで、うちのほうでは自主学習グループとか支援をしていますので、これはちょっと無理かなと考えていま…","id":"exchange-020"},{"speaker":"高星委員","kind":"質問","question":"業者１社と提携しろとか、その中でやる一つの作業として、個人のお宅にお邪魔しても構わないのかなというような気もするんだけれども。それから、自主学習グループ支援の事業をしていると言いましたね、それはどういうことなんか尋ねました。","respondent":"上川内生涯学習課長","answer":"学習グループを１人でやるのではなくて、グループをつくって学び合っていただくというのが、生涯学習課の一つの仕事でもあるわけです。ＩＴ講習会につきましても、グループをつくってお互いに本を読みながら、ほかの人とのスキルの交換をしながらスキルアップをしていただく。","id":"exchange-021"},{"speaker":"高星委員","kind":"質問","question":"今の話でよくわからなかったのは、自主グループ支援というのは講習会を受けた中で、あるいは受講が終わった人に、「こういうグループをつくりなさい」という指導をしていくということか尋ねました。","respondent":"上川内生涯学習課長","answer":"そこの中で自主的に学習をしてください。年に１回程度は講師派遣料を持ちますよという制度もありますので、そういう中でやっていかれるほうがいいのではないかということです。","id":"exchange-022"},{"speaker":"松澤委員","kind":"質問","question":"１人ということですね。どういう方かわからないか尋ねました。","respondent":"事務局","answer":"それはわかりません。","id":"exchange-023"},{"speaker":"松澤委員","kind":"質問","question":"紹介議員で高星委員がいらっしゃるんですが、この方とお会いになって、どんな感じの方か尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"松澤委員","kind":"質問","question":"これだけの方が署名していますよというものが多いものですから、各会派の方が署名しているので、何でかなと感じたんです。どこへ入れようかとやっているものですから、それらから見ると、これを始めると行政が邪魔をする。","respondent":"指田教育次長","answer":"私どももこの請願をいただきましていろいろ検討してみましたけれども、当時してきたことを考えていただきますと、底上げをやったという内容です。このように、今のところ私どもは考えているという状況です。","id":"exchange-025"},{"speaker":"桜井委員","kind":"質問・要望","question":"あるいは社会登録団体になっての補助とか、必ずしも初心者向けでなくても、一歩講習のランクがあるわけじゃないですか。それはそれなりの要望レベルがあるから、そういうところにだれでも基本的には参加できるような、そういう体制づくりというのはいいと思うんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問","question":"確かにパソコンをいじっていると、その辺のニュアンスが全然違ってくると、審査が全然変わってきてしまうんじゃないかなという気がするんです。行政がやるんですかと聞いたのは、個人的なものじゃないかなというところからスタートして質問をしているんですけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"高星委員","kind":"確認","question":"委員会の流れの中で、委員長の仕切りで今回は継続して、それまで中身を確認しましょうと言うのであるならば、私は結構です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"桜井委員","kind":"意見","question":"それは個々に紹介議員を通してやるのか、それとも委員長が請願代表者にお会いするのか、どういうふうな……との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"桜井委員","kind":"意見","question":"たまたま高星委員がこちらにいらしたけれども、それぞれ紹介議員になっているから、もしそれであればうちの上山議員を通して請願代表者に聞いてもらってもいいんだけれども、それぞれがそれぞれに聞いて違うなんていうことはないだろうねとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"川西委員","kind":"質問","question":"その方に指導を受けてＩＴをいろいろやっているんですから、そのぐらいの方です。ですから、日常的に２４時間かどうかはわかりませんが、日常的に相談できる体制が必要だというのが趣旨だと思うんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"桜井委員","kind":"意見","question":"例えば請願代表者にそれぞれの紹介議員がどうだこうだと聞くのも、議会としてあれですよね。私が直接電話して、それぞれ皆さんが電話しても──要するに個別にしてほしいのか、そこなんですよとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"高星委員","kind":"質問・要望","question":"そういうふうに扱ってもらって、扱いは継続にしてもらえばありがたいというふうに、私も紹介議員をやっていて不本意なんだけれども。ただ、やっぱりＩＴ全体の底上げを少しでも多くの人にしてもらいたいという願いからだけでありまして、そういうことはご理解ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"桜井委員","kind":"質問・要望","question":"４点ほどありますが、クラスが増えるということですからそうかなと思うんですけれども、学校への具体的な変更を知りたいと思います。そのことを所管は違うけれども、選択制によってもたらす問題ですから、教育委員会は児童課とのパイプというのでしょうか、その辺はどうか尋ねました。","respondent":"谷田部学務課長","answer":"第二延山小学校で行ってありますすまいるスクール、今年度は３校追加いたしまして４校で実施しているということで。就学通知を発送した後、指定校変更の希望のある方につきましては、それぞれの理由等を伺った中で指定校を変更していくという状況です。","id":"exchange-034"},{"speaker":"桜井委員","kind":"質問","question":"現在やっているわけでもありませんし、そういう影響が出ているという場合、児童課との協議はあるのかという質問をしたんです。この辺は前回の２月のときも質問して、あれば聞きたいと思います。","respondent":"谷田部学務課長、青木指導課長","answer":"先ほどの私の説明で、小学校の３０人以下の学級数の占める割合を７２％と、３１人以上は２８％という関係になっております。やはり相乗的な効果を高める上では児童課とは連携を取っていかなければならない事業だというふうに思ってあり… １学級になってしまったという学校に例ですけれども、その場合にはやはり２学級というような形のほうが、そうした指導をしております。それぞれの学校の状況に応じて…","id":"exchange-035"},{"speaker":"桜井委員","kind":"質問・要望","question":"ですから、実態をどういうふうに考えていくのかというのを、次回でもいいですからぜひ要望しておきたいと思います。自然増員ではなくて、そこだけ確認しておきたいんですけれども、影響なければ「ない」でいいです。","respondent":"谷田部学務課長","answer":"学童保育クラブに関しましては、児童課長に私から伝えておきます。それから、２点目の予算のつけ方、学校の人数によって増減があるかないかという影響ですけれども、こさは基本的にないと思ってあります。","id":"exchange-036"},{"speaker":"川西委員","kind":"質問・要望","question":"そんなようなことなんですが、そのことを把握して今後のことをどうお考えになっているのか。旧日本たばこはどこの学区域になるのか、その辺で地域の人がとても騒いでいるので、若い世代もおりますので聞かせてほしいと求めました。","respondent":"谷田部学務課長","answer":"１点目の３８名学級を２クラスにすることは、いわゆる４０人学級が基本ですから、２学級にはならないです。それから、旧日本たばこのところは城南小学校が学区域です。","id":"exchange-037"},{"speaker":"川西委員","kind":"質問","question":"分譲マンションですからマンションを買いますと夫婦で働くということがありますので、３年、４年後には学校の就学も増えていくと思うんです。ですかから、その点を考えると、やっぱり今から少し協議書が回ってきたのなら対策をお願いしたいということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"質問","question":"具体的に名前が出ていたんですけれども、もう一つ品川自動車練習場の跡地にも完成間近のマンションができております。それはどういう対応を、城南幼稚園も今年は定員から１人割っていただけですから、その辺はどういうふうにお考えになっているのか尋ねました。","respondent":"谷田部学務課長","answer":"ですから、区民住宅につきましては、大体経験則で持っていますけれども、民間の開発につきましては価格帯が安いものから高いものまである。５００戸供給して、施設の整備ですとか、当然そういうことを考えていかなければならないというふうに思ってあります。","id":"exchange-039"},{"speaker":"高星委員","kind":"質問・要望","question":"まさしくその中で学校関係者というのは、はっきり言うとまだ守りが強いというか、現場団体ではなかなか払拭仕切れないところがあるじゃないですか。だから、そのことをひとつ大丈夫かなということをお聞きしたいと思います。","respondent":"青木指導課長","answer":"地域の実態に精通している方、学校教育に実権を有し学校経営を客観的に分析できる方とか、いろいろ条件を挙げております。ただ、それぞれの学校が少しでも改善につながっていくようにということで、外部評価者を選んでいただきたいということはご説明しているところです。","id":"exchange-040"},{"speaker":"高星委員","kind":"質問・要望","question":"総体的なことを出して発表するということになっているんですけれども、例えば評価者を委嘱したときに何年間委嘱するというサイクルになっているのか。一定程度の評価を出した後もきちんとそれをチェックしてという、委嘱の期間ということも含めて、その辺の流れを教えてほしいと求めました。","respondent":"青木指導課長","answer":"そして３月の段階で、もう１回説明会を持ちます。３月の段階では、このような形で評価者の皆さんのご指摘、評価を生かしておりますというような形で、校長から外部評価者の方たちにご説明します。","id":"exchange-041"},{"speaker":"桜井委員","kind":"質問・要望","question":"それから二つ目には、要するに評価をする人にとっては学校像というんですか、こうあってほしいとか、こうすべきだとかそれぞれ違うと思うんです。だから、そういう視点での学校を評価していく上でのお互いの意見交換というんですか、当然レクチャーというんか尋ねました。","respondent":"青木指導課長","answer":"当然、それぞれの学校の説明会の中でも、校長から今年度の重点とか、具体的な目標とか、そういうものを示していく。学校もそのように考えて、学校評価を取り組んでいくことになるというふうに確信しております。","id":"exchange-042"},{"speaker":"桜井委員","kind":"質問・要望","question":"学校環境とか、そういうものを載せなかったのは何か理由があるんでしょうか。学校施設をチェックというんでしょうか、学校環境整備というものも項目に加えていただきたいというふうに思うんですけれども、いかがか尋ねました。","respondent":"青木指導課長","answer":"今回の学校評価がいかにつくられたのか、前にもご説明したと思います。委嘱の日時ですが、５月１３日に委嘱式を荏原文化センターで行うというふうに考えております。","id":"exchange-043"},{"speaker":"桜井委員","kind":"質問・要望","question":"できたらほしいと求めました。５月１３日ということは、評価委員会というのはほとんどそろっているという理解ですね。","respondent":"青木指導課長","answer":"今、学校では早速いろいろと、学校のそれぞれの形で進めている最中です。こちらのほうにそれぞれの学校の候補者がそろったところで、整理をして５月１３日を迎えたいというふうに考えております。","id":"exchange-044"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"３月の委員会で説明をいただいたときに、これは学校５８校に５８人の専門家が入るということになっているんですか。それからもう１件、社会性・人間性の育成に関しての２点というのは、その点についてお答えほしいと求めました。","respondent":"青木指導課長、指田教育次長","answer":"それから、２点目ですけれども、または子どもが意欲的に取り組んでいるだろうかというようなところから入っていきます。子どもの実態を説明していくのかというところが、大きな鍵になってくるんじゃないかというふうに考えております。 私のほうは評価者訓練をやっていこうと思っています。具体的にどういうふうにするのか、専門用語で評価者訓練と呼ばせていただきますけれども、一応研修的なものを考えているです。","id":"exchange-045"},{"speaker":"鈴木（真）委員","kind":"質問","question":"多分評価者になるんだろうというふうに言われている、ちょっと声がかかっている方から、その辺の質問もあったんです。それから、専門家の方が５８人、ばらばらに１人が２校、３校を受け持つということはなくて、５８人がばらばらでやるわけか尋ねました。","respondent":"青木指導課長","answer":"１校ないし２校、もし「３校でもいいよ」という方がいらっしゃれば、またお願いするかもしれません。お願いする個人によって、校数が変わる可能性は多分にあります。","id":"exchange-046"},{"speaker":"鈴木（真）委員","kind":"質問","question":"聞きにくい部分ですけれども、評価者の方に対しての実費的なものは出るような形になるんか尋ねました。","respondent":"青木指導課長","answer":"あくまでボランティアという形でお願いしますけれども、１年間終わった段階では心ばかりの形のものはお示ししたいと思います。","id":"exchange-047"},{"speaker":"松澤委員","kind":"意見","question":"ＰＴＡはわかるんですけれども、地域団体関係者は町会関係あるいは地域の民生委員・児童委員、保護士あたりが入るのかなと。なかなかどの学識経験者というので、この中で議員は選びませんという形になっているのか、優秀な議員を選んでいいというのかとの意見を述べました。","respondent":"青木指導課長","answer":"議員はこの対象には入っておりません。","id":"exchange-048"},{"speaker":"桜井委員","kind":"質問","question":"ただ、報酬というのか実費というのか、手当てというのは正確ではないんですけれども、きちっとそれはすべきだと思うんです。１年間でご苦労さまでしたと、きちっとすべきだと思うんですけれどもいかがですか、予算化していないんか尋ねました。","respondent":"指田教育次長","answer":"予算化はしていますので、今言われた話というのは、ある意味において、そんなにいっぱい高くは出ませんという意味で、ボランティアと言っただけであって、実費弁償額のお支払いは当然のことだというふうに思っております。","id":"exchange-049"},{"speaker":"桜井委員","kind":"質問","question":"学力向上推進協議会というのは、どういう性格を持つものでしょうか。３年間の常設なのか、これはメンバーの中の一員というふうにしていくのか、協議会の性格と構成と内容を説明を求めました。","respondent":"青木指導課長","answer":"その１地区の協議会として、いろいろな調査の協力依頼も当然４校に出てきますけれども、単なる学校だけの研究ではないということであります。学力向上の取り組みにいろいろなご意見やご感想等をいただきながら進めていくという…","id":"exchange-050"},{"speaker":"桜井委員","kind":"質問","question":"それで、何をするかというと、教材開発とか指導体制とかをやっていくんですか、これはどっちかというと教師側の作業ですよね。調査等の依頼とか、成果の普及とかというのは、また別の仕事というのかちょっとよくわからないんです。","respondent":"青木指導課長","answer":"２校の学校が核になりまして、１校の研究だけではなくて、地域として研究を深めていけるような協議会にしていきたいということであります。これから学校とも連絡を取り合って、具体的な内容は詰めていきたいというふうに考えています。","id":"exchange-051"},{"speaker":"桜井委員","kind":"質問","question":"依然としてわからないんですけれども、国レベルだって県レベルだって、そうすると品川区レベルであるということになると、品川区の教育委員会の中に推進協議会を置くというふうに、よくわかるように説明を求めました。","respondent":"若月教育長","answer":"それによって、３年間ありますから１年間活動する中で、そのときはまたそれで考えていきたいと考えております。フロンティア・スクール担当の指導主事がおりますから、小学校と中学校の担当の指導主事はこのメンバーに入れていきたいと考えているのが現状です。","id":"exchange-052"},{"speaker":"桜井委員","kind":"質問・要望","question":"少しわかってきたんですけれども、性格が決まるという気がするんですが、それだけもう１回教えていただきたい。本当に一人ひとりの子どもたちが学べる力が育つようにしてほしいんですけれども、「今日は何の会議ですか」みたいな、そういうふうにならないように。","respondent":"若月教育長","answer":"むしろ文部科学省のほうが、それを全国に一般化できないかということで、この事業ができたというのが事実なんです。そういった意味では全く委員のご指摘の点というのは、ある意味では杞憂だというふうにお考えいただいていいと思います。","id":"exchange-053"},{"speaker":"桜井委員","kind":"質問・要望","question":"そういうものを尊重してほしいと思いますし、何かよくわからない説明だったもので、私は中学校が心配になったということです。ですから、一人ひとりの力をつけていくというところと、そこのところは十分に配慮いただきたいというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"山路委員","kind":"質問・要望","question":"個々に児童・生徒の差があると思うんですけれども、教育者が中心になってこれを進めていかなければいけないということになると思うんです。学力の資質ということに関しては、どういう角度を置かれる予定なのか聞かせてほしいと求めました。","respondent":"青木指導課長","answer":"私たちはそれを両面育てていかなければならないというふうには考えておりますので、やはり同じ考えを持っております。学力をどういうふうにとらえるのか、保護者や地域の方たちにも理解していただけるような、そうした場にしていきたいなというふうに考えております。","id":"exchange-055"},{"speaker":"山路委員","kind":"意見","question":"これだけ先生たちがいれば、相当学力は期待できるかなと私なりに思ったんです。ここの中にも書いてありますけれども、それとの関連性というのは、どういう研究をされてきたのか、特に算数・数学ということですねとの意見を述べました。","respondent":"青木指導課長","answer":"一つの授業に２人の教員がつく、もしくは二つの学級を３分解して３人でそれぞれつくという、そうした場面もあります。そのような形で、教員が１人のところを２人で見ていくことによって、また発展的な内容で指導していくというような方法を現在取っております。","id":"exchange-056"},{"speaker":"山路委員","kind":"質問","question":"能力の境界というんですか、チーム・ティーチングと習熟度別の補助教員をここに対応されていますね、各学校に充実していきたいんじゃないかと。効果というのはもちろん上がっていると思うんですけれども、具体的にどういうふうになったというのはつかんでいらっしゃるんか尋ねました。","respondent":"青木指導課長、若月教育長","answer":"それを今度は、品川区独自の学力調査で調べていきたいなというふうに考えております。品川区独自の学力調査を使って実態の把握に努めていきたいというふうに考えております。 戸塚第三小学校ではありませんけれども、日々の子どもたちとの授業の中で、きちんとわかる仕組みで個別の学習をしているんです。やはり、そういう日頃の努力というものをこれから開発をしていく必要があると、こんなふうに考えています。","id":"exchange-057"},{"speaker":"山路委員","kind":"意見","question":"悩んでいた１点なんですけれども、息子とか関係者とか友達とかにいろいろ聞きましても、基礎的学力というのは感じてこなかったんです。そういうことをどうやって解決するか、学力向上フロンティア・スクールの研究によって、全体に定着してくることを期待しているものですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"高星委員","kind":"質問","question":"どうもこの３年間で最終的には荏原第三中学校のほうになっちゃうのかわからないけれども、相当差が出てくるような気がしてならない。もう一つは、推進協議会の中で地域住民との関係も含めたそのほかの教育、その辺はどう考えらているのかお聞きしたい。","respondent":"青木指導課長","answer":"その子どもの習熟状況にふさわしい形で指導するので、差は縮まりながら全体としては上がっていくというふうに考えております。総体的に差を縮めて上げていくという考え方で算数や数学を取り上げておりますので、充実させていきたいというふうに考えております。","id":"exchange-059"},{"speaker":"鈴木（真）委員","kind":"質問","question":"全体のレベルアップはわかるんですけれども、小・中一貫校にも絡んでくる部分もあると思うんですけれども、ほかの小学校から荏原第三中学校に入ったときに、そこでのレベルの違いが出てくることはないんか尋ねました。","respondent":"青木指導課長","answer":"研究協力校の山中小学校、杜松小学校、戸越小学校というのは、すべてこの学校からも荏原第三中学校に行きます。荏原第三中学校と三つの小学校はそういう意味での連携はさらに深まるというふうに考えておりますし、どこの中学校に行っても対応できるような。","id":"exchange-060"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その辺が気になるので、やっぱりほかの学校も同じように指導を進めていってもらう形で、これは全体的にこの学校だけではなくていろんな学校に広がっていくでしょうけれども、その辺のところをなるべく意識していただきたいなという思いです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"だから、そういった面で全体との係わりというんですか、本当に子どもたちはどうなっているのかというのが見えないというのが１点。５日制の問題とか、その辺も品川区の子どもがどうなっているのかというのも、今後でいいんですけれどもお示しほしいと求めました。","respondent":"青木指導課長、若月教育長","answer":"１点目、学校の教育活動が保護者や地域の方たちにわかっていただけるように、今後もさらに学校のほうに働きかけてまいりたいと思います。３点目は… ですから、考え方としてはいろいろあると思います。しかし、そこから出てくる力を全体に広げていこうという指導観を今現在のところは使っていると、こんなふうにご理解をいただきたいと思います。","id":"exchange-062"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"地域の方からすると、すごく学校が忙しい、新しいことをいっぱいやっていらっしゃるんだけれども、忙しくて中身がわかりにくいというところが１点。そういうところでの理解というんですか、いろんな公募の仕方もしていると思うんだけれども、その辺をもうちょっと充実していただきたいと要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"桜井委員","kind":"質問","question":"転任が多いなと思うんですけれども、過去の実績からしてどうですか。例えば、去年、一昨年はどうか尋ねました。","respondent":"青木指導課長","answer":"去年は小学校で退職した方が２人でした。今年度の異動は特別多いということではなく、昨年度が少なかったということになります。","id":"exchange-064"},{"speaker":"桜井委員","kind":"質問","question":"つかぬことですけれども、前館長の退職金はいかがなんか尋ねました。","respondent":"上川内生涯学習課長","answer":"非常勤職員ですので、退職金はございません。","id":"exchange-065"},{"speaker":"桜井委員","kind":"意見","question":"次回でもいいんですが小・中一貫校について、例えばこの間公募されていた準備委員が決まったのかどうか、準備委員が開かれたのかどうか。次回でもいいんですけれども、もし時間が取れればお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"桜井委員","kind":"質問・要望","question":"要望しておきます。教育長自身も準備委員会に入っていらっしゃるわけですから、どういうご答弁だったのかというのは、情報公開でいただけるんか尋ねました。","respondent":"指田教育次長","answer":"質問書は情報公開の手続を取ってもらえれば、要望書・質問書は公文書ですから……。","id":"exchange-067"},{"speaker":"高星委員","kind":"質問・要望","question":"第二日野小学校の場合、土地が今どういうふうな状況になっているのか、この間説明に入ったのは日野中学校と第四日野小学校だけではないですよね。行かれた学校と日にちを教えてほしいと求めました。","respondent":"指田教育次長","answer":"一番初めに２月９日に日野中学校に行き、その後大崎第一地区連合町会の役員会に行って説明をしました。明日、大崎第一地区連合町会に行ってご説明をする予定でおります。","id":"exchange-068"},{"speaker":"高星委員","kind":"質問・要望","question":"いろいろ説明に入って、日野中学校では要望書が出て、それの回答も。それらの話は情報公開で手続を踏めば、要望書と回答書そのものはすぐ出ると。","respondent":"指田教育次長","answer":"何も隠すつもりは全然ありません。やはり私ども教育委員会もありますので、そこのところの出方も含めながら、よく相談をさせていただければと考えています。","id":"exchange-069"},{"speaker":"藤田委員長","kind":"質問・要望","question":"各委員、その他はありますでしょうか。昨年の９月２６日の当委員会におきまして、各委員の意見をお伺いしまして、このような意見がありましたという報告をいたしました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/547087?Template=document&Id=4434#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":48902,"voices":182}},{"id":"h14-20020415-5","meetingId":"h14-cm04","date":"2002年4月15日","dateIso":"2002-04-15","committee":"総務委員会","time":"午後１時１６分～午後３時３７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"一ついいですか。秘書というセクションを設けたということなんだけど、依然として兼務になっているけれども、その辺の考え方だけ教えていただけますか。","respondent":"本間総務部長","answer":"この考え方等につきましては既にご説明をさせていただいているとおりですが、こういう事務取扱という体制で臨んでいくですので、よろしくお願いいたします。","id":"exchange-001"}]},{"id":"topic-02","title":"の平成１４年度組織改正","agenda":"の平成１４年度組織改正","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"ちょっとお聞きしたいんですけど、主査と係長の違いはどういうところにあるんか尋ねました。","respondent":"小野（孝）政策担当課長","answer":"多くの場合は、担当主査１人の組織ということで、定められた事務分掌を担っているです。どちらの組織をとるかですけれども、業務の規模、あるいは内容によってそれぞれ適当な組織が選択されるという形になっています。","id":"exchange-002"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"すぐにどうこうというわけにはいかないんで、その辺、組織の単純化、わかりやすさというなら、お考えいただきたいと、これはお願いしておきます。目的を達したから廃止しますという説明があったんですけれども、研修というのは、目的が達成されたんか尋ねました。","respondent":"小野（孝）政策担当課長","answer":"あくまでも１年間、それなりの仕事を実施をして、このような見直しをしたものです。研修外務制度という新しい研修のシステムを、この１年間検討いたしまして、平成１４年度から実施をするということになっております。","id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問","question":"では、総務課の右上の欄に書いてある説明はちょっとオーバーじゃないですか、組織体制が定着したため研修担当課長を廃止する」と。もう一つ、その関係で言うと、担当課長の仕事がそれぞれできてきたのなら、じゃあ施設課長が今度施設担当課長になったら、１年でいくんか尋ねました。","respondent":"小野（孝）政策担当課長","answer":"１人の課長ですので、事業部制を実施するに当たりましては、その部分について担当したです。事業部制において、課題に柔軟に、敏速に対応するために必要に応じて置かれるという内容です。","id":"exchange-004"},{"speaker":"林（宏）委員","kind":"質問","question":"今の施設担当のことなんかは、もう施設課長でいいじゃないですか。区民にわかりやすさというのを、そのためにネームをつけているんだから、そういうのを考慮してほしいと思うんです。","respondent":"市岡企画財政課長","answer":"今のご指摘を考えていきたいと思うんですが、事業部の部の段階は、条例で組織の骨格を定めるということが法律の前提になっております。委員のご指摘の点は、いろいろな形で、今後、研究をしていきたいと思っています。","id":"exchange-005"},{"speaker":"北野委員","kind":"質問","question":"組織の改正で、施設課が各事業部の中に入っていって、直接発注ができるようになったというお話なんですけれども、どこまでの範囲なんでしょうか。いろいろな部分があったと思うんですけれども、どういうところに事業部制の独自性が打ち出されるようになったのか、ちょっと話していただけますか。","respondent":"片田施設担当課長","answer":"多少小規模なものであっても、一応、できるものについては民間委託を進めていきたいといったような観点で考えてあります。小規模な小破修繕工事につきましては、教育委員会の独自の発注ということで、自己完結をしていきたいといったことで考えてあります。","id":"exchange-006"},{"speaker":"北野委員","kind":"意見","question":"要するに民間との設計のやり取りも含めて、それから、業者を選ぶ段階も含めて、すべて事業部に任されるのか。どこまでの発注が、事業部制として各事業部に任されているのかというのが、ちょっとよくわからないんですとの意見を述べました。","respondent":"片田施設担当課長、本間総務部長","answer":"これは計画通知と申していますけれども、それが必要なものに対して、施設担当課のほうが行う。逆に、計画通知等々が必要でないもの、小規模なものにつきましては、各事業部のほうが発注を行うといったような考え方です。 今、課長がご説明しましたとおり、こちらに技術の職員を配置して、自前でそういう修繕等をやります。そういう意味で、そこだけの変更だと、ひとつご理解をお願いいたします。","id":"exchange-007"},{"speaker":"北野委員","kind":"確認","question":"さっきいろいろ出たと思うんですが、事業部の独自性というところで、もっと踏み込んだものかなという理解が私はあったものですから、確認をさせていただいたんですが、わかりました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"戸籍電算課が現場の区民生活事業部の中にできたということで、それぞれの業務が電算化されるつど、現場にこういう電算化担当組織というものができてくるという考え方なんか尋ねました。","respondent":"小野（孝）政策担当課長","answer":"戸籍住民課の中に戸籍電算化担当主査を設置して、これに対応するですけれども、内容についてさまざまです。その内容によりまして、新たに組織を設置して対応するということが必要な場合につきましては、このような対応が出てくる。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"内容というのは、開発の規模という考え方なんか尋ねました。","respondent":"小野（孝）政策担当課長","answer":"規模というのが一番大きな理由なのかと思います。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"現場の要望にこたえられないということから、現場に置くことによって、当初の予定よりも開発能力が増えるということが結構あるんです。ですから、そういうところが、また一方での懸念材料というんですか、心配なんですが、その辺は、全体で管理していくという考え方なんか尋ねました。","respondent":"田中情報システム課長","answer":"一切の修正を入れないで導入しますので、この部分については、所管課の要望によってあれこれと改修規模が膨らむということはありません。ここで、政策予算等の前に調整会議をやって、システム開発がタコつぼ的にばらばらにならないような形での調整を行っているところです。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"現場の要望を聞きすぎるという傾向になると思いますので、ぜひ、今後の検討課題にしてほしいと求めました。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問","question":"１点伺いたいんですけれども、企画部のところの行政評価担当主査というのが新設になっているんですけれども、その理由のところで、「行政評価事務の円滑な執行のため」ということを挙げているんですけれども、具体的にどういうことをやるんか尋ねました。","respondent":"小野（孝）政策担当課長、市岡企画財政課長","answer":"今回、平成１４年度におきまして、平成１３年度に政策として行った事務事業評価を全事業で実施をするということがあります。そういうものに対応するために、今回、つくったものです。 すみません、ちょっと補足しますが、平成１３年度も、当然、企画の担当主査が担当しておりました。平成１３年度、より一層の業務の円滑を図るために、あえて担当ということで明確化をしたです。","id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"そうしますと、この企画財政課の中に担当主査を置いているけれども、これは全体を見るという役割なんか尋ねました。","respondent":"市岡企画財政課長","answer":"もちろん全体を見ますけれども、特に事務事業評価というのは自己評価が原則ですから、各事業部が、まず見ます。それから全庁の調整という意味でも、企画部が各事業部を支援する立場ですから、全体の扇の要になるような調整事務を行うという意味です。","id":"exchange-014"},{"speaker":"宮崎委員","kind":"質問","question":"そういう組織図のようだったんですけれども、ここでは各事業部を企画部のところで評価を誘導しているとか、そういうふうなものということではないんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"各事業部を支援している形の取りまとめの部署ということで、どういう評価を各事業部が自己評価しているのかを取りまとめた上で、全体の調整を図るためのいろいろな資料等を作成しているという位置づけです。","id":"exchange-015"},{"speaker":"宮崎委員","kind":"意見","question":"私がちょっと疑問に思ったのは、各事業部との関係で、この役割がどういうふうな動きをするのかが、ちょっといまいち見えてないんです。それとも、やっぱり事業部は事業部で自分たちできちっとやると、そこら辺の関係がよくわからないんですけどとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"各事業部間でばらつきが出てしまいますので、その辺をうまく調整して、最終的に各事業部がきちんと自己評価ができるようなものを支援していくという形の役割です。","id":"exchange-016"},{"speaker":"塚本委員","kind":"質問","question":"組織と人は関連するんですけれども、財政援助団体と出向派遣の関係の人事異動、あるいは、リタイヤ組の人たちの異動があったというふうに聞くんですけれども、そういうのがあれば教えていただけますか尋ねました。","respondent":"桑村人事課長、本間総務部長","answer":"それから、その下に新たに成年後見センターというのができまして、その関係で中川原課長ですけれども、派遣しています。それから、これまで品川総合福祉センターに出ておりました岩崎が品川区勤労者共済会派遣となっております。 課長が説明しましたのは派遣でございまして、それ以外に退職理事者等々のそれといたしまして、品川文化振興事業団に小栗前区民生活事業部長が。それと、春光福祉会に、佐藤和子前課長…","id":"exchange-017"},{"speaker":"宮崎委員","kind":"質問・要望","question":"「安全性と効率性を同時に求められてきたが、今後は安全性の確認を最優先し効率性も求める」というふうに変えるということなんですけれども。安全性の確認を最優先するということと、効率性を求めるということの関係ですね、ここのところはどういうふうに考えておられるのか。","respondent":"小野（弘）副収入役","answer":"これからは、まずは安全性のある銀行を選びまして、その中で引合等で利率のいいところに預けていくということです。破綻ということがあり得るわけですので、まずは安全な金融機関を選択してから、その中で効率性を見ていくという考え方です。","id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問・要望","question":"安全性と効率性を同時に求めれば、今のご説明のように、安全な中から利率のいいものを選ぶということになっていたんじゃないのかなと思うんです。ですから、今の説明ですと、ちょっと中身がどういうふうに変わったのかというのがよくわからないんです。","respondent":"小野（弘）副収入役","answer":"そういったところで、そこに安全があるということで、その中で効率性を見ていたです。金融機関が破綻するということになりまして、公金も一般の預金者と同じ扱いになるですので、より一層安全性のほうを重視していくという考え方です。","id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問","question":"この辺は、ちょっと工夫してもらえればと思います。ここの方針は、ほかに幾つかの外郭団体がありますけれども、そういうところもこの方針が徹底されるということなんか尋ねました。","respondent":"小野（弘）副収入役、中尾根企画部長","answer":"こちらは、品川区公金管理運用方針ということで、区のほうの公金管理運用方針です。 各外郭団体につきましても、区が行っている管理運用方針を準用するように指導していきたいと、従来から言っておりますので、そのように取り扱っていただくよう、区としても要請をしていきたいと考えています。","id":"exchange-020"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、この文言があまりあいまいに受けとられるようなものだと、やっぱり困ると思うんです。そうすると、安全性と効率性というのは、安全かつ効率的ということでいいんか尋ねました。","respondent":"市岡企画財政課長","answer":"「預金その他の最も確実かつ有利な方法」という言葉を変えておりませんで、そういう意味では、両方が並列的で運用されているところなんです。その辺の要請を、十分勘案した表現になっているかとは思うんです。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問","question":"だから私、そのことを言っているわけです。問題の外国債は元本保証じゃなかったわけですから、私は言っていますので、そこのところは徹底していただくということにしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"そうでない可能性もかなりあるわけですから、そのときにはどうしていくかというと、そのときにどうするか。大枠の考え方はありましたけれども。","respondent":"小野（弘）副収入役、市岡企画財政課長","answer":"完全に安全だということが担保されるところであれば、１金融機関に預金高をある程度。分散して、なおかつ限度額をある程度設けて、その中で対処をしていきたいという考え方です。 これは、場合によっては預金総量との関係で、区が引き金を引かない程度の額にあらかじめ縮減するという必要が出てくるかもしれません。その辺は、しっかり具体的な内容を検討して、いざとなってからではなくて…","id":"exchange-023"},{"speaker":"塚本委員","kind":"質問","question":"公金ですから、数百万円ぐらいならしようがないという話し合いになるかもしれないし、６００億円からすれば。この２点、いかがか尋ねました。","respondent":"小野（弘）副収入役、中尾根企画部長","answer":"２３区につきましても、今のところはそれぞれが、それぞれで運用方針等をつくったりしています。今後は、２３区でできるだけ情報を密にしながら、間違いのないような形で連携を取りながら進めてまいりたいと思います。 今回のペイオフのいろいろなことについて難しいのは、自分たちのものの考え方を、ほんとうにみんながはっきり自由にさせておいていいのか。私たちの検討の中にも、そういうことは大分いろいろ入っていたという経過の中で…","id":"exchange-024"},{"speaker":"中島委員","kind":"質問","question":"こういうのはすごく苦手なんで、単純な質問を、疑問に思った部分があったので、お聞きします。そうすると、みずほ銀行というのはどこに入るんか尋ねました。","respondent":"小野（弘）副収入役","answer":"まだ、どこの銀行がどこかということは申し上げないということです。","id":"exchange-025"},{"speaker":"中島委員","kind":"質問","question":"１,０００万円以上は普通預金にするというご説明がありましたが、みずほ銀行の定期預金が５９億円されているわけですけれども、ちょっとどうなのかなという疑問があったものですから。","respondent":"小野（弘）副収入役","answer":"要注意領域には入ってございません。","id":"exchange-026"},{"speaker":"中島委員","kind":"質問","question":"そうしたときに、とても心配なものですから、ちょっと質問させていただきました。その辺のところをお含みおきいただければ、結構です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"宮崎委員","kind":"質問","question":"すみません、１点ちょっと、資料の５のところの国債というのは何か尋ねました。","respondent":"小野（弘）副収入役","answer":"日本国債です。","id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"わかりました。通常、国債と書くと日本国債ということなんか尋ねました。","respondent":"小野（弘）副収入役","answer":"通常、国債というと日本国債ととらえております。","id":"exchange-029"},{"speaker":"林（宏）委員","kind":"確認","question":"確認をしていきますけれども、まずペイオフというのは何なのかということを聞きますけれども、１,０００万円プラス利息だけですか。基本的な考え方は理解しています。","respondent":"小野（弘）副収入役","answer":"一応、保証されるのは１,０００万円とその利子までですけれども、その精算の後に残務金があれば、それはまたプラスで預金者に戻すということです。","id":"exchange-030"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"そうではなくて、明らかに寄附行為違反であるということを認識をしておいていただきたいけれども、それを確認しておきます。そういう意味で、外部の情報というものは、どのあたりから取れるんでしょうかね。","respondent":"小野（弘）副収入役","answer":"４ページの「安全性を計るデータ」ということで、項目を挙げさせていただきました。公認会計士等に、その財務状況の調査を一緒にお願いをして、状況を把握するということで考えてあります。","id":"exchange-031"},{"speaker":"林（宏）委員","kind":"質問","question":"区の持っている情報とか、判断が１００％なら、それはそれでもちろんしなきゃいけないけれども、そうじゃない場合があるわけですよね。それで、２ページの上から４行目に、「品川区資金運用基準」というのがあるんですけれども、これはもうつくられているんか尋ねました。","respondent":"小野（弘）副収入役","answer":"はい、基準についてはできてあります。一応、内部のものということで、外には出さないという形の取り扱いをしています。","id":"exchange-032"},{"speaker":"林（宏）委員","kind":"質問","question":"この基準というのを見ると、そういうものが入って、もちろんそれ以外のいろいろな情報の中でランクづけがされているということなんですか。基準だから、いわゆるスタンダードじゃなくて、いろいろなケースの、個の金融機関が入っているというものなんか尋ねました。","respondent":"小野（弘）副収入役","answer":"個々の金融機関については入ってございません。取り扱いの部分の優良領域、それから、その他、領域の決め方、それからプラスアルファの部分、そういったものを盛り込んです。","id":"exchange-033"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、４ページの図をつくる上での基準と考えておけばいいんか尋ねました。","respondent":"小野（弘）副収入役","answer":"はい、そういうことです。それに、もう少しプラス、例えば延納金の限度額とか、そういったものも定めてあります。","id":"exchange-034"},{"speaker":"林（宏）委員","kind":"確認","question":"そうすると、この図の見方をもう一度確認するんですけれども、横軸に、一番上に自己資本比率と書いてありますね、左端に、監視指標と格付け。要注意水準と２種類あって、格付けが重要なポイントになっていますと、そういう見方でこの表を見ていけばいいんか尋ねました。","respondent":"小野（弘）副収入役","answer":"そういうことです。格付けがないところがありますので、そういったところに関しては、監視指標という形で、危険領域なりを判断するです。","id":"exchange-035"},{"speaker":"林（宏）委員","kind":"質問","question":"だったら、格付けは要らないんじゃないですか。そうすると、格付けは除いちゃったほうがいいんじゃないんですかということです。","respondent":"小野（弘）副収入役、中尾根企画部長","answer":"決めていきます。 日本の企業のつぶれた５０社を、いつ、どういう格付けかという表も具体的に見せてもらいました。先ほど言いましたように、公表はちょっと控えさせていただきたいです。","id":"exchange-036"},{"speaker":"林（宏）委員","kind":"質問","question":"その証券会社のランクづけというか、そういうものはされるんですか。そうなってくると、証券会社の目安としては、証券会社のランクづけも必要になると思うんですけれども、やるんか尋ねました。","respondent":"市岡企画財政課長","answer":"それについては、何月何日現在の価格は幾らでご提示願えますかということを実際にやって、仮入札みたいなことをやって購入をしております。上場会社のしっかりしたところであれば、国債購入のときには等しく同じ条件で、あとは価格で差をつけていくです。","id":"exchange-037"},{"speaker":"林（宏）委員","kind":"質問","question":"１ページに、金融危機対応会議というのを開かれる書いてあるんですけれども、それに区がどう対応していくということですよね。これはだれが判断していくんか尋ねました。","respondent":"中尾根企画部長","answer":"金融危機対応会議ですけれども、これは国の開くということで、内閣に新設された会議です。いずれにしろ、判断は区そのものが、区の立場で行うということです。","id":"exchange-038"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"では、要望だけしておきます。そういうことも考えながら、十分な対策をとっていただきたいということをお願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"三上委員","kind":"確認","question":"一つ確認させてもらいたいなと思うんですが、大きい事務所に所属していると、必要な形で入る情報収集量というものが大きい。そこらあたりの見極めというのを、どういうふうに考えて選任されていくのか、そこのところをちょっとお伺いいたします。","respondent":"小野（弘）副収入役","answer":"品川区金融機関調査会につきましては、既に設置されてございまして、委員につきましては、既に決定しています。区として判断をするですので、こういった場合におきましても、区が判断できると考えています。","id":"exchange-040"},{"speaker":"三上委員","kind":"質問","question":"その人たちが品川区の調査会のメンバーに入っているということであれば、それはそれでいいですけれども、そうじゃないわけでしょ。ということになれば、その意見を聞くということをやらない限り、区は決定できない話になると思うんですけど、どうなんか尋ねました。","respondent":"中尾根企画部長","answer":"委員ですけれども、今、三上委員がおっしゃったように、少なくとも出発時点では、それを確認しておりまして、ダブっていることはありません。品川区だけに専念する方というのは当然ながら基本にしておりますので、そのように、運営を心がけていきたいと思っています。","id":"exchange-041"},{"speaker":"三上委員","kind":"質問・要望","question":"そこのところは、やはりきちっと念頭に置いて、次に呼びかけがあったんだということは速やかに区のほうにも当人から報告もしてもらうということは当たり前のこととして、仮に重なって二つも、三つもかけ持ちでなんていうようなことにならないように、しっかりとやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問・要望","question":"５ページ目の資料にもあるように、むしろ個別に見たならば、安全性が確認されるということに尽きるんじゃないかなと思っているんです。この情報を得るように努力すべきだと、前回は要望として述べさせていただいたんですが、３カ月ごと情報提供ということになるんか尋ねました。","respondent":"小野（弘）副収入役","answer":"現在のところ、そのようになってありますけれども、指定金融機関とはかなり密接な連携を持ってありますので、今のご意見を踏まえまして、毎月というような形で要望してまいりたいと思います。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問","question":"逆の質問なんですが、指定金融機関に指定したがゆえにリスクが出るということもある得るんでしょうか。例えば、区に対する振り込みをストップするだとか、指定金融機関がゆえにリスクを負ってしまうということは出てくるんか尋ねました。","respondent":"小野（弘）副収入役、中尾根企画部長","answer":"国のほうも、そういった手続をとってまいりますので、こういった大手の金融機関が即破綻してしまうというような状況にはならないと思います。その間、２年間なりという形での手続を行うと思いますので、そのように考えてあります。 これがやっぱり、危ないからこれをどうするかというのは、やっぱり非常に難しい問題が現実的には出るだろうなと考えています。動きは、現実的に指定した後は…","id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"いろいろな事業に影響が出てくる要素もあろうかと思いますので、そちらのバンクに期待するのじゃなくて、適切な対応が求められると思うんです。これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"塚本委員","kind":"質問","question":"先ほどのところでの関連でお聞きしますけれども、どういう関係、関連地域でほかの銀行が強いんでしょうか。その２点、説明を求めました。","respondent":"小野（弘）副収入役","answer":"指定銀行については、１行のみということで決まってあります。","id":"exchange-046"},{"speaker":"塚本委員","kind":"質問","question":"お互いに競争しなさいということでペイオフが始まっているわけですから、そういう意味から言うと、もうそこに準備をしなければいけない。知恵を出し合って、他行もその準備を始めるわけですから、そういう習慣をつけなきゃいけないということを強く示しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"宮崎委員","kind":"提案","question":"４月１８日に、品川文化振興事業団の理事会と協議委員会があって、人事と財政運用の件について決められるという説明だったんですけれども、予算特別委員会のときに、理事長の表明がいろいろあったんですけれども、差し支えなければ…","respondent":"濱野助役","answer":"まだ、理事の方や協議委員会の方にも通知を出していないという段階ですので、ここで申し上げるのは差し支えがありますので、申し上げることはできません。","id":"exchange-048"},{"speaker":"宮崎委員","kind":"意見","question":"副理事長、幹事と、そこのところで区の４役が入っていたわけですよね。その辺のところは変わってくるということになりますかとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、もし今の質問で答えられないようだったら、それはしようがないです。","respondent":"濱野助役","answer":"先ほど申し上げたとおりです。","id":"exchange-050"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"指定金融機関にするかどうかぎりぎりまで待った銀行ですから、それの舌の根も乾かない四、五日後にこんなことが起きたわけですから。僕は温情派ですから、今回のことはシビアにとらえるべきだと思いますけれども、いかがか尋ねました。","respondent":"小野（弘）副収入役","answer":"すみません、説明不足で、言葉足らずで申しわけございませんでした。ですから、契約どおりに余分にお金を入れていただいたということです。","id":"exchange-051"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"ペイオフというのは、これから起きるかもしれないことに対する対応なんです。もう少しシビアに、さっき言ったように、担当をお考えいただきたいなと思いますので、再度、お考えを説明を求めました。","respondent":"中尾根企画部長","answer":"いくら契約があって９日までだといえ、不当利得になるんじゃないかというところまで検討した結果、そしてきちんとそれを精算しようと。今回、この本質だけはきちんとしておかなくちゃいけないという認識のもとにやったつもりですので、よろしくご理解をお願いしたいと思います。","id":"exchange-052"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201900?Template=document&Id=1576#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":39346,"voices":152}},{"id":"h14-20020416-13","meetingId":"h14-cm04","date":"2002年4月16日","dateIso":"2002-04-16","committee":"清掃・リサイクル特別委員会","time":"午後１時０５分～午後４時００分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"土井委員","kind":"意見","question":"今、電池という形で使われているものの３割程度、トータルのごみの中から言ったら微々たるものということになるわけです。そうすると、マンガン電池などの一定の、この法律自体がそういう形で二次電池のみをやることになった背景みたいなものはお分かりになりますかとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"これについての技術的な研究を進めていくべきなんですけれども、平成１３年４月の法定段階ではまだここまでうたうということはできなかったです。現実にそれが対応できる体制がとれていないといけないということで…","id":"exchange-001"},{"speaker":"土井委員","kind":"質問","question":"これまた事実でしょうけれども、そういうこともやっていくのではないかというふうなこともあったものですから、そういった疑いがあったわけです。私にとっては不満だけれども、そういう流れですから、ぜひＰＲ等をしっかりやっていただくようにお願いを申し上げます。","respondent":"中山清掃リサイクル課長","answer":"この辺の一次電池のリサイクルの義務というものを認識されていないというような危機感をまずして、今回冊子をつくったという経緯がありますので、これから区民の方への周知についてはいろいろな機会を捉えて充実していきたいと思います。","id":"exchange-002"},{"speaker":"中島委員","kind":"質問","question":"知っている方は、もうあからさまに言うのはあれかなと思うんですが、意外と一般区民の方はご存じないかと思うんです。広報とか、このマークを区民の方に印象付けるようなものがあったらいいんじゃないかなと感じたんですが、どうか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"ペットボトル等があるというふうに申し上げて、それが区民の方がすべてご存じかというと、まだ理解されていない面があるかと思います。ある機会を捉えて、その中で周知するとか、そういった全体のページ立てでない表示のことも含めた広報というのは考えていきたいと考えています。","id":"exchange-003"},{"speaker":"中島委員","kind":"質問","question":"この冊子が３,５００部ということですが、それ以上は増やさないということか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"まず、これは共通の部分ということなので、今回２３区で共同でつくりました。新たにこれをつくるという考えはないんですけれども、この辺の内容を抽出して、もう少し幅広くやっていきたいと考えております。","id":"exchange-004"},{"speaker":"中島委員","kind":"意見","question":"確かにこれをいっぱい配っても、逆に今度これがごみになってしまってはいけないなと思います。そういう部分のものが配られて、多くの人に周知されればいいかなと思いますので、どうぞとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"北野委員","kind":"質問","question":"そこにそれを取り扱う企業が入ってくるというところでは、メーカーから話し込んでいくという部分としてとれないんでしょうか。その辺についてお伺いします。","respondent":"中山清掃リサイクル課長","answer":"まずはこれを十分周知して、これは品川区だけではなく、今のところ新たにメーカーのリサイクルシステムと別にやるという考えはございません。今のところまだそれを立ち上げるという考えはございません。","id":"exchange-006"},{"speaker":"北野委員","kind":"質問・要望","question":"その後というのは、メーカーが電器店のところに荷物などを持ってきたときに、そのルートで回収して持っていくという形でいいんでしょうか。いろいろなものを買う部分では、結構難しいということになってしまうのか、そこのところをお伺いします。","respondent":"中山清掃リサイクル課長","answer":"会員が出資したお金の中で、以降の運搬業者のコストであるとか、プラントで再資源化するコストも捻出していくという方法をとっております。基本的には我が国のメンバーはこの中に集約されていっているですから、一言で言えば、メーカー負担でやっておるということです。","id":"exchange-007"},{"speaker":"北野委員","kind":"質問・要望","question":"ですから、網羅されるということでは、ぜひ進めていってほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問","question":"だから、一次電池と二次電池の違いというのが私自体ちょっと認識がなくて、電池というのは全部回収してほしいなと。水銀も使われていないということですけれども、実際にこれが埋め立てに行った場合に、環境を汚染するような物質は含まれていないんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"本会議でも部長のほうからお答えしたんですけれども、大田の第２工場というところで、一部資源回収をした後処理をしております。これも機会を見て、その辺の仕組みをご説明していきたいと考えています。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"埋め立てて、有害な重金属はないということでございましたけれども、焼却の段階での有害物の発生とか、その辺をお聞きしたい。そこの回収の中身とか、処理の方法がもし分かったら教えてほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"２３区のすべての工場は、大田第２工場においても、今後はこの辺の排ガスの濃度もさらに基準を厳しいものをクリアしていくように改善してまいります。処理状況を見ながら、合理的な仕組みになってくれば、品川区も考えていきたいとは思っているところです。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私自身も意識があまりなかったということでは、まず啓発のところから始まると思うし、いろいろな処理の仕方も、大勢の方の意見が聞ければ、また新しい道も開けるのではないかなと思うので、いろいろなところで検討をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"この冊子は確かに見やすいし、漫画などを入れて分かりやすいと思います。この冊子は２３区清掃協議会でつくっていただいている、４,０００万円といっても、その辺はどっちが払われているのか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"なかなか理解されていないという話が２３区の中で出まして、すべての区が共通課題としての認識がない限りはそれは共通でやるものではないと。この辺の周知が不十分というのは２３区も同様でしたので、品川区の年間１５０万円の分担金の中でこれを捻出してつくったです。","id":"exchange-012"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"念のため、区でなくて、協議会のほうですから、総予算はわからないと思うんですが、総予算としての単価的なものが分かれば教えてほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"申し訳ございません、総単価は今把握してございませんけれども、約９万部ということで、１部当たり１００円前後のところかなと思います。数十円というところじゃないかと思います。","id":"exchange-013"},{"speaker":"土井委員","kind":"意見","question":"２項道路みたいなところを通らないことには集められないということになりますから、それをどこかでやらなければいけないなという気がしました。ぜひこれからこの種のものを、近隣の皆さんのご理解を末永く得られるように、よろしくお願いをしておきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/930117?Template=document&Id=5660#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":13244,"voices":41}},{"id":"h14-20020416-16","meetingId":"h14-cm04","date":"2002年4月16日","dateIso":"2002-04-16","committee":"街づくり特別委員会","time":"午後１時０７分～午後２時４９分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"上山委員","kind":"質問","question":"最初にお尋ねしたいんですが、今のご説明ですと、中地区に対して半年ぐらいの遅れで進めていく方向のようにお話があったかと思うんです。この辺の違いですか、どうしたのかなという意味は、そこら辺どんな感じなんか尋ねました。","respondent":"南雲都市開発課長","answer":"権利者の方が今７割ぐらいという感じの状況ですので、今回は南地区については方針については、今後もう少し協議が整った段階で整備計画を立てるということを考えております。","id":"exchange-001"},{"speaker":"上山委員","kind":"質問・要望","question":"三お尋ねしたいんですが、もちろん開発の流れですから、ここにした意味合いがあったんでしょうか。今の改札口というんですか、南口というんですか、それが１点。","respondent":"南雲都市開発課長","answer":"今後、事業を進めていく中で変更になる部分があるんですが、これは建築基準法上の容積に関係する面積としますと８万２００m2です。住宅棟は２万１,９００m2、業務棟の大きいほうが５万１,０００m2、業務棟の小さいほうが７,７００m2というようになっております。","id":"exchange-002"},{"speaker":"上山委員","kind":"質問","question":"予算特別委員会でお尋ねした人もあったんですが、そんなに変わっていないと思いますから。保留床の問題で何度か質問をしたことがあったかと思うんですけれども、保留床の買い手などが決まったのかどうか、そこら辺をお尋ねしたいと思います。","respondent":"南雲都市開発課長","answer":"現在複数の不動産会社ですとか、生命保険会社と協議を行っておりまして、詰めの段階です。この都市計画の手続が具体的に動き出してきますので、今後、協議を行っております相手とも協議が進むだろうというふうに考えております。","id":"exchange-003"},{"speaker":"上山委員","kind":"質問・要望","question":"たまたま東口第３地区の事業をやっている方とお会いしましたら、まとまる形で、そこら辺はよく相談などを含めてやっていただきたい。これは要望だけにしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"宮崎委員","kind":"意見","question":"ここのところは具体的な中身はこれからだと思うんですけれども、平成１７年ぐらいの着工のようなお話だったんですけれども、実際はまだ絵になっていないんですけれども、どういう構想といいますか、お話しできる範囲でお願いいたしますとの意見を述べました。","respondent":"南雲都市開発課長","answer":"建物の配置ですとか、機能といいますのは、いろいろなパターンを検討している段階で、まだ確定しておりません。いろいろなパターンを検討しております。","id":"exchange-005"},{"speaker":"川西委員","kind":"質問","question":"隣が第二日野小で、区立一貫校の計画が同時並行で進んでいく時期になりますけれども、その辺との連携はどこの機関で今後行うのか。準備組合と、区の所管課との関係はどういうふうになるのか、説明を求めました。","respondent":"南雲都市開発課長","answer":"今回の２棟ですけれども、こちらの土地開発課のほうでそういう調整を行いますので、都市計画課と教育委員会のほうと調整を行って進めたいというふうに考えております。","id":"exchange-006"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、平成１７年度を一応目途に置きますと、平成１４年度は準備組合を設立したばかりで準備段階ということになりますと、具体的な都市計画は平成１５年ぐらいにはでき上がってくるかなというふうには思いますが、そんな感じでいいか尋ねました。","respondent":"南雲都市開発課長","answer":"これから協議ですので、はっきりしませんけれども、スムーズにいったとして、平成１５年度中ぐらいにはこの二丁目第２地区の都市計画設計ができるというふうに考えております。","id":"exchange-007"},{"speaker":"上山委員","kind":"意見","question":"自由通路の係わりがちょっとわからないんですけれども、大崎駅東口の駐輪場をつくっているところに階段がありましたね。あそこを最近取り払ったようですけれども、エレベーターを付けるというような話をされたのか、ちょっとそこのところをお願いしますとの意見を述べました。","respondent":"南雲都市開発課長","answer":"これにつきましては、東口の地下化の部分で、前は階段があったところが、今は除去されておりますが、道路から西側の敷地の中にエレベーターと階段を設置するということで、現在その工事中です。","id":"exchange-008"},{"speaker":"川西委員","kind":"質問","question":"山手通りのほうから、跨線橋といいますか、自由通路にどういうように入るのですか。ちょっと説明をお願いいたします。","respondent":"南雲都市開発課長","answer":"この図面で言いますと、下のほうに新大崎勧業ビルディングというのがありますが、これが今のニューシテイでございまして、この上のほうの部分がありますので……。","id":"exchange-009"},{"speaker":"川西委員","kind":"意見","question":"簡単に言いますと、いわゆるニューシテイ側から自由通路を使う人には１本線でとても具合がいいけれども、山手通りから上がる人は階段か、ニューシテイ側のほうに行って、エレベーターに入るか、今あるエレベーターに乗って、上へ１回入って、こちらに渡るということですねとの意見を述べました。","respondent":"南雲都市開発課長","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"この提言の中身というよりも、「はじめに」の最後のところで、「本区はもとより関係行政機関等に対し提言する」と書いてあるんですけれども、具体的に、例えばこれをまとめたら、こういうふうに提出したいとか、こういうふうな動きをしたいとかというのがあったら、お伺いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"石田委員","kind":"質問・要望","question":"４ページに、1)で、地権者等の全員合意に相当するものが求められるので。基本的にこれについては「地権者等の住民合意が求められるので」というぐらいにとどめておかないと、これが非常に足かせになっていくと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問","question":"ここは、今のような表現ということになると、そこのところがかなり質的に変わってくるような気がするものですから。今回は、こういう立場で「全員合意」としたほうがいいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"藤田委員","kind":"質問","question":"それぞれの考え方がありますので、全員合意とすると足かせになってしまうなというふうに感じています。ですから、この文面をもうちょっと不安のないように変えたほうがいいんじゃないかなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"本田委員","kind":"質問","question":"いろいろな整備も含めて出てくるわけですから、いろいろな経緯がありますけれども、基本的には全員合意で物事が進めば一番いいわけです。それはこれまでの議論を通じて出てきたことですから、私はこの文章で、含みを持たせた文章になっていていいなと受け止めているんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"藤田委員","kind":"質問","question":"６ページなんですけれども、「地区計画を進めるにあたり基準緩和等のメニューを増やす等合意しやすい制度にする」というふうにすれば、もっとストンといくんじゃないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"藤田委員","kind":"質問・要望","question":"４ページの1)は、「全員合意に相当するものが求められるので」を切って、「地区計画を定めていくためには、地権者等のより多くの合意を得るための新たな方策と計画決定のための基準が必要である」と。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"宮崎委員","kind":"意見","question":"どういう姿勢を持っていくのかということの問題だと思うので、私はちょっとこだわるんですけれども、「全員合意」というのを目指していくと。具体的な部分はいろいろあるにしても、この文言というのは、私としてはこだわるんですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"藤田委員","kind":"質問","question":"一方では全員合意なんだけれども、一方ではより多くで、文面がちぐはぐなものになってしまう。ですから、すっとしたほうがスムーズにいくんじゃないかと思っているんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"本田委員","kind":"質問","question":"文章をどういうふうにするかということですから、今藤田委員が言われたことについては、それはそれで構わないというふうに思うんです。「地権者等の住民合意を得るための」云々というふうにしたほうがいいかなというふうに、思いも含まれているというふうに思うんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"石田委員","kind":"質問・要望","question":"「地区計画を定めていくためには」でも「進めるにあたり」でも、そこはお任せいたしますが、「地権者等の住民合意が求められるので、合意を得るための新たな方策と計画決定のための基準が必要である」。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"本間委員","kind":"意見","question":"５ページのあたりを見ているんですけれども、抽象的な文になっていますけれども、よくまとめていただいなというふうに思っております。意見ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"藤田委員","kind":"意見","question":"しかるべき段階で関係機関にもの申すのはいいと思いますけれども、もう少し成り行きを見ていかないと、いかがなものか。関係機関に働きかけるというだけでは、慎重に扱ったほうがいいんじゃないかというふうに私は思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"上山委員","kind":"意見","question":"１年間かけてこういう提言をつくったわけで、例えばこれを区だけでは、ちょっとどうなのかなと思います。結果がどうなるかわかりませんけれども、お伝えするというのが、特別委員会としてやるべきことではないのかなと思うんですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"本田委員","kind":"質問・要望","question":"改めてこうやって見ると、そういう点で議会サイドからこういうようなまとめが出たわけですから、あまり聞かなかったことを都は聞くんだと思うんです。制度とか、法律とか、そういうものの改正を求めるような面から見た場合はどうなのか。","respondent":"山室住宅指導担当部長","answer":"区の理事者側にご提言いただくのは当然のこととして、次のステップとして、国・都に対してどういうやり方でこの趣旨を伝えていくか。先ほど藤田委員のほうからもありましたとおり、それに沿って理事者側はご用立てといいますか、準備を整えるということになろうかと思います。","id":"exchange-025"},{"speaker":"本田委員","kind":"意見","question":"それは国や都の動き、的外れにならないとも限りませんがから、その辺はちょっとよそを見ながらというようなことをたしかやりましたね。とりあえずはこれを議長を経て、区のほうに出して、次の街づくり特別委員会の中で状況を見ながら対応したらどうかと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"三上委員","kind":"質問","question":"ですから、本区はもとより、関係行政機関等にということになってくると、ある意味では変なことになりかねないというふうに思っている面もあるんです。国、それはそれでいいのかわからないですけれども、そこらあたりがまだ検証されていないというふうに思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"宮崎委員","kind":"意見","question":"今まで密集市街地に取り組んできたんですが、なかなか進まない。その中で品川区議会は品川区議会の問題意識でありますから、これは動いているときに出すということが、私はいいんじゃないかなというふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"横山委員","kind":"質問","question":"さっき藤田委員が言われたように、当委員会の提言ですから、提言先がなければ意味がない。その提言先をどこにするかというと、行政の中にこういったものを勉強された部分で調整してほしいということでいいんだと思うんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"本間委員","kind":"質問・要望","question":"自覚している時期もあったんですけれども、素直に１年間の成果をまとめて、しかるべきときにそれぞれの関係機関に要望を伝えていく。あるいは要望といいますか、手だてをしていくというような形でどうかなというふうに私自身は考えたんですが、意見を述べさせていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"川西委員","kind":"意見","question":"とりあえず委員会の１年間の活動として、区の理事者側に提言を出す。これはどうしても区の中では解決できない、委員会活動としてはそういう意見を汲み上げようということに割り切るということがいいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"三上委員","kind":"質問","question":"その中で「提言」という言葉を使った委員会の報告書というのは今までにありますか。それをこの委員会だけが「提言」という言葉でやってということでよいのか、ちょっと私は感じたものですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"宮崎委員","kind":"確認","question":"これで文言を修正していこうということで確認して、その後、提言をどういうふうに扱うかということで、今のような話だったと思うんです。扱いをどうするかで意見が違うところで、ちょっと話が違うんじゃないかと思いますので、そこのところは意見を言っておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"本田委員","kind":"質問","question":"ああしたらというような議論をやってきたわけですから、私は提言という言葉を使って文章全体が組み立てられているからいいんじゃないかと思うんです。これはこのままで。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"石田委員","kind":"質問・要望","question":"いろいろ付けられると思うんですが、私が理解できないのかどうかわからないんですけれども、防災生活圏と切り離していますね。１４棟などになっているけれども、もしそういう意味であれば、付けてほしいと求めました。","respondent":"浜脇住環境整備課長","answer":"もう１枚あったほうがよろしゅうありますので、資料につきましては、付けることも可能です。例えば公園・広場３カ所と書いてあるだけで、生活圏のほうの図面をつくりますが、若干資料の番号が変更になります。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/690912?Template=document&Id=6228#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":24000,"voices":125}}]);
